window.HARDTRP.receive("34769",[[42765,"2026-06-13T12:36:32",9,"🏰 РУИНЫ ДРАКОНЬИХ ХРЕБТОВ ⛰\n\nПостоянная локация. Ответственный — \"Hard Master\". Земли, которые никому не принадлежат. Край руин, опасностей, беззакония и охотников за сокровищами.\n\n— Основные особенности местности: горы и предгорья, густые леса, руины различных эпох и культур, пещеры и подземные комплексы.\n\n— Преимущества локации. Наличие данной локации открывает доступ к предысториям «Археолог» и «Антрополог».\n\nЗелёным на карте отмеченна примерная зона локации.",34769,null],[42812,"2026-06-13T13:49:25",9,"🗺Основная деятельность🔭\n\nАрхеологи и Антропологи могут организовывать экспедиции, набирая в них как игроков, так и наёмных помощников (НПС).\n\nЕсли вы не разу не были в составе экспедиции ваш персонаж не сможет никак попасть на эту локацию самостоятельно впервые. Исключения: вы Археолог/Антрополог или вас привёт тот кто уже бывал в локации.\n\nЭкспедиции могут заниматься: поиском и исследованием руин, изучением древних культур, поиском сокровищ и артефактов, геологической разведкой, охотой и выживанием в дикой местности.\n\nРекомендованная длительность экспедиции 2-4 реальных дня.\n\nОсновной упор сделан на нарративную и ролевую составляющую.\n\n— Если вы одновременно участвуете в экспедиции своим персонажем и выступаете ведущим события, ваш персонаж получает до 20 опыта за день исследований.\n\n— Персонажи игроков получают от 20 до 200 опыта за качественную ролевую игру. Другие способы получения опыта во время экспедиции отсутствуют, опыта за боевую составляющую нет. Не достаточно просто потратить день на экспедицию чтобы получить больше минимума требуется реальный факт ролевой составляющей путешествия/изучения/исследования и отыграша а не просто присутствие персонажа.\n\n— Каждый день (реальный) экспедиции определяется броском d100 (обращайтесь к ответственному за локацию). При желании можно остаться на уже открытой локации и не совершать новый бросок. День экспедиции = реальный день персонажа и ваш в локации во время которого нельзя воспользовпться механикой простоя или создания если нет подходящих условий. \n\nВо время исследований важны/делается упор на: ремесленные навыки, способности исследователей/учёных/персонажей, внимательность следопытов, боевые навыки если избежать опасности не удалось.\n\nНе факт, что экспедиция принесёт награду — многое зависит от удачи. Однако существует шанс обнаружить артефакты обычной или необычной редкости, а также повреждённые уникальные предметы, их заготовки или древние компоненты.\n\n❗ ВАЖНО ❗\n\nНаниматься на работу в экспедиции могут только игроки и нпс наёмники.\n\nЕсли для работы требуется ремесленник, он получает оплату одновременно как ремесленник и как наёмник.\n\nОбычные наёмники могут выполнять функции разнорабочих, носильщиков, охраны, добыичиков и прочиз за достойную плату.\n\nНа территории Руин Драконьих Хребтов отсутствуют налоги, однако цены на товары остаются стандартными из-за постоянной опасности и дефицита ресурсов.\n\nЕсли отдельно не указано иное, торговых точек на территории локации — нет. Участникам экспедиций придётся рассчитывать на собственные запасы, навыки и добытые ресурсы.\n\nНа данный момент это вся доступная информация о локации. Остальные разделы/интересные места/события/карты/находки/прочее будут оформленны позднее.",42765,null],[42814,"2026-06-13T13:49:58",9,"Запас",34769,null],[42815,"2026-06-13T13:50:00",9,"Запас",34769,null],[42816,"2026-06-13T13:50:02",9,"Запас",34769,null],[42817,"2026-06-13T13:50:03",9,"Запас",34769,null],[42818,"2026-06-13T13:50:04",9,"Запас",34769,null],[42819,"2026-06-13T13:50:06",9,"Запас",34769,null],[42820,"2026-06-13T13:50:08",9,"Запас",34769,null],[42821,"2026-06-13T13:50:09",9,"Запас",34769,null],[42822,"2026-06-13T13:50:10",9,"Запас",34769,null],[42823,"2026-06-13T13:50:11",9,"Запас",34769,null],[42824,"2026-06-13T13:50:12",9,"Запас",34769,null],[42825,"2026-06-13T13:50:13",9,"Запас",34769,null],[42826,"2026-06-13T13:50:14",9,"Запас",34769,null],[42827,"2026-06-13T13:50:16",9,"Запас",34769,null],[42828,"2026-06-13T13:50:17",9,"Запас",34769,null],[42829,"2026-06-13T13:50:18",9,"Запас",34769,null],[42830,"2026-06-13T13:50:18",9,"Запас",34769,null],[42831,"2026-06-13T13:50:19",9,"Запас",34769,null],[42832,"2026-06-13T13:50:20",9,"Запас",34769,null],[42833,"2026-06-13T13:50:21",9,"Запас",34769,null],[42834,"2026-06-13T13:50:22",9,"Запас",34769,null],[42836,"2026-06-13T13:50:48",9,"Запас",34769,null],[42837,"2026-06-13T13:50:49",9,"Запас",34769,null],[42838,"2026-06-13T13:50:51",9,"Запас",34769,null],[42840,"2026-06-13T13:50:52",9,"Запас",34769,null],[42841,"2026-06-13T13:50:53",9,"Запас",34769,null],[42842,"2026-06-13T13:50:54",9,"Запас",34769,null],[42843,"2026-06-13T13:50:55",9,"Запас",34769,null],[42844,"2026-06-13T13:50:56",9,"Запас",34769,null],[42845,"2026-06-13T13:50:57",9,"Запас",34769,null],[42846,"2026-06-13T13:51:56",9,"//На этом вся информация о локации оконченна. Собирайте команды в других локациях или \"обсуждениях квестов\"",34769,null],[42848,"2026-06-13T13:52:03",9,"ХХХХХХХХХХХХХХХХХХХХХХХХХХ",34769,null],[43349,"2026-06-13T21:25:42",9,"https://youtube.com/playlist?list=PLPnarMn7NyaUnFjAwPuC8askzdkUCAMn9&si=hWQ0fi2TiohtJNYA\n\n//Лень музыку подбирать, просто держите мой плейлист.",34769,null],[48865,"2026-06-15T19:32:30",10,"@H_Kruz тут",34769,null],[48867,"2026-06-15T19:32:47",8,"/roll 1d100",34769,null],[48869,"2026-06-15T19:32:59",10,"/r d100",34769,null],[48871,"2026-06-15T19:33:19",9,"// @Heyhoft @H_Kruz Fantomas мы будем тут, с каждого из вас д100",34769,null],[48876,"2026-06-15T19:34:57",8,"Юнус 94\nЯ 37\nИнсайд 58",34769,null],[48877,"2026-06-15T19:35:03",40,"/а, сорян",34769,null],[48878,"2026-06-15T19:35:11",40,"/ну 94 пусть будет",34769,null],[48879,"2026-06-15T19:35:13",9,"//Юн пусть перекинет тут",34769,null],[48880,"2026-06-15T19:35:20",40,"/бля ладно",34769,null],[48881,"2026-06-15T19:35:21",9,"//Ну или 94 пох",34769,null],[48882,"2026-06-15T19:35:25",40,"/ок",34769,null],[48884,"2026-06-15T19:37:31",8,"Типа так, но с 2 короткими мечами, и края плаща связаны верёвочкой",34769,null],[48886,"2026-06-15T19:42:28",40,"/а эт Хорхе пусть будет",34769,null],[48887,"2026-06-15T19:43:14",9,"*Несколько дней заняло путешествие через горы. Сейчас герои шли по узкой горной тропинке, а внизу стелился горный туман, пропасть.*\n\nХардинт: — Ступайте осторожно, лучше не спешить.\n\n*Вас уже окружали остатки цивилизации, древние, покрытые мхами. А ещё... руны на камнях которые казалось бы сюда притащили в другое время. Эти валуны стояли на местах у самых обрывов.*",34769,null],[48888,"2026-06-15T19:43:23",9,"//Ваш проводник и Археолог — Хардинт",34769,null],[48889,"2026-06-15T19:45:18",10,"*Гений , бомж , не филантроп - Багровый*",34769,null],[48890,"2026-06-15T19:46:25",9,"//Отыгрываем, чё, всё в вашем распоряжении)",34769,null],[48891,"2026-06-15T19:46:34",8,"– Прикольно, что тут уже туристы постарались. Значит, выживают здесь вполне *шагает с лёгкой подозрительностью во взгляде, но сейчас её будто развеселило*",34769,null],[48892,"2026-06-15T19:47:16",10,"*с любопытством осматриваю руны * - интересно",34769,null],[48893,"2026-06-15T19:47:16",40,"-руны.. это же не письмена погибшей цивилизации? У них другие буквы были",34769,null],[48894,"2026-06-15T19:48:05",8,"(Похоже на драконий?)",34769,null],[48895,"2026-06-15T19:48:18",9,"*Плетясь по каменным тропам и остатках ступеней молодой Археолог осматривал некоторые из них, его заинтересовали те валуны что явно сюда притащили недавно. Он попытался их осмотреть раз остальных это заинтересовало, но ничего не понял.*\n\n— Это не те руны которые мне известны.",48892,null],[48896,"2026-06-15T19:49:03",9,"Хардинт — Думаю, это не старые письмена. Те частично смог бы прочесть.",48893,null],[48897,"2026-06-15T19:49:33",9,"*Руны чем то похожи, но совсем другой стиль.*",48894,null],[48898,"2026-06-15T19:49:51",9,"//Вопрос, кто из персонажей контактировал с друидами в прошлом?",34769,null],[48899,"2026-06-15T19:50:00",8,"/не мой/",34769,null],[48900,"2026-06-15T19:50:48",10,"//точно не я",34769,null],[48901,"2026-06-15T19:51:05",10,"-давайте запишим руны и найдем позже того кто их знает",34769,null],[48902,"2026-06-15T19:51:21",8,"/очевидно, руны не дварфские, да?/",34769,null],[48903,"2026-06-15T19:52:13",9,"Хардинт — Неплохая идея. — *Согласился.*",48901,null],[48904,"2026-06-15T19:52:16",10,"/r 1d20+6  *пытаюсь вспомнить что-то с помощью магических знаний о рунах*",34769,null],[48906,"2026-06-15T19:53:02",9,"//Магию применяешь?",48904,null],[48907,"2026-06-15T19:53:23",10,"//ну магические знания просто о рунах типа как история но магией",34769,null],[48908,"2026-06-15T19:53:35",9,"//Броски модете выкинуть, главное владения и отыгрыш",34769,null],[48909,"2026-06-15T19:54:10",9,"//Ну, ты контактировал с друидами? Они в книгах свои знания не пишут)",48907,null],[48910,"2026-06-15T19:55:19",9,"*Ищет у сеья куда бы записать но у него всё в заметках и все они важны... как же не хватает простой бумаги.*\n\n— У кого-то есть уголёк и листы пергамента?",48903,null],[48911,"2026-06-15T19:55:43",10,"-я знаю только общий и небесный. Раз никто не понимает давайте соберём знания об этих рунах и их местоположении. Кажется это важно. Давайте пойдем дальше ведь путешествие только началось * пытаюсь понять куда пойти*",34769,null],[48912,"2026-06-15T19:56:38",9,"*Тропа лишь одна, и герои и так по ней шли. В узких горных грядах часто некуда свернуть.*",48911,null],[48913,"2026-06-15T19:56:48",10,"*магический мастеровой. Создаю маленький артефакт который записывает статические изображения*",34769,null],[48914,"2026-06-15T19:56:53",8,"– Скажу одно: это не дварфский и не драконий. Из минусов: бумаги у меня нет",34769,null],[48915,"2026-06-15T19:57:35",10,"-с помощью моей безделушки * показываю странную фоторамку* можно заснять это место",48913,null],[48916,"2026-06-15T19:57:59",9,"*Валун вспыхивает светом на мгновение и руны горят. Потом следующий через 500 футов, и следующий и следующий и так вверх по тропе в сторону куда шли герои исчезая из поля зрения.*",48913,null],[48917,"2026-06-15T19:58:26",10,"- похоже на путеводные знаки.",34769,null],[48918,"2026-06-15T19:58:40",9,"Хардинт — Чёрт, мне жто не нравится.\n\n//Вот щас да, бросок на магию + - кстати. Это было заклинание",34769,null],[48919,"2026-06-15T19:58:52",10,"//17 выкидывал считай",34769,null],[48920,"2026-06-15T19:59:40",9,"//Ты понимаешь что это обнаружение магии и кажется оно куда-то передало тот факт что здесь использовалась магия, или кому-то... никто кроме тебя ещё не понял что случилось",48919,null],[48923,"2026-06-15T20:00:35",10,"-хм теперь кто то знает что мы тут. Давайте больше не колдовать",34769,null],[48924,"2026-06-15T20:00:51",9,"Хардинт — Ты понял что это было?",48923,null],[48927,"2026-06-15T20:00:58",8,"/он заснял руны?/",34769,null],[48928,"2026-06-15T20:01:06",10,"-Обнаружение магии и передача информации",34769,null],[48929,"2026-06-15T20:01:33",8,"Как сигнальные костры. Значит, адресат наверху *встревоженно*",34769,null],[48930,"2026-06-15T20:01:33",10,"-но теперь мы можем снять все что нам интересно. Хоть какой то плюс",34769,null],[48931,"2026-06-15T20:02:07",9,"Хардинт — ... мне это не нравится. Прийдётся идти обратно и в обход, не хочу рисковать. Неизвестно кого мы можем встретить.",34769,null],[48933,"2026-06-15T20:03:13",9,"//Ну чё, не слушайте меня если что, это лишь мнение перса, бещ всс он все равно один не пойдёт, что либо, какие либо решения/идеи в ситуации ^^",34769,null],[48934,"2026-06-15T20:04:01",8,"- Адресат нас заметил, но не факт, что намеревается прибить, не так ли?",34769,null],[48935,"2026-06-15T20:04:13",10,"- или мы можем пойти по сигналам и увидеть куда он отправлен",34769,null],[48936,"2026-06-15T20:04:42",8,"Или адресат помер, а сигнальная схема осталась",34769,null],[48937,"2026-06-15T20:05:00",10,"- скорее всего. Но главное что там что-то точно есть",48936,null],[48938,"2026-06-15T20:05:47",40,"-Я предлагаю держать дистанцию 10 футов (3 метра) друг от друга. Чтобы нас в случае засады не накрыли всех одновременно, хвост колонны должен быть из самых сильных и у них будет время перестроиться и дать отпор",34769,null],[48939,"2026-06-15T20:06:14",10,"- согласен . Я могу пойти вперёд",34769,null],[48940,"2026-06-15T20:06:18",9,"*Кадется ваш проводник слишком остороден и рисковать не хочет особо, но всё же, ему тоде стало интересно... он никогда это не признает вслух.*\n\nХардинт — В обход и вправду будет слишком долго. — *Он вздохнул.* — Можем рискнуть раз вы настаиванте.",34769,null],[48941,"2026-06-15T20:06:45",40,"-Я за тобой",48939,null],[48942,"2026-06-15T20:06:53",8,"– Тогда вынуждена констатировать, что я ловкая, а не сильная *встаёт ближе к переду*",34769,null],[48943,"2026-06-15T20:07:14",10,"*прикрываясь щитом иду по сигналам осматриваясь*",34769,null],[48944,"2026-06-15T20:07:37",40,"*Хорхе тоже держит щит в руках а не на спине*",34769,null],[48945,"2026-06-15T20:07:53",8,"*держит в руках два меча*",34769,null],[48946,"2026-06-15T20:08:01",9,"*Хардинт достаёт щит и тоже идёт, ближе к середине. Его кажется определили замыкающим.*",34769,null],[48947,"2026-06-15T20:08:17",9,"//Восприятие, чем больше рещультат тем лучше",34769,null],[48948,"2026-06-15T20:08:43",10,"/r 1d20+4",34769,null],[48950,"2026-06-15T20:08:46",9,"/roll 1d20+6 Хардинт смотрит воба",34769,null],[48952,"2026-06-15T20:08:55",8,"/roll 1d20+3",34769,null],[48954,"2026-06-15T20:09:33",40,"/r d20+4+2",34769,null],[48960,"2026-06-15T20:14:25",9,"*Зоркие глаза старого вояки, слух как у собаки, нюх как у орла. Возле какого-то куста он замечает остатки скелетов. После показалось что кто то бормочет впереди. Слышно как чьи-то большие ноги подвинули несколько камней и те скатились. Звуки шагов эхом отражаются от гор и все ближе. Хорхе первым заметил это.*",34769,null],[48961,"2026-06-15T20:15:58",10,"*шепотом*- слышите? Тише. Давайте аккуратно посмотрим",34769,null],[48962,"2026-06-15T20:16:11",10,"-Кто хорош в скрытности?",34769,null],[48963,"2026-06-15T20:16:29",9,"*По узкой тропе кто-то идёт прямо к нам и в темпе.*",34769,null],[48964,"2026-06-15T20:16:47",8,"- Предположим, я *шёпотом*",48962,null],[48965,"2026-06-15T20:16:55",10,"*кидаю калтропы на пути * - отходим",34769,null],[48966,"2026-06-15T20:17:32",8,"(Я могу оборотиться в скелета? Не могу, понятно)",34769,null],[48967,"2026-06-15T20:17:54",9,"//?)",48966,null],[48968,"2026-06-15T20:18:11",40,"//можешь если щас нас разъебут",34769,null],[48969,"2026-06-15T20:18:40",8,"/пытаюсь спрятаться/",34769,null],[48970,"2026-06-15T20:19:01",40,"//я правильно понимаю, на нас спустили валуны сверху?",34769,null],[48971,"2026-06-15T20:19:06",9,"//Опиши, чем логичнее тем больше бонус к броску дам)",48969,null],[48972,"2026-06-15T20:19:44",9,"*Слышится что кто-то идёт и похоже ногами наступил на несколько камней. Кто-то крупный.*",48970,null],[48973,"2026-06-15T20:19:56",8,"*укрывшись в серый плащ и пригнувшись, пытаюсь слиться с камнем и кустом, изменив рост на минимальный полуросличий*",34769,null],[48974,"2026-06-15T20:20:18",9,"//Ну, за плащ +д6 докинь ещё",48973,null],[48975,"2026-06-15T20:20:43",8,"(Скрытность добавить?)",34769,null],[48976,"2026-06-15T20:20:51",10,"*прячусь за услупом и смотрю на ловушку с калтропами*",34769,null],[48977,"2026-06-15T20:20:52",40,"*шепот*\n-противник. нас не засекли. в укрытие...\n\nХорхе держа щит уходит за ближайший валун, взглядом контролирую тропу по которой ожидается двигающаяся цель",34769,null],[48978,"2026-06-15T20:21:00",9,"//Бросок на скрытность и с д6 лишним)",34769,null],[48979,"2026-06-15T20:21:18",8,"/roll 1d20+5",34769,null],[48981,"2026-06-15T20:21:26",8,"/roll 1d6",34769,null],[48983,"2026-06-15T20:21:33",8,"15",34769,null],[48984,"2026-06-15T20:21:33",10,"/r 1d20+2+1d6",34769,null],[48986,"2026-06-15T20:21:43",9,"*Хардинт прячется вместе с Багровым.*",48976,null],[48987,"2026-06-15T20:21:56",9,"//А ты без бонуса, у неё прос о предмет помогает)",48984,null],[48988,"2026-06-15T20:22:08",10,"17//",34769,null],[48989,"2026-06-15T20:22:36",9,"/roll 1d20+5+1д6 у меня боевой приём засада",34769,null],[48991,"2026-06-15T20:24:28",9,"*Вскоре в темпе по склону не спускается а словно сбегает четырёхрукий тролль. Большой как маленький гигант, слюни его текут, он за добычей, явно... Он облачон в друидические одеяния которые ни с чем не спутаешь.*",34769,null],[48992,"2026-06-15T20:25:00",9,"/roll -d20+2 восприятие с помехой ведь он сука бежит",34769,null],[48994,"2026-06-15T20:25:04",10,"*жду пока не упадет на калтропах*",34769,null],[48995,"2026-06-15T20:26:03",10,"//спас 15 ловкости",34769,null],[48996,"2026-06-15T20:26:25",40,"пытаюсь остаться за своим валуном незамеченным, не хочу губить местную фауну без необходимости",34769,null],[48997,"2026-06-15T20:26:42",9,"*Троль наподходе замечает некоторые из вас, еговзгляд точно ловит девушку под кустом и Багрового, он ускоряется ещё быстрее.*\n\n*Хардинт достаёт и поджигает факел, он кое что знает о троллях.*",34769,null],[48999,"2026-06-15T20:27:21",9,"— Угрргуувврввг гувррррр — *Что-то на языке великанов от тролля.*",34769,null],[49000,"2026-06-15T20:27:22",10,"*кидаю масло в тролля замечая факел*",34769,null],[49001,"2026-06-15T20:27:46",9,"//Такс, ребят, минуту, ваши лействия и подготовку опишите, вы понимаете что он вас видит)",34769,null],[49002,"2026-06-15T20:27:49",8,"/а если он зла не хотел?/",34769,null],[49003,"2026-06-15T20:28:07",9,"//Анализ кинь",49002,null],[49004,"2026-06-15T20:28:23",8,"/roll 1d20+4",34769,null],[49006,"2026-06-15T20:28:39",9,"*Сожрёт и не подавится.*",49005,null],[49007,"2026-06-15T20:29:02",8,"*достаю мечи и превращаюсь в Кайсу*",34769,null],[49008,"2026-06-15T20:29:21",10,"*и даю себе псевдожизнь*",49000,null],[49009,"2026-06-15T20:29:41",8,"*делаю знак пальцем \"вжик по горлу и указка на тролля\", видный остальным",34769,null],[49010,"2026-06-15T20:30:20",9,"*Тролль бежит и с всего разгону стаёт ногой на калтропы.*\n\nТроль — Агагагагрррргггг!!!",34769,null],[49011,"2026-06-15T20:31:19",9,"*Здоровяк падает на землю возле самого обрыва, хватается за ногу. Орёт так что заложило уши из-за эха.я*\n\n//Действия",34769,null],[49013,"2026-06-15T20:32:18",10,"*кинул масло ему в лицо* - пожигаай",34769,null],[49014,"2026-06-15T20:32:37",8,"(Есть камень побольше возле меня?)",34769,null],[49015,"2026-06-15T20:32:41",9,"*Хардинт кидает в Тролля факел.*",34769,null],[49016,"2026-06-15T20:32:47",9,"//Вещде",49014,null],[49017,"2026-06-15T20:33:17",8,"*кидаю, целясь ему в голову, чтобы он упал с обрыва*",34769,null],[49018,"2026-06-15T20:33:51",40,"*ну так как у меня таки есть щит, вероятно надо мне выйти на первую линию, а не срать за валуном.* - подумал старик, тем более уже усрался в таверне.\n\nСтарик хватает бурдюк с винным уксусом вместо оружия и с поднятым щитом выходит на тропу перегорождая дорогу зверю.\n\nв планах старика ебнуть уксусом по лицу тролля сбив его обоняние и отбить аппетит (ну короче попадание уксуса в глаза и иные слизистые вызывает ожог, если это можно посчитать как урон кислотой буду рад. собственно уксус я реально купил на прошлом квесте и уксус это кислота по своей сути)",34769,null],[49019,"2026-06-15T20:36:51",9,"*Здоровяк загорается, его друидическая мантия сгорает и вянет в огне, он кричит и уже был готов встать как ему в глаза плеснули едкой жидкостью. Он закрыл лицо руками, это был войс бульканием и сопением, следом ему прилетело камнем. Маленький великан ошатнулся от последнего, сделал шаг в сторону, но там небыло твердой почвы.*\n\n*Огромный троль на ваших глазах кубарем летит вниз с очень крутого склона.*",34769,null],[49020,"2026-06-15T20:37:22",10,"-хорошо летит*смотрю как далеко вниз он упал*",34769,null],[49021,"2026-06-15T20:37:50",8,"– Сам не упади, а то было бы нелепо *окрикивает из места около куста*",34769,null],[49022,"2026-06-15T20:38:17",10,"-не переживай товарищ*мягко улыбаюсь * я умею летать немного",34769,null],[49023,"2026-06-15T20:38:42",40,"-Да смилуется над твоей душой Ильматер. Покойся с миром, - Хорхе вернулся в построение чтобы продолжить дорогу",34769,null],[49024,"2026-06-15T20:39:30",9,"*Ниже туман, но судя по звуку тот падал ооочень долго разогнавшись до невероятной скорости... даже если и остался жив, то едва и заживать прийдётся всему.*\n\n//Короче, там прям с горы скотился, ебать сколько дробящего шо писец, вы даж сами не спуститесь туда потому что круто очень",49020,null],[49025,"2026-06-15T20:40:02",8,"– Он мог быть не один, нам бы идти осторожнее",34769,null],[49026,"2026-06-15T20:41:00",10,"- или один. Тролли вроде не живут кучей",34769,null],[49027,"2026-06-15T20:41:04",9,"Хардинт — Похоже он и расставил эти валуны. — *Услышав коментарий Кайсы ток кивнул, она высказала его мысль.*",34769,null],[49029,"2026-06-15T20:43:01",9,"Хардинт — Думаю нужно идти. Тропа слишком узкая, как бы нам бы самим не упасть по неосторожности.",34769,null],[49030,"2026-06-15T20:43:38",8,"*держится ближе к стене, пока идёт",34769,null],[49031,"2026-06-15T20:43:43",10,"-видимо. Давайте дальше",34769,null],[49032,"2026-06-15T20:43:50",10,"-только тихо",34769,null],[49033,"2026-06-15T20:45:22",9,"*Около часа пути и путники видят пещеру, та неприметна, если бы не огромный подвинутый валун. Его явно постоянно двигали чтобы это место было неприметно сред груды камней, но Тролль узнал о добыче и как-то должен был выйти.*",34769,null],[49034,"2026-06-15T20:46:15",8,"*видны следы ловушек, али тролль слишком туп?* делаю упреждающий жест рукой",34769,null],[49035,"2026-06-15T20:46:20",40,"-Сможет толкнуть?",34769,null],[49036,"2026-06-15T20:46:53",9,"*Видны следы следов тролля из пещеры тролля. Никаких ловушек, просто он закрывался внутри валуном.*",34769,null],[49037,"2026-06-15T20:47:33",8,"– Очевидных подлянок не видно, или я слепая крыса. Давайте я впереди",34769,null],[49038,"2026-06-15T20:47:41",10,"-давайте вместе навалился и уберем камни",34769,null],[49039,"2026-06-15T20:48:13",8,"(Вход закрыт?)",34769,null],[49040,"2026-06-15T20:48:14",40,"видит ли Хорхе следы недавнего присутствия людей. следы, костры, кости людей, стрелы и болты арбалетов (троли такое не изготовят) короче че нибудь",49036,null],[49041,"2026-06-15T20:48:37",9,"*Там достаточно большой проход.*\n\nХардинт — Держите, я не слишком силён. — *Он достаёт лом, камень атлетикой с преимуществом если мешает.*",34769,null],[49042,"2026-06-15T20:49:26",9,"*Снаружи выглядит как груда камней с пещерой за ними и один большой что закрывал её.*",49040,null],[49043,"2026-06-15T20:49:40",9,"//Пролезть можно",49039,null],[49044,"2026-06-15T20:50:12",10,"- к чему лезть ? Давайте уберем камни и зайдём",34769,null],[49045,"2026-06-15T20:50:13",8,"– Лучше убрать, да. А то обвалится при выходе",34769,null],[49046,"2026-06-15T20:50:56",9,"//Кто кинет атлетику с преимуществом чтобы отодвинуть камни, ведь у него одолженный лом?)",34769,null],[49047,"2026-06-15T20:51:14",10,"//я не очень силен )",34769,null],[49048,"2026-06-15T20:51:32",8,"/я тоже. Может, вместе?",34769,null],[49049,"2026-06-15T20:52:10",9,"//Бля, у меня конечно +4 но я расчитывал на кого то из вас, ладно. Дед должен быть силён, наверно.",34769,null],[49050,"2026-06-15T20:52:30",8,"/или лезть на свой страх и риск, раз у всех ловкость/",34769,null],[49051,"2026-06-15T20:53:48",9,"//Мне или вы? С преимуществом от лома",34769,null],[49052,"2026-06-15T20:54:15",8,"*ок, попробую*",34769,null],[49053,"2026-06-15T20:54:38",9,"//сложность  15",34769,null],[49054,"2026-06-15T20:54:57",8,"/roll 1d20-1",34769,null],[49056,"2026-06-15T20:55:05",8,"/roll 1d20-1",34769,null],[49058,"2026-06-15T20:55:18",8,"*смотрит униженно*",34769,null],[49059,"2026-06-15T20:55:21",9,"/roll +d20+4 хардинт понял что остальные хиловаты для работы и решил сам всё равно приклбченцы постоянно лезут в пещеры за сокровищами",34769,null],[49061,"2026-06-15T20:55:40",10,"- я творец а не силач* пожимаю плечами*",34769,null],[49062,"2026-06-15T20:56:07",8,"– Спасибо, Хардинт",34769,null],[49063,"2026-06-15T20:56:43",10,"*заговор свет* - ну пойдем внутрь?",34769,null],[49064,"2026-06-15T20:56:49",9,"*После некоторые стараний валун поддаётся и сдвигается немного прокатившись, на место его вернуть будет очень сложно.*\n\nХардинт — Работать руками тоже иногда полезно. — *Но это не значит что ему нравилось работать руками.*",34769,null],[49065,"2026-06-15T20:57:42",8,"Да *кивает и входит*",49063,null],[49066,"2026-06-15T20:58:05",40,"Хорхе смотрит куда их занесло и че тут из *интерьера* так сказать",34769,null],[49067,"2026-06-15T20:59:46",9,"*Внутри было темнос вонь стояла неймоверная вонь. Троль тут и жил и ел и срал, глаза слезились.*\n\nХардинт — Кх кх — *Хорошо что он всегда носит платок.*\n\n*Внутри много скелетов и остатков добычи, даже какие-то кости людей и приключенцев судя по остаткам снаряжения.*",34769,null],[49068,"2026-06-15T21:00:36",10,"-как же тут воняет. Впрочем что ещё ожидать от троля",34769,null],[49069,"2026-06-15T21:00:43",8,"– Можешь подсветить, и мы осмотрим скелетиков? Ради приятных мелочей не жалко и руки замарать",34769,null],[49070,"2026-06-15T21:01:43",40,"Хорхе хочет понять погибшие были искатели приключений которые сами приходили и заёбыли тролля или троль выходил на охоту и ловил невинных гуляк (грибников, путешественников, прочих мирных жителей)",34769,null],[49071,"2026-06-15T21:02:05",10,"*быстро делаю с помощью инструментов вентилятор и вливаютв него магию* - должно помочь от вони",34769,null],[49072,"2026-06-15T21:02:24",10,"*мощный магический вентилятор*",34769,null],[49073,"2026-06-15T21:02:35",9,"*Похоже на экспедиции приключенцев и археологов как вы. Больше никто сюда не ходит.*",49070,null],[49074,"2026-06-15T21:02:53",9,"//Ищите добычу?)",34769,null],[49075,"2026-06-15T21:03:25",8,"/естественно/",34769,null],[49077,"2026-06-15T21:04:13",10,"*освещаю пещеру светом*",34769,null],[49082,"2026-06-15T21:09:35",9,"// распишитесь:\n\n— Боевой посох\n— 3 кинджала\n— Кирка \n— Фонарь\n— Скимитар\n— Тёплый грибной плащ\n— 8 факелов\n— желещный горшок\n— 2 фляги масла\n—  5 стеклянных бутылок\n— Набор травника\n— Зелье лечения\n— Непрозрачный голубой кварц (10 зм.)\n— Малахит с чередующимися светло-зелёными полосами (10 зм.)\n\n\nНа говне тролля растут какие-то жёлтые цчеты в полной темноте, пахнут лекарствами немного разбавляя вонь.\n\n— На 20 золотых материалы для зелий.",34769,null],[49085,"2026-06-15T21:11:26",9,"*Большая часть вещей от приключенцев либо сломанна либо сгнила. Троль даже пожевал чью-то кольчугу так что её наверное пришлось бы собирать обратно по звеньям, а кинджалы лежали в одном месте, были ему как зубочистки.*",49082,null],[49086,"2026-06-15T21:12:06",9,"*На стене так же висел плащ поросший грибами, от него веяло теплом.*",49082,null],[49087,"2026-06-15T21:12:41",9,"//Потом поделите еси чё",34769,null],[49088,"2026-06-15T21:12:49",10,"*ч помощью набора травника пытаюсь понять чё за растения *",49082,null],[49089,"2026-06-15T21:13:43",9,"*Названия ты не знаешь но это редкие лекартвенные травы которые растут ток в помёте тролля.*",49088,null],[49090,"2026-06-15T21:14:17",10,"*собираю как умелый травник* - давайте потом все поделим после возвращения",34769,null],[49091,"2026-06-15T21:14:42",8,"– Да, давайте по рюкзакам пока распихаем, я как минимум попрошу фонарь",34769,null],[49092,"2026-06-15T21:16:00",9,"Хардинт — На награду не претендую, знаково могу взять кинджал. — *Всё же он и позвал всех сюда.*\n\n//Да и я веду, так что не над мне тут награду большую)",34769,null],[49093,"2026-06-15T21:16:35",10,"-дед возьми зелье",34769,null],[49094,"2026-06-15T21:16:53",10,"- я травы возьму )",34769,null],[49095,"2026-06-15T21:17:23",9,"//Там ещё два красивых камня по 10 зм чистыми)",34769,null],[49096,"2026-06-15T21:18:05",40,"-пасиб за зелье",34769,null],[49097,"2026-06-15T21:18:38",8,"- Можно взять кварц? Тогда, кроме фонаря, ни на что не претендую",34769,null],[49098,"2026-06-15T21:19:09",10,"- ну тогда я возьму накидку. Посмотрим может я научусь делать такие же",34769,null],[49099,"2026-06-15T21:19:17",40,"*Дед встает на охранение, нельзя расслабляться и чесать яйца, ибо мы на вражеской территории.*",34769,null],[49100,"2026-06-15T21:19:43",9,"//Всё разобрали?",34769,null],[49101,"2026-06-15T21:20:10",8,"/запускаешь плесень, и готово😁/",49098,null],[49102,"2026-06-15T21:20:17",10,"/ угу остальное что не взяли продадим из общего пула. Фонарь , кварц , зелье и плащ взяли",34769,null],[49103,"2026-06-15T21:20:50",9,"//Агась, оке, я тогда вместо кинджала возьму кирку лучше",34769,null],[49104,"2026-06-15T21:21:10",8,"/ты ж археолог, надо/",34769,null],[49105,"2026-06-15T21:21:30",9,"*Хардинт присмотрел добротную кирку себе. Что ему весь хлам, а это модет пригодиться.*\n\n//Да и нет кирки как раз",34769,null],[49106,"2026-06-15T21:21:38",10,"*изучаю плащ * - какая странная безделушка. Надо точно ее исследовать.* Оглядываюсь* - вы ребята устали? Если да то можно немного устроить тут привал и дальше исследовать",34769,null],[49107,"2026-06-15T21:22:33",8,"– Я хотела бы утром по другому делу отправляться, так что пас, извините",34769,null],[49108,"2026-06-15T21:22:48",9,"*Далее по пути, крутая тропинка превратилась в небольшую площадку. Здесь стояли стены старых строений без крыш что скорее всего сгнили.*",34769,null],[49109,"2026-06-15T21:23:04",9,"//Всё?",49107,null],[49110,"2026-06-15T21:23:17",10,"- я думаю мы за сегодня осмотримся и вернёмся в город",49107,null],[49111,"2026-06-15T21:23:23",8,"/не всё, просто завтра не сыграю/",34769,null],[49112,"2026-06-15T21:23:40",10,"- не переживай мы сюда для начала пришли осмотреться",34769,null],[49113,"2026-06-15T21:24:05",9,"//Мы щас ток играем, и я почти закончил. Думал 3 провести подряд но меня ток на одну хватило, простите",34769,null],[49114,"2026-06-15T21:24:09",10,"//вы с фантомасом идете завтра на один квест хард )",34769,null],[49115,"2026-06-15T21:24:28",10,"/тогда хватит на сегодня?",34769,null],[49116,"2026-06-15T21:25:03",9,"Хардинт — Это хорошее место, здесь модет быть что-то интересное. Осмотритесть ищите что приглянётся.",49108,null],[49117,"2026-06-15T21:25:16",8,"*ищет*",34769,null],[49118,"2026-06-15T21:25:23",9,"//С каждого восприятие на поиск интересной добычи и заканчиваем",34769,null],[49119,"2026-06-15T21:25:35",8,"/roll 1d20+3",34769,null],[49121,"2026-06-15T21:25:51",40,"/roll 1d20+4+2",34769,null],[49123,"2026-06-15T21:25:55",10,"//ща пишу",34769,null],[49124,"2026-06-15T21:27:04",9,"*Ты находить глиняную статуэтку козы, Хардинт подсказывает что знает кому продать такую за несколько золотых.*\n\n// Полученна \"Глиняная статуэтка гороной козы\" (чистая стоимость 4 золотых)",49120,null],[49125,"2026-06-15T21:27:06",10,"*Загораюсь божественной энергией и излучаю свет. Отрастаюсь прозрачные крылья и горящими глазами осматриваю все*",34769,null],[49126,"2026-06-15T21:27:15",10,"/r 1d20+4",34769,null],[49128,"2026-06-15T21:28:33",10,"//просто хотел использовать сияющую душу на последок",34769,null],[49129,"2026-06-15T21:29:00",8,"/не оправдывайся, нельзя винить за желание попонтоваться/",34769,null],[49130,"2026-06-15T21:29:31",10,"//очень эффектный понт ибо такой хуйни ваши персонажи ещё не видели. Буквально ангел",34769,null],[49131,"2026-06-15T21:29:55",9,"*Твой взгляд сверху почти ничего не смог увидеть но была одна вещь что привлекла внимание, нечто от чего веяло магией. Это была неприметная бнсформенная стекляшка.*\n\n//Получено:\n\n\"Осколок магической силы\". Расходникс если сломать его сломавший восстановит ячейку 1-го уровня.",49127,null],[49132,"2026-06-15T21:30:15",40,"|меня не забудь)",49122,null],[49133,"2026-06-15T21:30:49",9,"Хардинт — Серафим. — *Вспоминает тексты из кое каких исторических книг, но не любопытствует слишком сильно.*",49125,null],[49134,"2026-06-15T21:31:45",8,"– Ага, прикольно. Но твоё умение творить эффективные бляшки лучше",34769,null],[49135,"2026-06-15T21:31:52",9,"*Дед находит чъё то захоронение под квадратным камнем. Там лежит скелет воина с украшенным мечом и рядом кувшин с монетами.*\n\n//Грабишь могилу?",49122,null],[49136,"2026-06-15T21:32:08",10,"-о чем ты ? Я Багровый. Обычный человек. Разве не все так умеют ?",49133,null],[49137,"2026-06-15T21:32:34",8,"(Фонарь закрытый, кстати?)",34769,null],[49138,"2026-06-15T21:32:57",9,"Хардинт — Нет. Лучше не показывай это на людях, за такое могут и убить или пленить.",49136,null],[49139,"2026-06-15T21:33:14",9,"//Неа, я бы написал закрытый",49137,null],[49140,"2026-06-15T21:33:29",8,"И нимб слегка очевидный, не находишь?",34769,null],[49141,"2026-06-15T21:34:04",9,"//Бля, а у него прям нимб!?)",49140,null],[49142,"2026-06-15T21:34:07",10,"-Пленить? Странно. Хорошо",49138,null],[49143,"2026-06-15T21:34:14",10,"Пиздец какой//",49141,null],[49145,"2026-06-15T21:34:58",9,"//Ну, нимб может ещё магия конечн какая. Но крылья и остальное уже на уровне сверхъестественного)",34769,null],[49146,"2026-06-15T21:36:07",10,"//все кто что надо взял хард бери остальное просто)",34769,null],[49147,"2026-06-15T21:36:11",9,"*Хардинт раскащал где и кому лучше продать статуэтку глиняной кощы чтобы за неё дали 4 золотых а не купили как безделушку.*",34769,null],[49148,"2026-06-15T21:36:34",8,"*за кадром продам этим козофетишистам*",34769,null],[49149,"2026-06-15T21:36:51",10,"- ты и правда опытный исследователь. Буду рад ещё попутешествовать с тобой",49147,null],[49150,"2026-06-15T21:37:04",9,"//Просто сумму пощитай общую того что вам не надо и продайте скупщику получив 30% от этого",49146,null],[49151,"2026-06-15T21:37:53",9,"Хардинт — На этот раз я думаю мы дальше не пойдём. Не ожидал встретить тролля ещё на тропе.",49149,null],[49152,"2026-06-15T21:38:14",10,"- хорошо что взяли масло и ловушки",49151,null],[49153,"2026-06-15T21:38:21",10,"- боюсь мы бы не победили его",34769,null],[49154,"2026-06-15T21:39:20",9,"— Согласен. Живучие твари, а этот ещё и необычный. Слышал ток о троллях с двумя руками и они небыли магами или друидами.",34769,null],[49155,"2026-06-15T21:40:07",8,"– Может, дитя имбридинга, поэтому и туповатый, и четырёхрукий?",34769,null],[49156,"2026-06-15T21:40:29",9,"*Хардинт решает разместить небольшой лагерь, чтобы приготовить всем отобедать.*\n\n//-2 рациона, честно за поход и вам советую)",34769,null],[49157,"2026-06-15T21:41:19",8,"*ок, тоже свой ест. Очень аккуратно*",34769,null],[49158,"2026-06-15T21:41:19",10,"-они не шибко умные",49155,null],[49159,"2026-06-15T21:41:27",9,"*Качает головой пока разжигает кострище и ставит котелок.*\n\n— Боюсь, все тролли туповаты. Как по мне он был просто очень голоден в этот момент.",49155,null],[49160,"2026-06-15T21:41:37",10,"*сажусь и ем со всеми*",49156,null],[49161,"2026-06-15T21:42:45",9,"//Деда ток ждём, разграбит ли он могилу",34769,null],[49162,"2026-06-15T21:42:57",10,"-берите факелы (8 штук) и масло (2шт) . Их нет смысла продавать",34769,null],[49163,"2026-06-15T21:43:08",10,"-берите каждый понемногу и все",34769,null],[49164,"2026-06-15T21:43:37",9,"//Мне кирка, остальное делите)",34769,null],[49165,"2026-06-15T21:44:20",8,"*берёт флягу масла* – Остальное мне не надо",34769,null],[49166,"2026-06-15T21:45:20",9,"// @H_Kruz реши разграбил ли могилу, а там просто отпишу если времени нет",49135,null],[49167,"2026-06-15T21:45:29",10,"/сколько зелий я могу сделать из трав?",34769,null],[49168,"2026-06-15T21:45:43",9,"//Владеешь набором травника?",34769,null],[49169,"2026-06-15T21:46:41",10,"/да",34769,null],[49170,"2026-06-15T21:47:06",10,"//по-моему где-то 2 обычных",34769,null],[49171,"2026-06-15T21:47:08",40,"|инет отвалился сори\n\nНет Хорхе не оскверняет чужие захоронения",49135,null],[49172,"2026-06-15T21:48:14",9,"*Решив неграбить могилу воина Хорхе больше особо ничего приметного не нашёл.*",49171,null],[49173,"2026-06-15T21:48:55",9,"//Создание обычного зелья лечения не требует рецепта, создаётся за 17,5 зм в материалах",49170,null],[49174,"2026-06-15T21:49:21",9,"//Ебашь одно зелье короче)",34769,null],[49175,"2026-06-15T21:49:24",10,"//ну значит 1",34769,null],[49176,"2026-06-15T21:49:54",40,"помолился за упокой похороненного. взял факел и сел жрать",34769,null],[49177,"2026-06-15T21:50:34",8,"(а как фонарь называется на днд.су? Дистанцию посмотреть бы)",34769,null],[49178,"2026-06-15T21:50:40",9,"*После короткого отдыха и обеда Хардинт беседовал с новыми знакомцами. После, собрал всех в обратный путь.*",34769,null],[49179,"2026-06-15T21:50:52",10,"-интересно было",34769,null],[49180,"2026-06-15T21:50:56",10,"- надо повторить",34769,null],[49181,"2026-06-15T21:51:24",8,"– *сосредоточенно* Люблю смотреть на огонь. Этот и орал ещё, занятно, хотя и жалко немного",34769,null],[49182,"2026-06-15T21:52:21",40,"-без орала тут мне",34769,null],[49183,"2026-06-15T21:52:28",40,"-извращенцы блять...",34769,null],[49184,"2026-06-15T21:52:33",9,"— Я не против зайти глубже, но, надо подготовиться. В будущем рад расчитывать на вас. — *Хардинт улыбнулся под платком.* — Без вашей смекалки и командной работы мы могли бы разве что попытаться убежать пока тролль доедал одного из нас.",34769,null],[49185,"2026-06-15T21:52:44",40,"-он не против зайти глубже блять...",34769,null],[49186,"2026-06-15T21:52:55",40,"-пойду поем в другом месте, - слух деда стал подводить",34769,null],[49187,"2026-06-15T21:53:17",10,"-согласен. Троль да ещё и в руинах. Это только начало. Кто знает что ещё тут есть",49184,null],[49188,"2026-06-15T21:53:20",8,"– Или у кого-то извращённое понимание действительности)",34769,null],[49190,"2026-06-15T21:55:07",8,"– Я иногда захожу в \"Кабаний клык\", так что вероятность увидеться есть",34769,null],[49192,"2026-06-15T21:55:37",10,"- я там живу. Так что заходите",49190,null],[49193,"2026-06-15T21:56:14",9,"— Тоже часто там бываю. Присмотрел там одно дельце, недавно вывеска появилась.",34769,null],[49195,"2026-06-15T21:56:28",8,"– Работаешь там?",49192,null],[49197,"2026-06-15T21:57:01",10,"-Нет нет я делаю зелья и чиню вещи",34769,null],[49198,"2026-06-15T21:57:09",10,"- Иногда ввязываюсь в авантюры",34769,null],[49199,"2026-06-15T21:57:50",10,"-Я неожиданно появился на краю карнавала фей. Без памяти и они мне даже имя дали. Вот он закончился и я перебрался к Торнвальду",34769,null],[49200,"2026-06-15T21:58:08",8,"– Завтра отряд на поиски дочки одной отправляется, не хотелось бы присоединиться?",34769,null],[49201,"2026-06-15T21:58:31",10,"-Нет спасибо. У меня уже есть дело интересное в одном странном доме",34769,null],[49203,"2026-06-15T21:59:18",8,"– Что ж, успешной работы)",34769,null],[49204,"2026-06-15T21:59:32",9,"*Хардинт задумался услышав о карнавале фей.*\n\n— Говорят что туда нельзя расказывать как попасть иначе фейское проклятие. Хотелось бы побывать на нём, но туда должен провести кто-то кто знает как попасть на него.",49199,null],[49205,"2026-06-15T21:59:44",10,"//На 4 человека",34769,null],[49206,"2026-06-15T21:59:44",10,"30 зм камни чистыми\n20 зм материалы для зелий\n\nнабор травника 5зм\n скимитар 25\n3 кинжала 6зм\nбоевой посох 2 см\n5 стекляных бутылок 10 зм // 30% = 14 зм. \n50+14=64 зм общее",34769,null],[49207,"2026-06-15T21:59:56",10,"//по 16 каждому",34769,null],[49208,"2026-06-15T22:00:15",40,"-Когда нибудь видеть проявление Бога в живую. его магию или сработавшую молитву или что то подобное",49204,null],[49209,"2026-06-15T22:00:16",9,"//Это шо",34769,null],[49210,"2026-06-15T22:00:30",10,"- Да нет его больше. Я и не знаю как туда попасть. Говорю же закрылся",49204,null],[49211,"2026-06-15T22:00:32",9,"//А да, похоже.",34769,null],[49213,"2026-06-15T22:00:49",9,"//Отлично + -",49206,null],[49214,"2026-06-15T22:00:52",8,"Феи странные, не всех любят...",49204,null],[49215,"2026-06-15T22:01:08",10,"-Нет к сожалению или к счастью не видел. Я еще только начал свой новый путь",49208,null],[49216,"2026-06-15T22:01:29",9,"— Карнавал появляется раз в несколько лет, надеюсь в следующий раз удасться попасть на него.",34769,null],[49217,"2026-06-15T22:01:49",9,"//По факту — раз в год реального",34769,null],[49218,"2026-06-15T22:02:05",10,"- Там очень необычно. Советую посетить если найдешь",34769,null],[49219,"2026-06-15T22:02:33",9,"Хардинт — Спасибо. Может именно ты туда меня и проведёшь. Буду рад.",49218,null],[49220,"2026-06-15T22:02:48",10,"-Я попрошу для тебя приглашение",49219,null],[49221,"2026-06-15T22:03:24",8,"- В некоторых пьесах феи слишком высокомерные, а в сказках есть доля правды. Однако это был бы интересный новый опыт",34769,null],[49223,"2026-06-15T22:03:52",10,"- Главное не причиняйте им зла и не обижайте их. А то не отвяжутся",34769,null],[49224,"2026-06-15T22:05:34",9,"//Опыт короче:\n\nХаридинт — 20\n@H_Kruz — 80 дед пропадает часто\nFantomas — 120\n@Heyhoft  — 130 покрасовался крылатый\n\n//Это аналог простоя, так что профит как по мне хорош и добыча и опыта немного, всем спасибки ^^",34769,null],[49225,"2026-06-15T22:06:24",10,"//Было интересно и нарративно) а главное Хард запиши Хардингу подаренные фотографии знаков и их расположение",34769,null],[49226,"2026-06-15T22:06:48",10,"-Держи Хардинг * Передаю фотки*- Если узнаешь их значение буду рад если поделишься за кружкой эля",34769,null],[49227,"2026-06-15T22:06:51",9,"//Ох, надо найти того кто владеет друидическим языком",34769,null],[49228,"2026-06-15T22:08:08",9,"//Хардинт:\n\n20 опыта\n\nКирка\n\n16 золотых\n\nЗаписки с друидическими знаками на камнях",34769,null],[49229,"2026-06-15T22:08:35",10,"* Фоторамка в которую влита магия . Содержит 360 градусное фото места с камнями и рунами *",34769,null],[49230,"2026-06-15T22:08:45",10,"//считай безделушка",34769,null],[49231,"2026-06-15T22:10:24",9,"*Взял фотографии.*\n\n— Спасибо, подозреваю нужен друид. Они неохотно делятся знаниями.",49226,null],[49232,"2026-06-15T22:10:43",9,"//Ну, как вам в целом? Стоит того? Сходили бы ещё как-то?)))",34769,null],[49233,"2026-06-15T22:11:05",10,"//Мне по кайфу. Нарратив и чил",34769,null],[49234,"2026-06-15T22:11:20",9,"//Тож кайфанул",49233,null],[49235,"2026-06-15T22:11:39",8,"/интересно и приятно, хотя и специфично, ввиду нарративности, а не \"кидай инициативу\". Разминка в отыгрыше перед завтрашним квестом",34769,null],[49236,"2026-06-15T22:12:19",9,"//Ну, вы прям тролля скинули. Я сам не сразу сообращил что он может упасть просто)",34769,null],[49237,"2026-06-15T22:13:01",8,"/он мог быть летающим мутантом/",34769,null],[49238,"2026-06-15T22:13:05",9,"//Спасибо за приятный вечер ❤️",34769,null],[49239,"2026-06-15T22:13:30",9,"//Он и полетел! Только вниз 😏",49237,null],[49241,"2026-06-15T22:13:54",8,"/вот я был, и вот меня не стало/",34769,null],[49242,"2026-06-15T22:14:58",9,"//Помните что тролли живучие. Регенятся от всего кроме кислоты и огня. Этот мог и выжить, но это мы узнаем или никогда не узнаем)",34769,null],[49243,"2026-06-15T22:14:59",8,"/но можно делать троллей-изобретателей-Карлсонов/",34769,null],[49247,"2026-06-15T22:34:46",10,"//Хорошо что он горел)",49242,null],[50237,"2026-06-16T08:26:44",40,"/ Hard а может дед вернуться в таверну?",34769,null],[50241,"2026-06-16T10:33:35",9,"//Ещё вчера с этого момента)",49224,null],[79624,"2026-06-28T15:34:07",10,"Fantomas Hard  * Спустя какое то время Багровый отводит вас на место где они остановились в прошлый раз и показывает вам камни друидов, Но надолго не останавливаясь и предупредив не использовать магию он повел вас вверх по следу камней и дальше по неизведанной даже для него тропе. Достав карту он указывает область и показывает её вам* - Где то тут возле пещеры тролля мы остановились в прошлый раз и по собранным мною данным гдето в этой местности находится лес. Думаю если мы пойдем в ту сторону то точно не пропустим его",34769,null],[79626,"2026-06-28T15:35:15",8,"– Ага, сложно не заметить лес...",34769,null],[79629,"2026-06-28T15:36:39",9,"*Несёт на себе внушительный рюкзак, возможно из-за парня вы останавливались лишний раз.*\n\n— Может стеклянный лес это выражение такое. Интересно будет посмотреть как оно на самом деле.",34769,null],[79630,"2026-06-28T15:36:53",10,"*И правда через несколько часов ровно в полдень вы обнаружили огромный лес. Стоя на входе в него вы слышите музыку которая создается ветров проходящим через стеклянные листья*",34769,null],[79632,"2026-06-28T15:37:36",9,"*Присвистывает, впервые такое видит.*",79631,null],[79633,"2026-06-28T15:37:58",8,"*стоит молчаливо с восхищением во взгляде*",34769,null],[79634,"2026-06-28T15:38:28",10,"-Довольно красиво. Я не так много мест видел еще , но это точно выделяется на фоне",34769,null],[79635,"2026-06-28T15:38:32",9,"//Сейчас хардинт в платке кстати",34769,null],[79636,"2026-06-28T15:39:02",10,"*Быстро делаю безделушки респираторы* - вот держите. Правда они скоро пропадут , но хватит на путешествие",34769,null],[79639,"2026-06-28T15:39:56",9,"— Думаешь листья из настоящего стекла или просто прозрачны и не имеют пигмента? — *Спрашивает он пока надевает свою защиту для лица.*",79634,null],[79640,"2026-06-28T15:40:12",8,"/чтобы не порезаться, остаётся в шёлковых перчатках/",34769,null],[79641,"2026-06-28T15:41:01",8,"– Спасибо *все ещё отвлечённо из-за красоты леса* *надевает*",79636,null],[79642,"2026-06-28T15:41:24",10,"-Так вот предлагаю аккуратно идти и хм незнаю. Кто-то из вас умеет обращаться с музыкальными инструментами? такое ощущение что лес в гармонии , но мне не хватает знаний.",34769,null],[79644,"2026-06-28T15:42:14",8,"– Я могу на виоле сыграть, если мы не хотим скрываться *рада, что может быть полезной*",34769,null],[79645,"2026-06-28T15:43:09",9,"— Я умеб играть только на ремесленных инструментах. — *Покачал головой.* — Но могу обучиться в течении доя или несколтких сносной игре. Правда не хотелось бы тратить время.\n\n//Черта быстрый студент",79642,null],[79647,"2026-06-28T15:44:08",10,"-Думаю это будет не лишним. Наш новый товарищ может помочь тебе в обучении не так ли ?",79645,null],[79648,"2026-06-28T15:44:33",8,"– Могу рассказать по пути, мне нетрудно!",34769,null],[79649,"2026-06-28T15:44:46",9,"— Снова видеть ваше выступление. Почту за честь. — *Немного наигранно поклонтлся. Молодой ещё и пытается веселиться.*",79644,null],[79650,"2026-06-28T15:45:41",10,"*стою в стороне и осторожно оглядываюсь ища врагов*- Давайте приступайте. Я посторожу",34769,null],[79651,"2026-06-28T15:45:42",9,"— Не смогу так быстро, но постараюсь взять пару уроков.",79648,null],[79653,"2026-06-28T15:45:53",8,"– Премного благодарю. *манерно и элегантно делает ещё более глубокий поклон (согнув ноги, отставив заднюю и приподняв полы туники)* *вот-вот рассмеётся*",79649,null],[79654,"2026-06-28T15:46:05",10,"/r 1d6",34769,null],[79656,"2026-06-28T15:46:28",10,"/roll 1d6",34769,null],[79658,"2026-06-28T15:46:34",9,"*Немного смущён (не в романтическом смысле), он так ищысканно кланяться не умеет.*",79653,null],[79659,"2026-06-28T15:46:38",10,"//сцука ладно",34769,null],[79661,"2026-06-28T15:47:34",10,"//Вы опишите своё обучение или мы приступим к изучению?",34769,null],[79662,"2026-06-28T15:48:20",9,"//так, ну быстрый студент так не работает если нужна музыка, то прийдётся потратить продолжительный и у нас есть щапасной инструмет?, но в теории на действие \"помощь\" хватит и пары часов",34769,null],[79663,"2026-06-28T15:48:53",8,"/нет запасного, но на время обучения даёт свою виолу/",34769,null],[79665,"2026-06-28T15:49:17",10,"//Магия монтажа и действие помощь помогут всем. Считайте у нас привал после путешествия",34769,null],[79666,"2026-06-28T15:49:18",9,"*Хардинт думает.*\n\n— Ммм, виола всего одна...",34769,null],[79668,"2026-06-28T15:49:53",8,"– Ничего, я тебе показывать буду и давать виолу, чтобы ты повторил",34769,null],[79670,"2026-06-28T15:50:14",8,"*обучает азам, типа нот, длительностей и пр.*",34769,null],[79673,"2026-06-28T15:51:38",9,"— Хммм, дай мне немного времени.",34769,null],[79675,"2026-06-28T15:52:28",9,"*Находит палку какую нить и вырещает Флейту инструментами резчика по дереву.*",34769,null],[79676,"2026-06-28T15:52:43",10,"*Во время привала Багровый быстро смешал несколько химикатов. Что-то взорвалось в мензурке и он довольно кивнул* - Чтож держите на всякий случай зелье. Выпейте его перед боем , оно действует только 10 минут. \\\\Устойчивость. Выпивший получает бонус +1 к КД на 10 минут.",34769,null],[79678,"2026-06-28T15:54:29",9,"— Я не смогу полноценно обучиться и лира одна. Буду на поддержке. — *Улыбается показывая почти готовую флейту, простую, сделал сам. Лишь бы играра.**",34769,null],[79680,"2026-06-28T15:55:00",10,"-Думаю кому то из вас стоит возглавить этот путь потому что я лучше буду идти в хвосте и охранять вас в случае нападения. *Достаю щит , надеваю тяжелые чешуйчатые доспехи и расправляю плечи*",34769,null],[79681,"2026-06-28T15:55:12",8,"– Если так, потерпите десять минут *шутливо, ибо считает свою игру хорошей* *пока Хардинт вырезает флейту, играет мелодию, похожую на журчание ручейка* +4 временных хп всем",34769,null],[79682,"2026-06-28T15:55:38",8,"/на это ответила/",79676,null],[79683,"2026-06-28T15:55:55",9,"//Инструменты имба. Чего-то нет? Кто сказал что этого нет?))",34769,null],[79684,"2026-06-28T15:56:05",10,"*Подхожу к Харди* - Чем ты бьешься ?",34769,null],[79685,"2026-06-28T15:56:38",9,"*Показывает спрятанные кинджалы и дротики пож желетом.*",79684,null],[79686,"2026-06-28T15:57:10",9,"*Кинджала всего два.*\n\n— Воин правда из меня такой себе.",34769,null],[79687,"2026-06-28T15:57:27",9,"//Разрешишь использовать помощь слуг?",34769,null],[79688,"2026-06-28T15:57:45",10,"*Дотронувшись до кинжала провожу по нему руками и на секунду нимб и глаза вспыхивают золотым светом и затухают* - Будь аккуратнее с ним. Я его усилил //инфузия +1",34769,null],[79689,"2026-06-28T15:59:21",10,"//У кого будет зелье +1 к кд решите и пойдем)",34769,null],[79690,"2026-06-28T15:59:29",9,"*Кивает и говорил вслух.*\n\n— Красный — Помощь господину Багровому. Синий помощь мне. Зелёный — помогай леди.",79688,null],[79691,"2026-06-28T16:00:26",10,"*смотрю на гомункулов* - Вижу ты только начал постигать ту же профессию что и у меня. Думаю у тебя все получится. Продолжай в том же духе",79690,null],[79692,"2026-06-28T16:00:31",8,"/не думаю, что мне сильно поможет 13 кд вместо 12/",79689,null],[79693,"2026-06-28T16:00:36",9,"*Три крошечных конструкта размером чуть больше яйца, почти с кулак вылетели из рюкзака и заняли места на плечах и шее со спины готовые помогать.*",34769,null],[79694,"2026-06-28T16:00:57",10,".",79680,null],[79697,"2026-06-28T16:02:34",8,"/Хард может в авангарде (уклоняться, естественно), или слабоват?/",34769,null],[79699,"2026-06-28T16:02:52",9,"//Ну, думаю девушка первая не пойдет, тогда и зелье мне, у меня слабак с 12 кд",34769,null],[79701,"2026-06-28T16:03:12",8,"/мы два слабака, поздравляю",34769,null],[79702,"2026-06-28T16:03:33",8,"/я без зелья, но в середине",34769,null],[79703,"2026-06-28T16:04:12",9,"*Хардинт идёт вперед головый уклоняться, зелье он принял ьез вопросов. Раз они решили играть на инструментах, кое как играет на флейте, но скорее как подлержка основному музыканту.*",34769,null],[79706,"2026-06-28T16:04:58",10,"Обычная чаща резко обрывается, уступая место застывшему чуду. Перед героями возвышаются хрустальные стволы, чьи стеклянные листья звенят на ветру. Они кажутся хрупкими, но таят в себе смертельную остроту. Это место — результат древней магии огромной силы, испытывающей каждого, кто осмелится ступить под его прозрачные своды.\n«Хрустальный перезвон заполняет воздух, когда вы делаете первый шаг. Под ногами — ковер из чистейших стеклянных осколков. Каждое движение рождает музыкальную ноту, эхом разносящуюся по прозрачной чаще. Лес слушает вас... и вы должны звучать с ним в унисон».",34769,null],[79708,"2026-06-28T16:05:43",8,"*пробую понять основную мелодию леса, динамику мелодии*",34769,null],[79711,"2026-06-28T16:06:39",10,"//выступление прокинь",34769,null],[79712,"2026-06-28T16:06:51",8,"/roll 1d20+5",34769,null],[79714,"2026-06-28T16:07:43",9,"*Хпрдинт тоже пытается поддердать зарождающейся мелодию звуками флейты.*",34769,null],[79715,"2026-06-28T16:07:48",9,"//Помощь!",34769,null],[79716,"2026-06-28T16:07:55",10,"//Ты понимаешь что весь лес звучит в определенном ритме и вы должны его придерживаться чтобы пройти безопасно",79712,null],[79719,"2026-06-28T16:08:39",8,"*играю в этом же ритме максимально высокими звуками, типа \"си\", но не интенсивно",34769,null],[79720,"2026-06-28T16:08:41",10,"//Групповая проверка выступления общ сложность 20",34769,null],[79721,"2026-06-28T16:08:59",8,"/ох",34769,null],[79722,"2026-06-28T16:09:08",10,"//Оба киньте выступление и я применю магию сложения",34769,null],[79723,"2026-06-28T16:09:19",8,"/roll 1d20+5",34769,null],[79725,"2026-06-28T16:09:39",9,"/roll 1d20+1",34769,null],[79728,"2026-06-28T16:10:09",10,"**Успех:** Лес отзывается чарующей гармонией, которая сама ведет путников. Проверка **Выживания** для поиска пути совершается с преимуществом, а базовое значение **СЛ снижается до 10** (вместо СЛ 14).",34769,null],[79729,"2026-06-28T16:10:29",8,"*подчиняю шаг мелодии*",34769,null],[79730,"2026-06-28T16:10:50",9,"*Играет не сильно переменчивую мелодию, просто поддерживает ритм.*",79726,null],[79731,"2026-06-28T16:11:18",10,"-Ступайте осторожнее и не заденьте ничего. Выглядит опасно тут всё",34769,null],[79732,"2026-06-28T16:11:43",8,"– Сложновато, но постараюсь)",34769,null],[79734,"2026-06-28T16:12:05",9,"//Кидать?",79728,null],[79735,"2026-06-28T16:12:36",10,"//да давайте",34769,null],[79736,"2026-06-28T16:12:45",10,"//с преимуществом но думаю выкинете чо 10 всего",34769,null],[79737,"2026-06-28T16:12:50",9,"/roll +d20+1 раз ест контакт",34769,null],[79739,"2026-06-28T16:13:29",8,"/roll 1d20+1\n/roll 1d20+1",34769,null],[79741,"2026-06-28T16:13:49",10,"Пройдя просеку, герои упираются в тупик. Перед ними раскинулся тупиковый лабиринт из переплетенных стеклянных стен, работающих как сложная система зеркал. Пройти насквозь невозможно — взору открываются лишь бесконечные галереи собственных обманчивых отражений. Чтобы открыть проход, нужно решить загадки.",34769,null],[79742,"2026-06-28T16:15:11",8,"*вытаскивает верёвку*",34769,null],[79743,"2026-06-28T16:15:19",10,"Перед тупиковой стеной на входе высятся три хрустальные колонны-призмы. На земле высечен круг с тусклыми древними рунами. Сверху сквозь крону падает одинокий сфокусированный луч света, который преломляется в центральной призме и бьет в стену, проявляя надпись:\n«Свет укажет дорогу, но лишь тогда, когда огонь страсти, чистота разума и зелень жизни сольются воедино. Раскрась мою блеклость».",34769,null],[79745,"2026-06-28T16:16:23",10,"//Ваши действия",34769,null],[79746,"2026-06-28T16:16:36",8,"/думаю, а то тупая/",34769,null],[79747,"2026-06-28T16:17:07",8,"– Может, подставить камни разного цвета под свет?",34769,null],[79748,"2026-06-28T16:17:13",9,"— Ммм. Использовать принцип преломления света через призму для того чтобы разбить луч на цвета... — *Смотрит нет ли подходящих солнечных лучей.*",79744,null],[79749,"2026-06-28T16:17:23",10,"-Думаю что вы правы. Только какие?",34769,null],[79750,"2026-06-28T16:17:37",8,"– Отражения у стекла цветные...",79747,null],[79755,"2026-06-28T16:18:17",10,"* Вы видите на полу (как на арте) линзы всех цветов радуги. всего 7 разных цветов*",34769,null],[79756,"2026-06-28T16:18:26",8,"– Красный, белый, зелёный *загибает пальцы*",79749,null],[79760,"2026-06-28T16:19:35",8,"– Или синий вместо белого?",34769,null],[79762,"2026-06-28T16:19:48",9,"— Огонь страсти, чистота разума и зелень жизни, хм... — *Задумался.* — Кажется нам надо три цвета, зелёный и красный, на счет третьего не уверен, ощущение что третий осколок не должен иметь цвета вовсе, или все же.\n\n*Покачал головой.*",34769,null],[79763,"2026-06-28T16:20:33",8,"– Синий – цвет мудрости. У северных народов – цвет скорой погибели...",34769,null],[79765,"2026-06-28T16:20:44",9,"— Может я слишком много думаю  но и у меня всего две руки. Подбери третий цвет, постарайся. — *Берет красный и зелёный.*",34769,null],[79766,"2026-06-28T16:21:22",10,"-Звучит неплохо. осталось понять последовательность и узнать на наших шкурах последствия выбора",34769,null],[79768,"2026-06-28T16:21:26",8,"*беру синий и белый, чтобы получить небесно-голубой блик*",34769,null],[79769,"2026-06-28T16:21:47",8,"– Небо всегда чистое *с надеждой*",34769,null],[79771,"2026-06-28T16:23:22",9,"*Выстраивает словно линзу в ряд, оставив место в центре, предлагая изольде вместить свой цвет меж ними.*",34769,null],[79772,"2026-06-28T16:23:35",9,"//Щас ёбнет, чую",34769,null],[79773,"2026-06-28T16:24:18",10,"//В какой последовательности и какие цвета вы вставляете? Можно смешивать в любом количестве.",34769,null],[79774,"2026-06-28T16:25:12",9,"*Сначала красный, пусто для третьего цвета, потом зелёный.*",34769,null],[79775,"2026-06-28T16:25:56",10,"-Значит Изольда какой цвет ты вставишь ? синий или белый ?",34769,null],[79776,"2026-06-28T16:26:08",10,"-Или оба?",34769,null],[79777,"2026-06-28T16:26:48",8,"-оба *наложение*",34769,null],[79778,"2026-06-28T16:26:57",8,"/после красного",34769,null],[79779,"2026-06-28T16:28:16",8,"/ёбнет, но так надо было не блёкло, а белый бесцветен/",34769,null],[79780,"2026-06-28T16:28:22",10,"*Вы видите как Красный смешивается с синим образуя Фиолетовый цвет. Колонна начинает светиться мягким фиолетовым цветом и лес гудит одобрительно. Когда свет вы вставляете белый цвет то возникает вспышка*",34769,null],[79781,"2026-06-28T16:28:29",10,"//Спас тела 12",34769,null],[79782,"2026-06-28T16:28:45",10,"//с преимуществом изза гомункулов",34769,null],[79783,"2026-06-28T16:28:50",10,"/r 2d20+3",34769,null],[79785,"2026-06-28T16:28:54",8,"/там наложение белого и синего через луч же/",34769,null],[79786,"2026-06-28T16:29:16",10,"//Через синюю норм прошло через белую пошло через очко.",34769,null],[79787,"2026-06-28T16:29:39",8,"/roll 1d20+2\n/roll 1d20+2",34769,null],[79789,"2026-06-28T16:29:59",9,"/roll +d20 тело, конструкты зашумели и предупредили о неладном",34769,null],[79791,"2026-06-28T16:30:47",10,"-Какой приятный свет *Раскинув руки купаюсь во вспышке света* - Чтож думаю первые два цвета были правильными. Фиолетовый... Огонь страсти и чистота разума слились",34769,null],[79792,"2026-06-28T16:31:10",10,"//Все прошли спасы. Возникла вспышка излучения но у вас достаточно крепкое тело",34769,null],[79794,"2026-06-28T16:31:24",9,"— Убираем белый?",34769,null],[79795,"2026-06-28T16:31:24",8,"/там нужно было чисто синий, да?/",34769,null],[79796,"2026-06-28T16:31:35",10,".",79780,null],[79797,"2026-06-28T16:32:00",9,"//Ну, да. Только на стенах остались тени а завтра мы начнем лысеть ^^",79792,null],[79799,"2026-06-28T16:32:20",10,"//На таких спасах пока норм. Кто знает что будет в следующий раз если ошибетесь",34769,null],[79801,"2026-06-28T16:32:50",10,"-Думаю первые два цвета это красный и синий. Что же дальше?",34769,null],[79802,"2026-06-28T16:32:58",8,"– Теперь зелёный",34769,null],[79803,"2026-06-28T16:33:27",9,"*Приголовился пробовать ещё раз.*",34769,null],[79804,"2026-06-28T16:33:39",10,"//ничего не происходит пока что. Видимо нужно добавить еще цвет",79802,null],[79805,"2026-06-28T16:33:53",9,"*Сейчас держит красный и синий.*",34769,null],[79806,"2026-06-28T16:34:11",10,"-Реакция была правильной когда смешалось два цвета. Думаю в этот раз будет тоже самое",34769,null],[79807,"2026-06-28T16:34:15",8,"/интуитивно накладывает к нему жёлтый/",34769,null],[79808,"2026-06-28T16:34:25",8,"/чтобы был салатовый/",34769,null],[79809,"2026-06-28T16:34:59",8,"/снова спас?/",34769,null],[79810,"2026-06-28T16:35:14",9,"//Красный, синий, зелёный, четвертый чтоль...",34769,null],[79814,"2026-06-28T16:36:06",10,"*Свет пройдя через зеленый и желтый начала мягко сиять салатовым цветом*",34769,null],[79816,"2026-06-28T16:36:58",8,"– Жизнь, это и кровь. Но красный и зелёный дали бы коричневый цвет кладбищенской земли...",34769,null],[79817,"2026-06-28T16:37:31",8,"– Хотя растения прорастают из земли",34769,null],[79818,"2026-06-28T16:38:15",10,"*Смешались все цвета и колонна засияла коричневым цветом.огонь страсти, чистота разума и зелень жизни слились воедино.*",79810,null],[79819,"2026-06-28T16:38:25",9,"— Я уже не понимаю, о четвертом цвете нечего не сказанно кроме как раскрась мою блеклость.",34769,null],[79821,"2026-06-28T16:38:54",10,"//Не не вы правильно 4 цвета соединили. Красный \\ синий \\ зеленый\\желтый",34769,null],[79822,"2026-06-28T16:39:07",9,"*Это произошло как раз когда он думал о прозрачном.*",79818,null],[79823,"2026-06-28T16:39:16",9,"— Ты гений.",79817,null],[79825,"2026-06-28T16:39:37",10,"*Открывается проход*- Чтож я думаю мне повезло со спутниками",34769,null],[79826,"2026-06-28T16:40:02",10,"Как только световые руны загораются правильными цветами, зеркальная стена со скрежетом расходится, открывая узкий проход. Он увенчан аркой, на которой подвешены сотни тончайших, как паутина, хрустальных колокольчиков. На своде арки выгравированы слова:",34769,null],[79827,"2026-06-28T16:40:09",10,"«Я хрупка, как само это место. Ты можешь разрушить меня, просто назвав по имени. Что я?»",79826,null],[79828,"2026-06-28T16:40:17",8,"– Либо солнце, либо кровь. Я не была уверена",79823,null],[79830,"2026-06-28T16:41:06",10,"-Хорошо надпись видно отсюда. Давайте подумаем перед тем как войти",34769,null],[79831,"2026-06-28T16:41:16",9,"— Подождите немного. — *Делает подпорку из чего нить чтобы цвета всегда освещали колонну. Другие путники чтобы не споткнулись об это.*",34769,null],[79832,"2026-06-28T16:41:21",8,"– Тишина",34769,null],[79833,"2026-06-28T16:41:51",10,"*Ничего не происходит. Думаю надо зайти в проход чтобы узнать ответ или последствия*",34769,null],[79834,"2026-06-28T16:42:21",8,"*иду первой, раз назвала*",34769,null],[79835,"2026-06-28T16:42:40",10,"*иду за всеми в конце группы*",34769,null],[79836,"2026-06-28T16:42:40",8,"/но побаиваюсь/",34769,null],[79837,"2026-06-28T16:43:15",9,"*Хардинт не стал спорить, он тоже подумал о тишине.*",34769,null],[79838,"2026-06-28T16:43:40",10,"*Вы стоите перед аркой с надписью. Ваши действия?*",34769,null],[79839,"2026-06-28T16:43:44",10,".",79829,null],[79840,"2026-06-28T16:44:04",8,"*говорю \"Тишина\" и пробую войти*",34769,null],[79841,"2026-06-28T16:44:17",10,"//Как ты это говоришь?",79840,null],[79842,"2026-06-28T16:44:29",8,"*шёпотом*",34769,null],[79843,"2026-06-28T16:44:30",9,"*Но ищущий всегда подвох и накручивая себя, очень не уверен что ответ так прост.*",34769,null],[79844,"2026-06-28T16:45:11",10,"*Колокольчики на арке мягко колышатся и расступаются*",34769,null],[79845,"2026-06-28T16:45:34",8,"– Идём? *встаю в середину*",34769,null],[79846,"2026-06-28T16:46:02",10,"//Спас ловкости 12",79845,null],[79847,"2026-06-28T16:46:12",10,"//всем. Зал начинает резонировать",34769,null],[79848,"2026-06-28T16:46:28",9,"/roll 1d20+2 эхь",34769,null],[79850,"2026-06-28T16:46:32",10,"/r 1d20+2",34769,null],[79852,"2026-06-28T16:46:41",8,"/roll 1d20+2",34769,null],[79854,"2026-06-28T16:46:50",8,"/жопа/",34769,null],[79855,"2026-06-28T16:46:52",9,"//Ну, другого результата",79849,null],[79856,"2026-06-28T16:46:56",10,"/r 2d4 звуком",79852,null],[79858,"2026-06-28T16:47:31",9,"*Показывает жестом не шуметь.*",79853,null],[79859,"2026-06-28T16:47:34",10,"*От своей осторожности ты шел с зажатым ртом и ушами. Думаю твоя паранойя сработала*",79849,null],[79860,"2026-06-28T16:47:49",10,"*тихо иду за всеми*",34769,null],[79861,"2026-06-28T16:47:57",8,"*замолкаю*",79858,null],[79862,"2026-06-28T16:48:09",9,"— Тишина... — *Прошептал он плвторяя то же самое, на всякий.*",34769,null],[79863,"2026-06-28T16:48:25",10,"*ничего не происходит. Проход итак открыт*",34769,null],[79864,"2026-06-28T16:48:29",8,"/почему я не знаю язык жестов, помогло бы/",34769,null],[79865,"2026-06-28T16:48:51",9,"*Идём.*",34769,null],[79866,"2026-06-28T16:49:11",8,"*иду в середине с палочкой*",34769,null],[79867,"2026-06-28T16:49:46",8,"*распускаю клубок верёвки, чтобы не заблудиться*",34769,null],[79868,"2026-06-28T16:49:59",10,"*пройдя через арку вы оказались в проходе. Тут тихо и мирно только звенит стекло*",34769,null],[79869,"2026-06-28T16:51:02",10,"-Думаю если бы мы просто промолчали все было бы хорошо. Ты в порядке Изольда?",34769,null],[79870,"2026-06-28T16:51:23",8,"*кивает и показывает палец вверх*",34769,null],[79871,"2026-06-28T16:51:24",9,"//Кста, у меня не гомункулы а прост конструкты мелкие, на всякий.",34769,null],[79872,"2026-06-28T16:51:41",10,"//оке",34769,null],[79873,"2026-06-28T16:52:22",10,"*Провожу рукой по ушам. Руки горят золотым светом и ты чувствуешь себя лучше* - не стоит притворятся. Наши жизни сейчас связаны",79870,null],[79874,"2026-06-28T16:52:41",10,"/r 1d4+4 лечащее слово",34769,null],[79876,"2026-06-28T16:54:02",8,"– Спасибо *тихо*",34769,null],[79877,"2026-06-28T16:54:20",10,"*Пройдя некоторое время путь вперед преграждает глубокий овраг(без арта) на дне которого торчат острые стеклянные пики. Из расселины дует мощный поток ветра. Проходя сквозь полые стеклянные сталагмиты, ветер создает жуткий , оглушительный скрежет*",34769,null],[79878,"2026-06-28T16:55:28",9,"/roll 1d20+3 осматривается на наличие опасности хотя пассивное восприятие и так восемнадцать",34769,null],[79880,"2026-06-28T16:55:37",8,"*пока развилок нет, подбираю верёвку*",34769,null],[79881,"2026-06-28T16:56:01",8,"/там сколько ширина?/",79877,null],[79882,"2026-06-28T16:56:06",9,"*Ветер слишком сильный, немного слезятся гоаща от потоков воздуха.*",79879,null],[79883,"2026-06-28T16:56:35",10,"*Кричу с заложенными ушами* - КАК ВСЕ СТРАННО! ШУМ ПОСЛЕ ТИШИНЫ! * пытаюсь идти через овраг по тропе падаю на колени и держась за уши отхожу назад* - ДУМАЮ ЧТО ЕСЛИ НЕ УСПОКОИТЬ ВЕТЕР ТО НАМ НЕ ПРОЙТИ! //ответ на твою проверку",79878,null],[79884,"2026-06-28T16:57:02",10,"//Большая) но можно спокойно пройти по середине по тропе.",79881,null],[79885,"2026-06-28T16:57:53",8,"/тоже осматриваюсь на подозрительную фауну конкретно/ /roll 1d20+3",34769,null],[79886,"2026-06-28T16:58:06",8,"/roll 1d20+3",34769,null],[79888,"2026-06-28T16:58:13",10,"//Пампампаам инициатива по заявкам. Хард и Фантомас бросьте чтобы определить очередность заявок",34769,null],[79889,"2026-06-28T16:58:33",8,"/roll 1d20+2",34769,null],[79891,"2026-06-28T16:58:38",9,"//Да в принципе, у меня нет идей пока",34769,null],[79892,"2026-06-28T16:59:02",10,"*Ты видишь что сталагмиты через который проходит ветер выглядт отдаленно похоже на гиганскую стеклянную флейту*",79887,null],[79893,"2026-06-28T16:59:11",9,"/roll 1d20+2+5 инициатива на всякий раз так, бонус пять тоже от черты",34769,null],[79895,"2026-06-28T16:59:41",10,"//Ок ход Харди. Твои действия или пропускаешь?",34769,null],[79896,"2026-06-28T16:59:52",8,"/гигантские флейты из земли т.е./",79892,null],[79897,"2026-06-28T17:00:21",9,"//Пропуск, пытается посмотреть что у него в рюкзакеполещного может быть",34769,null],[79898,"2026-06-28T17:00:40",10,"//По устройству отдаленно похоже на флейту. Ветер проходит в дыры в сталагтитах и вызывают яростный асинхронный звук который режет твой музыкальный слух",79896,null],[79899,"2026-06-28T17:00:57",10,"//Ход фантомас",34769,null],[79900,"2026-06-28T17:01:07",8,"/сталактиты (сверху) или сталагмиты (снизу)? Это разное/",34769,null],[79901,"2026-06-28T17:02:00",10,"//Пусть сталагмиты",34769,null],[79902,"2026-06-28T17:02:10",10,"//да я еблан путаю) сталагмиты",34769,null],[79903,"2026-06-28T17:03:11",8,"/пытаюсь виолой привести хаос в единый камертон, вставляю более гармонизирующие ноты/",34769,null],[79904,"2026-06-28T17:04:06",8,"/хз, сработает ли/",34769,null],[79905,"2026-06-28T17:04:07",10,"*Ничего не происходит. Возможно стоит осмотреться вокруг* //действие закончилось. теперь остались только слова и бонусное",34769,null],[79908,"2026-06-28T17:04:54",9,"//Ну, я не вижу флейт похоже",34769,null],[79909,"2026-06-28T17:04:59",8,"/осматриваюсь, нет ли чего-то, кроме \"флейт\"",34769,null],[79910,"2026-06-28T17:06:54",10,"*в углу у стены лежат обрывки одежды и бинтов в крови от путников. а так же 2 стеклянные сферы. На стене нарисована схема флейты и два зачертнутых отверстия из 4*",34769,null],[79911,"2026-06-28T17:07:33",10,"сек",34769,null],[79912,"2026-06-28T17:08:09",8,"/заставляешь чувствовать себя тупым, уважаемо/",34769,null],[79913,"2026-06-28T17:08:21",8,"/думаю/",34769,null],[79915,"2026-06-28T17:08:57",8,"– Надо заткнуть остальные два отверстия...",34769,null],[79916,"2026-06-28T17:09:14",10,"-А?! ЧТО ТЫ ГОВОРИШЬ?! НЕ СЛЫШУ!",34769,null],[79917,"2026-06-28T17:09:15",8,"– Только как?",34769,null],[79918,"2026-06-28T17:09:28",8,"*орёт то же самое*",34769,null],[79919,"2026-06-28T17:10:08",10,"-ДУМАЮ МОЖНО ПРОЛЕЗТЬ ТУДА ИЛИ КИНУТЬ ШАРЫ В ДЫРЫ!! //ход Харди",34769,null],[79920,"2026-06-28T17:10:17",9,"*Хардинт тоже нихуха не слышит.*",34769,null],[79921,"2026-06-28T17:10:27",8,"/у меня шарики есть, кстати/",34769,null],[79922,"2026-06-28T17:10:39",10,"//эти размером с шар для боулинга\\",34769,null],[79923,"2026-06-28T17:10:49",9,"— ПРОЛЕЗТЬ КУДА И КАКИЕ ШАРЫ",34769,null],[79924,"2026-06-28T17:12:00",10,"-ВОН ТАМ ДЫРЫ В СТАЛАГМИТАХ! НАДО ЗАТКНУТЬ ПРАВИЛЬНЫЕ *показываю на шары у стены. Харди на своей 18 ебаной внимательности видит скелет в углу*",34769,null],[79925,"2026-06-28T17:12:13",8,"/если залезем, то при вылезании то же самое начнётся. Или из-за гармонии ветер затихнет/",79919,null],[79926,"2026-06-28T17:12:35",8,"/от голода помер 100%/",79924,null],[79927,"2026-06-28T17:13:04",9,"*Харди пытается понять что именно надо заткнуть, типа где бля та самая флейта ёмана.*",34769,null],[79928,"2026-06-28T17:13:17",10,"*Ты вспоминаешь что твоя сестра выглядела так же когда ты только училась играть на музыкальных инструментах. Похоже он умер от кринжа*",79926,null],[79929,"2026-06-28T17:13:40",10,"//Проверка выступления",79927,null],[79930,"2026-06-28T17:13:50",9,"/roll 1d20+1",34769,null],[79932,"2026-06-28T17:14:18",8,"/улыбается, думая: \"Ничего, потерпела же. Забавно было\"/",79928,null],[79933,"2026-06-28T17:14:20",9,"— НЕВЫХУХА НЕ ПОНИМАЮ, ГДЕ-ЧТО, У МЕНЯ БОЛИТ ГОЛОВА ОТ ЗВУКА УЖЕ.",34769,null],[79934,"2026-06-28T17:14:38",10,"*Наверное как и нарисовано на схеме. Жаль что ты не долго изучал как играть на флейте , но уверен что вроде нормальная мелодия выйдет*",34769,null],[79935,"2026-06-28T17:15:44",8,"(Флейты в овраге?)",34769,null],[79936,"2026-06-28T17:15:47",10,"//Ты можешь спуститься и прозеть по выступам туда или кинуть шар куда над",34769,null],[79937,"2026-06-28T17:16:04",10,"//до сталагмитов можно добраться при сноровке",34769,null],[79938,"2026-06-28T17:17:00",9,"//Или просто обьяснить хардинту что нада сделать. Типа, я спрашиваю потому что не понимаюгде флейта и как добраться до неё",34769,null],[79939,"2026-06-28T17:17:59",10,"//сек",34769,null],[79940,"2026-06-28T17:18:24",8,"*показываю на дыры и профессионально ору* Надо заткнуть их собой или чем угодно!",34769,null],[79942,"2026-06-28T17:18:45",10,"//Кароч модно добраться до них по стене. там есть выступы. Либо кинуть с тропы и попасть куда над",34769,null],[79943,"2026-06-28T17:18:50",9,"//тоесть эта хня на дне оврагп",34769,null],[79944,"2026-06-28T17:19:10",10,"//на уровне глаз. Тут не глубоко но внизу пики стеклянные",34769,null],[79945,"2026-06-28T17:19:10",9,"— ПОКАЖИ КАКИЕ ИЗ НИХ НУЖНО ЗАКРЫТЬ!!!",34769,null],[79946,"2026-06-28T17:19:22",8,"(Наверху есть выступы, чтобы прицепить к ним верёвку?)",34769,null],[79947,"2026-06-28T17:19:31",10,"//Схема на стене. Ты думаешь что отличная мелодия получится. наверное",79914,null],[79948,"2026-06-28T17:19:51",8,"– ПЕРВУЮ И ТРЕТЬЮ, НАЧИНАЯ СПРАВА!",79945,null],[79950,"2026-06-28T17:20:01",9,"*Хардинт расчехляет комплект для лазанья, не зря он его купил.*",34769,null],[79951,"2026-06-28T17:20:03",10,"//Ок пожалуйста. Если вы обвяжитесь веревкой то атлетика с преимуществом",79946,null],[79952,"2026-06-28T17:20:59",8,"*обвязываю верёвку обо что-то твёрдо стоящее на поверхности*",34769,null],[79953,"2026-06-28T17:21:27",10,"//С такой хуйней ты без проблем доползешь. Ты просто так полезешь через шум ?",34769,null],[79954,"2026-06-28T17:21:28",8,"/у меня охрененная атлетика -1",34769,null],[79955,"2026-06-28T17:21:38",9,"*Хардинт делает узлы реже, чтобы не упасть от точки страховки к шипам. Мог бы послать своих слуг но под ветром те вряд-ли полетят еще и шар нести, что не факт что подымут.*",34769,null],[79956,"2026-06-28T17:21:59",9,"//Секунду",79953,null],[79957,"2026-06-28T17:22:22",10,"-ОЧЕНЬ ГРОМКО! НУЖНО БЫТЬ ОСТОРОЖНЕЕ!",34769,null],[79958,"2026-06-28T17:22:29",8,"*засовываю в уши сейчас придумаю что*",34769,null],[79959,"2026-06-28T17:23:19",8,"*немного пеньки, слегка взяв из верёвки*",34769,null],[79960,"2026-06-28T17:23:29",9,"*Воска небыло но есть мыло, не лучший вариант но, деоает щатычки для ушей из мыла.*\n\n//-2 мыла на затычки с расходом на жксперименты",34769,null],[79961,"2026-06-28T17:24:06",10,"//Ок скок чтобы добраться туда нужно 2 хода",34769,null],[79962,"2026-06-28T17:24:14",10,"//60 футов дистанция",34769,null],[79963,"2026-06-28T17:24:31",8,"/верёвка 50 футов/",34769,null],[79964,"2026-06-28T17:24:47",10,"//у него комплект для лазанья",34769,null],[79965,"2026-06-28T17:25:12",9,"*Лезет перецепляя страховку постоянно, каждые 10 футов, лучше уж минуту лезть чем упасть.*",34769,null],[79966,"2026-06-28T17:25:49",9,"//И атлетичный, лажу без потери скорости",34769,null],[79967,"2026-06-28T17:26:16",10,"//ок там не нужно же с таким комплектом атлетику прокидывать?",34769,null],[79968,"2026-06-28T17:26:25",10,"//или акробатику",34769,null],[79969,"2026-06-28T17:26:29",8,"*если уж лезу отдельно, то надо два мотка верёвки связать в один*",34769,null],[79970,"2026-06-28T17:26:48",9,"//Да хз, это на усмотрение д-ма",34769,null],[79971,"2026-06-28T17:27:19",10,"//Думаю ты пролез без проблем. конец твоего хода. У тебя нет ни действий ни бонусных.",34769,null],[79972,"2026-06-28T17:27:32",9,"*Непонимающе смотрит, не понимает зачем Изольда лезет.*",79969,null],[79973,"2026-06-28T17:27:44",10,"//Ход Изольды",34769,null],[79974,"2026-06-28T17:27:46",8,"/вторая дырка/",34769,null],[79975,"2026-06-28T17:28:16",8,"*лезу по связанной 100 фт верёвке с узелками*",34769,null],[79976,"2026-06-28T17:28:31",10,"//Проверка атлетики \\ акробатики с преимуществом",34769,null],[79978,"2026-06-28T17:29:00",8,"/roll 1d20+4\n/roll 1d20+4",34769,null],[79980,"2026-06-28T17:29:43",10,"//на край хватило. на рывке ты сможешь пролезть 30 футов. Местность явно не путешествие по лугу с цветами",34769,null],[79981,"2026-06-28T17:30:18",8,"/т.е. за ход не долезла?/",34769,null],[79982,"2026-06-28T17:30:23",10,"*Багровый стоит на краю уступа и фармит ауру*",34769,null],[79984,"2026-06-28T17:30:35",10,"//60 футов дистанция. Ты пролезла половину как и Харди",34769,null],[79985,"2026-06-28T17:30:43",8,"/ок/",34769,null],[79986,"2026-06-28T17:30:46",9,"//Учитывая всё, моё чудо не сильно быстрее)",34769,null],[79987,"2026-06-28T17:30:53",10,"//я забыл про рывок. но и ты забыл про рывок Харди)",34769,null],[79989,"2026-06-28T17:31:01",8,"/зато надёжнее",79986,null],[79990,"2026-06-28T17:31:06",9,"*Лезет дальше.*",34769,null],[79991,"2026-06-28T17:31:14",10,"//почти",34769,null],[79992,"2026-06-28T17:31:20",9,"//А у меня испольщование тратится, без рывка",79987,null],[79993,"2026-06-28T17:31:21",10,"/r 2d6",34769,null],[79995,"2026-06-28T17:31:37",10,"//Половина урона тем у кого уши заложены",34769,null],[79996,"2026-06-28T17:31:47",9,"//3",34769,null],[79997,"2026-06-28T17:31:57",8,"/3,5 или 4?/",34769,null],[79998,"2026-06-28T17:32:16",10,"*Звук в ваших ушах хоть и заложен что было хорошей идеей , но клетки вашего тела  всеравно резонируют от такого сильного звука*",34769,null],[80000,"2026-06-28T17:32:19",10,"//3",34769,null],[80001,"2026-06-28T17:32:47",9,"*Сцепил зубы и лезет.*",34769,null],[80002,"2026-06-28T17:32:48",8,"/не забываем про 4 временных хп/",34769,null],[80003,"2026-06-28T17:32:49",10,"//Ход Харди",34769,null],[80004,"2026-06-28T17:33:04",9,"//Ооо, тогда збс",80002,null],[80005,"2026-06-28T17:33:30",9,"//Дальше*",80001,null],[80006,"2026-06-28T17:34:00",10,"//Ты добрался до первого отверстия ибо дырка только в жопе как говорил твой мастер",34769,null],[80007,"2026-06-28T17:34:28",10,"Какое отверстие ты закрываешь?",34769,null],[80008,"2026-06-28T17:34:37",8,"/заткнуть первое и третье, начиная справа/",34769,null],[80010,"2026-06-28T17:35:21",10,"//Скорости хватит чтобы заткнуть первое",34769,null],[80011,"2026-06-28T17:35:36",9,"*Хардитн нацелен на то что дальше, это он оставит девушке, к нему легче долезть.*\n\n//ход, шар у меня тоже только один",34769,null],[80012,"2026-06-28T17:36:03",10,"//ты заткнул отверстие ?",34769,null],[80013,"2026-06-28T17:36:10",9,"//Я помню",80008,null],[80014,"2026-06-28T17:36:29",9,"//Не, изольда пусть, я следующее заткну",80012,null],[80015,"2026-06-28T17:36:36",9,"//Тоесть третье",34769,null],[80017,"2026-06-28T17:36:59",10,"//Третье в 40 футах. по сложной местности",34769,null],[80018,"2026-06-28T17:37:07",10,"//Ход Изольды.",34769,null],[80020,"2026-06-28T17:38:57",8,"*показываю звуку кончик языка с зажатым ртом и лезу к первому отверстию*",34769,null],[80021,"2026-06-28T17:39:38",10,"//ну допустим мяу. Я думал к третьему. Тогда давайте так",34769,null],[80022,"2026-06-28T17:39:56",10,"//Изольде хватит скорости до первого . Харди на рывке бы добрался до третьего за свой ход",34769,null],[80023,"2026-06-28T17:40:04",9,"//Ну она ток к первому успевает, я в след ход к треттему планировал",34769,null],[80024,"2026-06-28T17:40:28",10,"//Вы у нужных отверстий",34769,null],[80025,"2026-06-28T17:41:00",8,"*затыкаю спиной с рюкзаком, за жопу боязно*",34769,null],[80027,"2026-06-28T17:41:10",9,"*Показываю один, два, три, чтобы закрыть одновременно.*",34769,null],[80028,"2026-06-28T17:41:36",8,"*тогда одновременно с Хардом*",34769,null],[80029,"2026-06-28T17:41:40",10,"*вы затыкаете звучит мелодия*",34769,null],[80030,"2026-06-28T17:41:45",10,"//каждый киньте выступление",34769,null],[80031,"2026-06-28T17:41:56",8,"/roll 1d20+5",34769,null],[80033,"2026-06-28T17:41:57",9,"/roll 1d20+1 выступление",34769,null],[80035,"2026-06-28T17:42:04",10,"//Думаю Изольдя с преимуществом даже. Она ведь музыкант",34769,null],[80036,"2026-06-28T17:42:15",8,"/roll 1d20+5",34769,null],[80038,"2026-06-28T17:43:24",10,"*Изольда была так уверена в своем мастерстве учителя и в вере в Харди что дала ему сыграть не ту ноту. Харди понял что накосячил и слишком быстро стал уверен в себе и даже не спросил у своего учителя *",34769,null],[80039,"2026-06-28T17:43:51",10,"//Вы понимаете какие нужно заткнуть на 21 выступления",34769,null],[80040,"2026-06-28T17:44:17",9,"//Надо сместить их на 1 обе. С другой стороны!)",34769,null],[80042,"2026-06-28T17:44:38",10,"/r 1d4 психического урона Изольде за плохо взятую ноту. Тебе скребет прям по душе",34769,null],[80045,"2026-06-28T17:45:06",8,"/у меня же 21, не?/",34769,null],[80046,"2026-06-28T17:45:38",10,"//Изольда поняла что нота не та) и поняла какую надо взять. Но ты опытный музыкант и фальшивая нота режет твой слух",34769,null],[80047,"2026-06-28T17:45:49",8,"/а)",34769,null],[80048,"2026-06-28T17:45:58",8,"/гениально)",34769,null],[80049,"2026-06-28T17:46:05",9,"*Ну что же, делаем. Даже Хардинт понимает что что-то не так, ветер е утих, он тоже думал о возможности перепутать стороны.*",34769,null],[80050,"2026-06-28T17:46:08",10,"//Если не хотите отыграть то вы закончили испытание",34769,null],[80051,"2026-06-28T17:46:16",9,"//Рил думал щас перепутаем)",34769,null],[80052,"2026-06-28T17:46:32",10,"//ты 4 выкинул на выступление когда смотрел на схему",80051,null],[80053,"2026-06-28T17:46:39",9,"*Перень вынимает счою сферу и смешает на 1 дальше.*",34769,null],[80054,"2026-06-28T17:47:09",9,"*Это логика а не выступления, сторона нам неизвестна правильная.*",80052,null],[80055,"2026-06-28T17:47:27",10,"//Это нотная грамота)",34769,null],[80056,"2026-06-28T17:47:47",9,"//Ну типа, не сработало с права на лево, значит надо с лева на право , там 4 отверстия)",34769,null],[80057,"2026-06-28T17:48:02",9,"//Лан, как хотите, парень тупит",34769,null],[80058,"2026-06-28T17:48:15",10,"*Звук стал гармоничным и успокаивающим. Вы чувствуете как лес резонирует с ним и теперь можно пройти дальше*",34769,null],[80059,"2026-06-28T17:48:36",8,"*осторожно убираю спину*",34769,null],[80061,"2026-06-28T17:48:50",9,"*Помогает девушке перелезть обратно и собирает потом свои страховочные шлямбуры.*",34769,null],[80062,"2026-06-28T17:48:51",10,"*звук орет снова неправильно*",34769,null],[80063,"2026-06-28T17:49:06",10,"-ДУМАЮ НАДО ЧЕМ ТО ЗАТКНУТЬ!",80059,null],[80064,"2026-06-28T17:49:06",9,"//А она не взяла вторую сферу?",34769,null],[80065,"2026-06-28T17:49:16",10,"//хз) она рюкзаком заткнула)",34769,null],[80066,"2026-06-28T17:49:22",8,"/блин, нет, я тупая/",34769,null],[80067,"2026-06-28T17:49:36",9,"— СТОЙ ТАМ Я ЗА НЕЙ СЛАЖУ!",34769,null],[80068,"2026-06-28T17:49:38",10,"*Багровый кидает тебе сферу*",34769,null],[80069,"2026-06-28T17:49:51",10,"/r 1d20+2+1d4",34769,null],[80071,"2026-06-28T17:50:16",9,"//На днооооо",34769,null],[80072,"2026-06-28T17:50:19",10,"*Она попала не в то отверстие и звук теперь совсем паршиво звучит*",34769,null],[80073,"2026-06-28T17:50:49",8,"*держу рюкзаком пока*",34769,null],[80074,"2026-06-28T17:50:50",10,"-Я СТАРАЛСЯ БЫТЬ ПОЛЕЗНЫМ!",34769,null],[80075,"2026-06-28T17:51:16",8,"- НИЧЕГО. НАДО ДОСТАТЬ СФЕРУ!",34769,null],[80076,"2026-06-28T17:51:55",8,"/какой же я дятел/",34769,null],[80077,"2026-06-28T17:51:57",9,"*Ну, раз сфера в зоне досягаемости вынимаю её и меняю нашего забывчивого чародея на сферу.*",34769,null],[80078,"2026-06-28T17:52:11",10,"//ну собственно у меня осталась последняя финальная глава) Фантомас ты еще задержишься на максимум 30 минут?",34769,null],[80079,"2026-06-28T17:52:17",8,"/да",34769,null],[80080,"2026-06-28T17:52:31",8,"/без проблем, планы чуть поменялись",34769,null],[80081,"2026-06-28T17:52:35",10,"*теперь все нормально и вы можете идти дальше. Багровый вас вытягивает за веревки и вы на тропе*",34769,null],[80082,"2026-06-28T17:52:38",9,"//Ты прошлые две загадки вывезла, с цветами я бы не догадался, там не совсем логично",80076,null],[80083,"2026-06-28T17:52:43",10,"//Скок времени еще?",80080,null],[80085,"2026-06-28T17:52:56",8,"/час точно",34769,null],[80086,"2026-06-28T17:53:04",8,"/возможно, и больше",34769,null],[80087,"2026-06-28T17:53:15",9,"//Я тож подустал",34769,null],[80088,"2026-06-28T17:53:30",10,"//ну значит точно финал)",34769,null],[80089,"2026-06-28T17:53:43",8,"/но локация классная/",34769,null],[80091,"2026-06-28T17:54:06",10,"В самом сердце леса деревья расступаются, образуя ровную круглую поляну. В её центре пузырится и плавно течет густой пруд из расплавленного стекла, напоминающий кипящую светящуюся карамель. Это остаточное эхо древней магии",34769,null],[80092,"2026-06-28T17:54:21",9,"*Собирает засобой шлямбуры и страхтовку. Нечего раскидываться вещами.*",34769,null],[80093,"2026-06-28T17:54:52",9,"— Красиво. — *Заворожен просто.*",80091,null],[80095,"2026-06-28T17:54:59",8,"*подбирает верёвку XL и снимает её с уступа*",34769,null],[80096,"2026-06-28T17:55:34",8,"– В белом больше всего цветов... *кайфует*",34769,null],[80097,"2026-06-28T17:55:46",10,"Пруд затихает, превращаясь в гигантское зеркало.Надписи на непонятном вам языке",34769,null],[80098,"2026-06-28T17:56:30",10,"-Изольда вы ведь тоже волшебник? можете мне помочь понять суть леса и озера? Я чувствую сильную магию от них",34769,null],[80099,"2026-06-28T17:56:50",8,"/кстати, вполне логично, если мыслить символами",80082,null],[80101,"2026-06-28T17:57:23",8,"*пытаюсь опознать местную магию на вид и запах*",34769,null],[80102,"2026-06-28T17:57:35",10,"/r 2d20+6+1d4",34769,null],[80104,"2026-06-28T17:58:21",8,"/можно на магию кинуть?/",80101,null],[80105,"2026-06-28T17:58:53",9,"*Хардинт тоже помогает, он владеет магическими знания в какой-то мере.*\n\n//Владею навыком магия",34769,null],[80106,"2026-06-28T17:59:04",10,"//Ну ты оказала действие помощь",80104,null],[80107,"2026-06-28T17:59:14",10,"//я кританул на проверке щас вам лора подкину",34769,null],[80111,"2026-06-28T18:00:41",10,"В самом центре леса деревья расступаются, образуя идеальный круг. Внутри него бурлит, дымится и переливается пруд из расплавленного стекла. Это остаточное явление древнего заклинания **8-го круга**, завязанного на ментальное состояние вошедших. Весь лес подвергся заклинанию истинного полиморфа. Возможно много лет назад это место было совсем другим пока не случилось какое то бедствие в этих руинах или благословение.",34769,null],[80112,"2026-06-28T18:02:20",9,"//Так и запишем, место где волшебники смогут выучить истинный полиморф ^^",34769,null],[80113,"2026-06-28T18:02:37",8,"/полиморф врага в овцу",34769,null],[80114,"2026-06-28T18:02:50",10,"*Багровый подходит к зеркалу и читает надписи. Они оказались на небесном ( как удобно)* - Написано что надо принять и понять себя. Хм откуда я знаю этот язык?",34769,null],[80115,"2026-06-28T18:03:11",8,"– Родился не на земле?",34769,null],[80116,"2026-06-28T18:03:37",10,"-Незнаю. Я очнулся без памяти на фестивале фей. Ничего не помню только обрывки и пара вещей из прошлого",34769,null],[80119,"2026-06-28T18:04:52",9,"— Кхм кхм. Hjhfs huugta njjgg. — *Говорит на глубинном. А потом улыбается одними глазами под платком.* — У каждого своё прошлое.",34769,null],[80121,"2026-06-28T18:05:40",10,"-У меня его к сожалению нет. Но не будем о грустном. Думаю это конец нашего пути в этом лесу. Он нас испытывал и привел сюда. Будете участвовать в финальном испытании?",34769,null],[80122,"2026-06-28T18:06:24",8,"- Раз пошла такая пьянка *улыбается во все зубы*",34769,null],[80123,"2026-06-28T18:06:41",10,"//Тогда первая Изольда.",34769,null],[80124,"2026-06-28T18:07:06",9,"— Никто же не запрещает попробовать?)",34769,null],[80125,"2026-06-28T18:07:22",10,"*При вгляде в зеркало мир теряет фокус и ты видишь перед собой отражения*",80122,null],[80126,"2026-06-28T18:07:40",10,"**Иллюзия:** Грандиозный театр, залитый светом софитов. Изольда в центре сцены со своей виолой, публика рукоплещет. Позади неё стоят её родители и сестра Оринтия — они больше не прячутся в глуши, открыто сплетая теневую магию с музыкой Изольды. Полная безопасность для её семьи и абсолютное признание её таланта.\n * **",34769,null],[80127,"2026-06-28T18:08:03",10,"**Шепот леса:** *«Вот сцена, которой ты достойна. Твое настроение переменчиво, но эти зрители никогда не устанут от тебя. Здесь твоя семья наконец-то свободна. Сыграй для нас, стань королевой этого стеклянного замка вечно...»*",34769,null],[80128,"2026-06-28T18:08:40",8,"– Тогда я никогда не увижу свою семью по-настоящему(",34769,null],[80129,"2026-06-28T18:09:33",10,"**Шепот леса:** *«Останься тут и все будет реальным. Вечно. Тут ты получишь все о чем мечтаешь и твоя семья будет счастлива с тобой»*",34769,null],[80133,"2026-06-28T18:12:05",8,"– Вечность – удел тех, кто хочет постоянства. Постоянный успех наскучит, если не испытывать неудачи и адреналина. И знаешь, странный голос, под конец долгой жизни я хотела продолжить путь в ином мире, иначе где приключение? *легко смеётся* Но спасибо за красоту, которую ты дал мне",34769,null],[80134,"2026-06-28T18:13:04",8,"– Такие места обязаны существовать, чтобы кто-то увидел их раз в жизни и никогда не забывал в переменчивости мира",34769,null],[80137,"2026-06-28T18:14:16",10,"*Твой вольных дух хочет нарушить этот скучный порядок и спастись* //твои действия?",34769,null],[80140,"2026-06-28T18:15:32",8,"/я посылаю в иллюзию ворох иллюзорных прекрасных полевых цветов и рывком назад пытаюсь/",34769,null],[80143,"2026-06-28T18:15:44",10,"//Спас мудрости 12",34769,null],[80144,"2026-06-28T18:16:14",8,"/roll 1d20+1",34769,null],[80146,"2026-06-28T18:16:15",10,"Иллюзия начинает трещать из-за нарушенного порядка и хаоса",34769,null],[80147,"2026-06-28T18:16:39",10,"//скок там? у меня в браузере не показывает больше ролы",34769,null],[80148,"2026-06-28T18:16:47",8,"/9",34769,null],[80149,"2026-06-28T18:16:53",8,"(",34769,null],[80150,"2026-06-28T18:17:13",10,"//Ты застыла на раунд",34769,null],[80151,"2026-06-28T18:17:52",10,"Багровый и Харди видят как Изольда сначала улыбалась , но неожиданно начала покрываться стеклом",34769,null],[80152,"2026-06-28T18:18:00",10,"/r 1d4 урона огнем",34769,null],[80154,"2026-06-28T18:18:18",10,"//Твои действия Харди?",34769,null],[80155,"2026-06-28T18:18:29",10,"- О нет что-то пошло не так!",34769,null],[80156,"2026-06-28T18:20:00",10,"Hard",34769,null],[80157,"2026-06-28T18:20:57",9,"//Кому",80153,null],[80158,"2026-06-28T18:21:07",8,"/это же не состояние очарованный?/",34769,null],[80159,"2026-06-28T18:21:08",10,"//Изольде. Она покрылась стеклом",34769,null],[80160,"2026-06-28T18:21:37",10,"//Ты в иллюзии 8 круга. Сейчас ты в театре и начала наводить хаос",34769,null],[80161,"2026-06-28T18:21:47",8,"/оке",34769,null],[80162,"2026-06-28T18:22:25",9,"*Хардинт незнает что делать, а потом вспоминает что у него есть кое что, надеется сработает...*",34769,null],[80163,"2026-06-28T18:22:56",10,"/r 1d4+4 Исцеляющее слово",34769,null],[80165,"2026-06-28T18:23:14",10,"-Надеюсь это поможет //Действие Харди и вовращаемся в иллюзию",34769,null],[80166,"2026-06-28T18:23:30",9,"*Касается серги на обратной стороне воротника и пытается связаться с девушкой.*\n\n— Ты как. Ты где. Возвращайся, сопротивляйся...\n\n//Я хрен знает сработает ли, серьга сообщения!",34769,null],[80170,"2026-06-28T18:24:18",10,"*Изольда ты слышишь голос Харди с помехами. Возможно нужно еще сильнее разрушить структуру*",34769,null],[80173,"2026-06-28T18:25:20",8,"(Я не могу двигаться?)",34769,null],[80174,"2026-06-28T18:25:24",9,"//Возможно она даже ответить может, связь вродь в обе стороны раунд",34769,null],[80176,"2026-06-28T18:25:40",10,"//Сейчас ты можешь чтото сделать. Но в конце хода снова спас мудрости",34769,null],[80178,"2026-06-28T18:26:21",8,"*мысленно Хардинту отвечаю \"Пригнитесь!\"",34769,null],[80180,"2026-06-28T18:26:45",8,"*действием в кружении кастую луч болезни по всему, что можно*",34769,null],[80181,"2026-06-28T18:26:52",10,"-Это испытание нужно пройти самому. Неизвестно что показало ей зеркало",34769,null],[80182,"2026-06-28T18:27:29",10,"*В реальности ничего не происходит и никто ничего не слышит  , но в иллюзии люди начали разбегаться и она еще сильнее трещит*",34769,null],[80183,"2026-06-28T18:27:35",10,"//спас мудрости",34769,null],[80184,"2026-06-28T18:27:56",8,"(С песенкой \"Карусель, карусель начинает рассказ..\")",80180,null],[80185,"2026-06-28T18:28:31",10,"Твоя мать и сестра обращаются к тебе : Останься с нами и принеси снова гармонию. Зачем страдать когда тут есть всё что нужно?",80184,null],[80186,"2026-06-28T18:28:35",8,"*бонусным фокусами пытаюсь вырваться с порывом ветра (заговор)",34769,null],[80188,"2026-06-28T18:28:47",8,"/roll 1d20+1",34769,null],[80189,"2026-06-28T18:28:48",10,"//ок с преимуществом спас",34769,null],[80191,"2026-06-28T18:28:57",8,"/жесть",34769,null],[80193,"2026-06-28T18:29:10",8,"/roll 1d20+1",34769,null],[80195,"2026-06-28T18:29:42",8,"– Мне не нужны подделки, если есть настоящее золото!",80185,null],[80196,"2026-06-28T18:29:47",8,"/ход",34769,null],[80197,"2026-06-28T18:29:52",10,"Иллюзия рассеивается и ты чувствуешь себя легче. По другому. Что-то в глубине тебя изменилось , но магия не виновата в этом. Она помогла тебе осознать себя глубже",34769,null],[80205,"2026-06-28T18:30:51",8,"– И снова привет! Кто следующий?",34769,null],[80206,"2026-06-28T18:30:52",10,"*Багровый и Харди видят как Изольда снова нормальная хоть и выглядит по другому. Более целеустремленной ? *",34769,null],[80211,"2026-06-28T18:31:21",10,"-Ты прошла испытание? мы переживали за тебя. Ты покрылась стеклом вся и я думал что ты уже стала частью леса",34769,null],[80213,"2026-06-28T18:31:49",9,"— Что там было.",34769,null],[80214,"2026-06-28T18:31:55",8,"– Не как два пальца об асфальт, но посильно. Вы тоже сможете",34769,null],[80215,"2026-06-28T18:32:11",9,"— С тобой всё хорошо?",34769,null],[80217,"2026-06-28T18:32:31",8,"– Уникальную красоту хотели сделать мне скукой смертной и вечной *поднимает глаза*",80213,null],[80219,"2026-06-28T18:33:22",9,"*Ничего не понял но переспрашивать не стал. Смотрит на Багрового а потом снова на Изольду.*\n\n— Думаешь стоит попробовать?",80217,null],[80221,"2026-06-28T18:33:32",8,"– Вечный успех на музыкальном поприще, полное принятие обществом и всё такое, только в здешней реальности... Мне это наотрез не надо, как я поняла",34769,null],[80224,"2026-06-28T18:34:02",10,"-Думаю что стоит попробовать. Изольда выглядит более свободной",34769,null],[80227,"2026-06-28T18:34:26",9,"— Если так... то я скорее попаду в свой ад. — *Усмехнулся парень, ведь он стремился не к успеху а к пути.*",80221,null],[80228,"2026-06-28T18:34:26",8,"– Только смелым подчиняются моря *подмигивает*",34769,null],[80229,"2026-06-28T18:36:54",9,"*Всё же и сам, под одобрениями и прочим, пытается взглянуть.*",34769,null],[80230,"2026-06-28T18:37:03",10,"* **Иллюзия:** Идеальная, безопасная мастерская. Верстак, знакомые инструменты, огромные пустые стеллажи, готовые для его коллекций. Рядом стоит его Учитель, тепло улыбается и приглашает сесть за работу. Синий кристалл загадочного артефакта горит ровным, стабильным светом.\n * **Шепот леса:** *«Зачем ты идешь дальше с этими людьми?Посмотри на этих людей рядом с тобой. Ты ведь едва их знаешь. Люди они совершают ошибки и принимают плохие решения. Они погибнут, и ты снова останешься один в чужом мире. Шагни сюда. Здесь твоя точка опоры. Здесь безопасно. Здесь ты всё контролируешь. Твоя коллекция будет в сохранности. Шагни сюда. Вернись к верстаку»*",34769,null],[80235,"2026-06-28T18:39:33",9,"*Это было неожиданно, даже если он знал чего ждет, произошло другое... он ждат тонны работы, непосильных заказов и прочего, а здесь был какой-то уют, даже тело отреагировало словно само, по памяти.*\n\n— Здраствуйте учитель. У нас сегодня есть работа?",80230,null],[80237,"2026-06-28T18:40:34",10,"**Шепот леса : Работа есть всегда. Слишком много заказов и мне нужна помощь моего ученика. Ты ведь однажды хочешь тоже стать мастером? Садись и начинай. Тут ты сможешь достичь этого **",80235,null],[80242,"2026-06-28T18:41:57",10,"//пройди спас мудрости если слова мастера звучат соблазнительно",34769,null],[80244,"2026-06-28T18:43:17",9,"*Хардинт сел и начал работать. Интересные вещи, дроны, механизмы даже чиняоружие наёмников он видел их историю сражений что написанно зазубреннами на клинке.*",34769,null],[80245,"2026-06-28T18:43:26",9,"/roll 1d20+1 мудрость",34769,null],[80247,"2026-06-28T18:43:34",10,"//скок там?",34769,null],[80248,"2026-06-28T18:43:44",9,"//17",34769,null],[80249,"2026-06-28T18:43:46",10,"//Веб версия перестала кубы показывать( срака",34769,null],[80250,"2026-06-28T18:44:45",10,"*ничего не происходит ты работаешь вместе с мастером и ты вроде бы счастлив оказаться в знакомом безопасном месте. Ты видишь даже куда можно поставить свои вещи из коллекции*",34769,null],[80251,"2026-06-28T18:45:19",10,"*В реальности Харди сделал шаг вперед к зеркалу*",34769,null],[80252,"2026-06-28T18:45:44",9,"*Так летели часы, дни, мгновения вечности но ничто не могло побороть тягу к новому. Любопытство... в один момент рука словно сама потянулась к кристалу, узнать больше, изучить... мастерская не сможет удовлетворить его.*",34769,null],[80254,"2026-06-28T18:46:18",10,"//Спас мудрости",34769,null],[80256,"2026-06-28T18:48:17",10,"//я так понял ты тянешься к артефакту который тебя телепортировал?",34769,null],[80259,"2026-06-28T18:49:25",9,"/roll 1d20+1",34769,null],[80261,"2026-06-28T18:49:34",9,"//14",80260,null],[80262,"2026-06-28T18:50:14",10,"Ты видишь что артефакт стабильно работает и кольца больше не крутятся хаотично. Ты понимаешь что можешь ввести координаты места куда хочешь телепортироваться , но знаешь ли ты их или попробуешь случайно ввести ?",34769,null],[80263,"2026-06-28T18:50:39",10,"*в реальности еще шаг в сторону зеркала и Харди прислоняется рукой к его поверхности*",34769,null],[80264,"2026-06-28T18:51:36",10,"-Похоже он не справляется или просто хочет остаться там",34769,null],[80265,"2026-06-28T18:52:22",9,"— Я... я не знаю... — *Прошлый раз эта вещь сработала сама, а сейчас, он не знал, попытка вспомнить ничего не дала. Прошло ещё некоторое время, и вот Хардинт всё равно вернулся к кристалу.*",80262,null],[80266,"2026-06-28T18:52:59",8,"– Может, дёрнем его к нам? Я тоже начинаю беспокоиться",34769,null],[80267,"2026-06-28T18:53:14",9,"— Я не знаю, но не знал и прошлый ра... — *Он подымает молот и бъет по кристалу.*",34769,null],[80270,"2026-06-28T18:53:32",10,"-Тело его может и тут а вот разум? Если мы насильно оттянем его то разум может остаться там",80266,null],[80271,"2026-06-28T18:53:52",9,"*С мыслями или рванёт или перенесёт.*",80267,null],[80272,"2026-06-28T18:53:54",10,"*накладываю гайденс на Харди в надежде помочь* -  Надеюсь что это хотябы немного облегчит его путь",34769,null],[80274,"2026-06-28T18:54:38",10,"//Мотивация какая? ты решаешь отказаться от безопасности этого места ради исследований ?",80271,null],[80276,"2026-06-28T18:55:34",9,"— Прощайте учитель... впш ученик слишком егоистичен и любопытен...",34769,null],[80277,"2026-06-28T18:55:42",10,"Шепот леса : Мастер тебе говорит: Харди ты уверен? Тут всегда тебе рады , полно работы и безопасно.*",34769,null],[80278,"2026-06-28T18:56:01",10,"//спас мудрости + гайденс финальный",34769,null],[80279,"2026-06-28T18:56:22",8,"(Можно помощь?)",34769,null],[80281,"2026-06-28T18:56:42",10,"// да почему нет. Попробуй подбодрить его",34769,null],[80282,"2026-06-28T18:56:43",9,"/roll 1d20+1 мудрость",34769,null],[80284,"2026-06-28T18:56:45",8,"/шлейф из цветочных запахов по направлению к нам/",34769,null],[80286,"2026-06-28T18:57:05",8,"/чтобы помочь вернуться в реальность/",34769,null],[80287,"2026-06-28T18:57:09",10,"//Шо там ? докинь еще гайденс и видимо помощь",80283,null],[80289,"2026-06-28T18:57:39",9,"//Я не знаю что такое гайденс",80287,null],[80291,"2026-06-28T18:57:50",10,"//1к4 докинь",34769,null],[80292,"2026-06-28T18:57:51",9,"//С помощью 20",80290,null],[80295,"2026-06-28T18:58:28",10,"Харди вырвался из иллюзии отказавшись от идеального прошлого ради исследований",34769,null],[80299,"2026-06-28T18:58:52",9,"— Мой учитель бы наказал меня даже за мысль чтобы коснутся кристала. — *Усмехнулся.*",80277,null],[80301,"2026-06-28T18:59:18",9,"*Это похоже уже в реальности.*",80299,null],[80302,"2026-06-28T18:59:34",8,"– Ты был изрядно им привлечён. Что-то крайне приятное, да?",34769,null],[80305,"2026-06-28T19:00:31",9,"— Работа, спокойствие. Но... моя жизнь никогда такой не была, это быстро надоело. — *Произносит с ноткой грусти, к вам вернулся очень меланхоличный парень.*",34769,null],[80306,"2026-06-28T19:00:55",10,"*от Зеркала ты больше ничего не ощущаешь , Но перемены были в тебе*",34769,null],[80307,"2026-06-28T19:01:00",10,"-Ну видимо моя очередь",34769,null],[80310,"2026-06-28T19:01:51",10,"//все минут 5 и мы закончили)",34769,null],[80312,"2026-06-28T19:01:53",9,"//Вот если бы его завалило испытаниями он бы там и остался 😅",34769,null],[80319,"2026-06-28T19:02:29",8,"– Я ещё неопытна до тифлингов, но знаю, что радости свои у всех *приободряюще улыбается* Рада, что тебе нравится больше веселья. С нами будет лучше)",80305,null],[80320,"2026-06-28T19:02:31",10,"//еще шаг оставался до входа) Ваще ты успешно прошел все испытания, а то покрылся бы стеклом",34769,null],[80321,"2026-06-28T19:02:41",10,"//Просто ты не пытался вырваться вот и не выходил",34769,null],[80322,"2026-06-28T19:03:07",10,"-Интересно что покажет зеркало тому кто ничего не имеет",34769,null],[80323,"2026-06-28T19:03:08",10,"* **Иллюзия:** Роскошная кузница-лаборатория. На стенах — чертежи величайших артефактов, которые он когда-то создавал. Наставник с медальона протягивает ему кузнечный молот и толстую книгу его утерянных воспоминаний, а у костра в безопасности сидит его друг Хардинт. Пруд предлагает вернуть память и былую силу мастера прямо сейчас.\n * **Шепот леса:** *«Зачем тебе эта пустота в голове? Мир вокруг пугает тебя. Зачем учиться заново, если можно просто забрать то, что принадлежало тебе? Шагни в зеркало, верни себя...»*",34769,null],[80342,"2026-06-28T19:06:05",10,"-Так вот какой была моя жизнь? *провожу рукой по кузнечному молоту и чертежам* - Но это ведь больше не буду я? У меня уже появились новые хобби и воспоминания. Я уже другой человек. *Оглядываюсь на учителя* - И твоя голова будет выглядеть отлично в виде фонаря *бью кузнечным молотом по темечку учителя*",34769,null],[80343,"2026-06-28T19:06:16",10,"/r 1d20+1d4",34769,null],[80346,"2026-06-28T19:06:25",10,"//шо там?",34769,null],[80349,"2026-06-28T19:06:52",8,"/22",34769,null],[80350,"2026-06-28T19:06:58",9,"//Чистя 20 и 2, тоесть 22, крит среди критов! Мои двойки ^^",80344,null],[80352,"2026-06-28T19:07:28",8,"/хэдшот",34769,null],[80354,"2026-06-28T19:07:33",10,"**Учитель теряет сознание и Багровый делает из неё фонарик. Лучший из тех что он делал. И иллюзия рассыпается*",34769,null],[80356,"2026-06-28T19:08:17",10,"-хм теперь я не буду гнаться за прошлым. Хотя *смотрю в руку где был фонарь* такую идеальную работу я наверное больше не сделаю.",34769,null],[80357,"2026-06-28T19:09:04",10,"//Для чайников в первом квесте моего Аасимара без памяти разозлил один некромант и он из его головы в порыве вдохновения сделал магическую безделушку. Фонарь",34769,null],[80358,"2026-06-28T19:09:15",8,"– Она была особенно эстетичной, функциональной или что? *недоумённо*",80356,null],[80359,"2026-06-28T19:09:26",10,"-Она была идеальной во всем",34769,null],[80360,"2026-06-28T19:10:06",9,"— Иллюзии слишком хороши. — *Подходит ближе, хлопает по плечу, явно подмазывается.* — Мой учитель говорил что совершентво в несочершенстве. Как меч воина со сколами и местами починки, но со своей историей.",34769,null],[80361,"2026-06-28T19:10:51",10,"Зеркало исчезает в пруду и из пруда появляется стол и три шкатулки. Они текут как жидкость пока не обретают форму и застывают",34769,null],[80362,"2026-06-28T19:11:14",10,"-Это правда. Но теперь я знаю как выглядит идеальная работа для моего хобби",80360,null],[80363,"2026-06-28T19:11:37",8,"– Однажды ты точно создашь свою калокогатию)",34769,null],[80364,"2026-06-28T19:12:05",9,"— Лучше не трогать... — *Достает, не поверите, шест и с подозрением открывает шкатулки на расстоянии, пытается.*",80361,null],[80365,"2026-06-28T19:12:20",9,"/roll 1d20+2 ловкость рук)",34769,null],[80367,"2026-06-28T19:12:24",8,"*берёт волшебной рукой шкатулку*",34769,null],[80368,"2026-06-28T19:12:28",10,"Нормальные шкатулки. Награда достойная испытания",34769,null],[80369,"2026-06-28T19:12:44",9,"// 16 для инсайд",80366,null],[80370,"2026-06-28T19:13:00",10,"-Вы слишком осторожны *Открываю свою шкатулку и забираю награду* //потом напишу чо там",34769,null],[80371,"2026-06-28T19:13:07",9,"*Одобрительно кивает.*",80367,null],[80372,"2026-06-28T19:13:25",8,"(Свою взял?)",34769,null],[80373,"2026-06-28T19:13:34",10,"-Мы прошли испытания не для того чтобы награда нас убила. Это не логично",34769,null],[80374,"2026-06-28T19:13:52",8,"/если не взял, ему тоже его передаю/",34769,null],[80375,"2026-06-28T19:13:57",9,"//Лан, тут опыт ведущему всегда 20 а остальным 20-200 за отыгрыш на усмотрение ведущего",34769,null],[80376,"2026-06-28T19:14:10",10,"//я свою взял) вы как хотите) на шест не реагирует. просто звенит. и Рука подняла шкатулку",34769,null],[80377,"2026-06-28T19:14:17",9,"— Всегданадо быть осторожным.",80373,null],[80378,"2026-06-28T19:14:41",9,"*Взял свою и отошёл с озера на землю.*",34769,null],[80379,"2026-06-28T19:14:43",10,"//Думаю мы отлично все отыграли) по 200 опыта заслужено",34769,null],[80380,"2026-06-28T19:15:06",10,"-Давайте выйдем и закончим на сегодня.",34769,null],[80381,"2026-06-28T19:15:17",8,"– Как говаривала матушка, подготовь заклинания, но излишне не стрессуй *отходит со своей шкатулкой*",80377,null],[80382,"2026-06-28T19:15:27",9,"*Собирается и идёт.*",34769,null],[80383,"2026-06-28T19:15:53",8,"/тоже идёт/",34769,null],[80384,"2026-06-28T19:16:03",10,"*Когда вы путешествуете назад вы чувствуете что лес больше не звенит. Музыка больше не играет. Стекло крошится от прикосновения*",34769,null],[80385,"2026-06-28T19:16:50",8,"*Изольда чуть не плачет* – Неужели никто больше не увидит этого совершенства?",34769,null],[80386,"2026-06-28T19:16:54",10,"*Оглядевшись на пруд вы видите что он застыл и больше не сияет*",34769,null],[80387,"2026-06-28T19:17:24",10,"-В памяти он всегда с тобой * Делаю безделушку фоторамку и запечатливаю красоту этого места для Изольды*",34769,null],[80388,"2026-06-28T19:17:46",10,"-Это теперь навсегда с тобой.",80090,null],[80389,"2026-06-28T19:18:22",10,"*Просто фоторамка с изображением Хрустального леса. Фотография это иллюзия только застывшая в моменте*",34769,null],[80390,"2026-06-28T19:19:02",8,"– Спасибо. Я попрошу художника перерисовать картинку и дам копию первому встречному)",34769,null],[80391,"2026-06-28T19:20:10",10,"Стоит последнему герою выйти из леса и перешагнуть невидимую границу между жизнью и стеклом вы слышите грохот. Обернувшись видите лес и удивленных зверей.",34769,null],[80392,"2026-06-28T19:20:29",10,"* Вместо хрустальных стволов — вековые дубы и сосны, покрытые мхом.\n * Вместо стеклянных листьев — мягкая зеленая листва, мирно шелестящая на ветру.\n * Вместо острого хрусталя под ногами — обычная земля, хвоя и старая трава.\nДревнее проклятие пало. Лес вернулся к своему истинному первозданному облику. Герои стоят на опушке, согретые обычным солнечным светом. Они стали сильнее, мудрее, обрели редкие артефакты и, самое главное, поняли, что в этом пугающем мире они больше не одиноки.",34769,null],[80393,"2026-06-28T19:21:45",10,"//Вот и конец истории господа. Надеюсь было вайбово и прикольно. Спасибо за игру. награды я сейчас подшаманю",34769,null],[80394,"2026-06-28T19:21:52",10,"//Пока запишите +200 опыта",34769,null],[80395,"2026-06-28T19:23:00",9,"— Багровый. Я немного свыкнусь с ремеслом и хотел бы вашей помощи в исследованиях и поиске рецептов. Взамен буду вам помогать в ваших делах, у меня есть три компетентных помощника, свиснул их с мастерской учителя совершенно случайно. — *Из за спины выглядают три конструкта.*",34769,null],[80396,"2026-06-28T19:23:00",8,"/локация очень атмосферная вышла. Описания достаточно вайбовые тоже. Плюс механики, завязанные на звуках, а не гоблинах/",80393,null],[80397,"2026-06-28T19:23:16",9,"//Да, я не ожадал ничё такого, кайфарики",34769,null],[80398,"2026-06-28T19:23:17",10,"-Конечно. я буду только рад",80395,null],[80399,"2026-06-28T19:23:25",10,"//го в лс хард",34769,null],[80412,"2026-06-28T19:53:29",10,"| **Хрустальная Шкатулка Странника** | Харди | *Сумка хранения* | Шкатулка из металлических колец с зеркальной крышкой. Вмещает до 250 кг предметов в карманном измерении. Позволяет Хардинту упорядочивать свою коллекцию деталей и использовать её как мини-верстак (Инструменты ремесленика).",34769,null],[80414,"2026-06-28T19:53:35",10,"| **Призматическая Маска Маскарада** | Изольда | *Шапка маскарада* | Маска из дымчатого хрусталя, переливающаяся на свету. Позволяет сотворять заклинание *Зеркальная Маскировка* неограниченно. При смене облика лицо на секунду покрывается зеркальными гранями. | Требуется настройка",34769,null],[80415,"2026-06-28T19:53:39",10,"| **Окуляр Забытого Мастера** | Багровый | *Очки детального зрения* | Хрустальный монокль в астральной оправе. Дает **преимущество на проверки Анализа (Investigation)** предметов в пределах 1 фута. Подсвечивает скрытые механизмы багровыми линиями. |",34769,null],[80420,"2026-06-28T19:59:11",10,"Дальше награды по желанию . Наши персонажи прошли через личностный рост и вы можете изменить в анкете персонажа черту характера ( НЕ ДОП ЧЕРТА НА ПЕРСОНАЖА. это биография для рп)",34769,null],[80421,"2026-06-28T19:59:13",10,"Новая черта характера и особенность:\n​Хардинт («Исследовательский риск»): Осознание того, что знание стоит риска, открывает в нем новые ментальные резервы. \n​Механика: Когда Хардинт совершает проверку Магии (Arcana), Истории (History) или Анализа (Investigation) для изучения неизвестного предмета, руин или ловушки в опасной обстановке (например, во время боя), он может пойти на осознанный риск. Он получает преимущество на эту проверку. Однако, если бросок оказывается провальным, следующая атака по нему до конца его хода совершается с преимуществом, так как он слишком сильно увлекся исследованием и потерял бдительность",34769,null],[80422,"2026-06-28T19:59:28",10,"* **Изольда:** Получает уникальную особенность *«Взгляд из-за кулис»*. Опыт распознавания фальшивых лиц дает ей постоянное **преимущество на проверки Проницательности (Insight)**, когда она пытается определить, находится ли существо под иллюзией, маскировкой или ментальным очарованием.",34769,null],[80423,"2026-06-28T19:59:39",10,"* **Багровый:** Получает черту *«Шаг в неизвестность»*. Он обретает **бонус +2 к спасброскам против Испуга**. Кроме того, когда он впервые видит незнакомый магический предмет, его подсознательные навыки мастера активизируются, давая преимущество на первую проверку *Магии (Arcana)* для этого предмета.",34769,null],[80429,"2026-06-28T20:04:10",10,"Fantomas",34769,null],[80431,"2026-06-28T20:06:28",8,"Т.е. при желании одну черту изменить на эту?",80420,null],[80432,"2026-06-28T20:08:32",10,"при желании ты можешь изменить в анкете персонажа там где написано : ЧЕРТА ЛИЧНОСТИ",80431,null],[80433,"2026-06-28T20:08:55",10,"типа ты выросла и отвергла то что было в иллюзии и поняла лучше чего хочешь",34769,null],[80434,"2026-06-28T20:09:51",8,"А, ок",34769,null],[80436,"2026-06-28T20:11:12",10,"Эволюция Личности (Новая черта)\n​Отказ от идеальной фальшивки ради непредсказуемого реального будущего делает хаотичную натуру Изольды её силой. Мастер предлагает игроку добавить черту:\n​Новый Идеал/Черта: «Импровизация жизни. Идеал — это клетка для искусства. Я буду менять маски и сценарии так часто, как захочу, и никто не сможет запереть меня в шаблоне».\n​Уникальная особенность «Взгляд из-за кулис»: Изольда выросла, оценивая покупателей на рынке, а испытание пруда показало ей «идеально поддельные» лица. Теперь её способность читать людей обостряется. Она получает постоянное преимущество на проверки Проницательности (Insight), когда пытается определить, находится ли существо под поддельным личинами, иллюзиями или магическим очарованием.",80434,null],[80437,"2026-06-28T20:12:40",8,"/извини за тупизм, просто механика новая/",34769,null],[85728,"2026-07-01T15:33:00",9,"//Слелайте это сообщение щакреплённым кто нибудь ~",42765,null],[115129,"2026-07-14T20:47:09",9,"ХХХХХХХХХХХХХХХХХХХХХХ",34769,null],[115130,"2026-07-14T20:48:11",5,"На место встречи прибыли дракон и троглодит. (В компании кентавра?)",34769,null],[115131,"2026-07-14T20:48:37",9,"// @sweetkittywitch @elsio28 @Ashenchampion сорян, в ирл были дела. Залетайте если ещё актуально. Можете кого-то ещё с собой прихватить, бунчев вродт хочет.",34769,null],[115132,"2026-07-14T20:50:49",9,"*Хардинт, ваш проводник и знакомый, вёл через горы экспедицию, по знакомым тропам.*\n\n//Представьте своих персов, имя и арт пж",34769,null],[115135,"2026-07-14T20:51:25",41,"( локация пустошь ?",34769,null],[115137,"2026-07-14T20:52:10",17,"/ Меня возьмёте?",34769,null],[115138,"2026-07-14T20:52:22",41,"( я только за",115137,null],[115139,"2026-07-14T20:52:34",5,"Аметистовый драконорождённый Гвиндшарх, его сопровождает глазастый троглодит",34769,null],[115141,"2026-07-14T20:52:52",9,"*Знакомая картина, руины, камни с рунами друидов. Похоже этой тропой пользуются часто.*\n\nХардинт — Не сорвитесь с края, падать здесь высоко и далеко. — *Он посмотрел вниз, где не видно подножия из стелящихся туманов.*",48887,null],[115142,"2026-07-14T20:53:03",41,"По пути Соль прихватывает своего бывшего телохранителя. В прошлый раз он очень круто провел их мимо семьи волков",34769,null],[115143,"2026-07-14T20:53:40",41,"( Как хорошо, что для Соли вы баклажан и огурец",115139,null],[115144,"2026-07-14T20:53:51",17,"Немой контрабандист. Скрытный и мало эмоциональный. Идёт на дело за наградой или добычей, а не ради идеи.",34769,null],[115145,"2026-07-14T20:54:01",5,"// огурец я понимаю... но баклажан?",115143,null],[115146,"2026-07-14T20:54:10",41,"( фиолетовый",115145,null],[115147,"2026-07-14T20:54:21",5,"// неет это красивый дракоша",34769,null],[115148,"2026-07-14T20:54:42",41,"Соль Ён. Прекрасная дева зимы, чей холод мягкий как первый снег",34769,null],[115149,"2026-07-14T20:55:05",5,"— Вижу, у тебя появилось сопровождение. Как звать? Меня — Нориксиус Гвиндшарх",115144,null],[115150,"2026-07-14T20:56:26",41,"Соль невинно посмеялась. \n\n— Имя этого господина: Фауст. Он не может говорить.",34769,null],[115151,"2026-07-14T20:56:39",17,"Фауст кивнул",115150,null],[115152,"2026-07-14T20:56:59",5,"Дракон кивнул в ответ",34769,null],[115153,"2026-07-14T20:59:25",9,"*Хардинта заинтересовали руны на камнях, он видел их и прошлый раз.*\n\nХардинт — Кто-то знает друидический?",34769,null],[115154,"2026-07-14T20:59:25",17,"Эладрин достал верёвку из рюкзака и повесил на ремень. А еще шлямбуры. Положил их в нагрудный карман.",34769,null],[115155,"2026-07-14T21:00:16",9,"//А то сук уже 3й раз мимо камней иду, а друидов так и нет 👍",34769,null],[115156,"2026-07-14T21:00:33",41,"( могу кинуть проницательность чтоб попытаться разобрать иероглифы внешне ? Может они как египетские",115153,null],[115157,"2026-07-14T21:01:18",5,"— Нет, только драконий. А мой спутник, его зовут Гниляк, знает ещё дварфийский ии нферальный",115153,null],[115158,"2026-07-14T21:01:33",9,"*Руны можно нащупапь пальцами, форму и знаки. Они прям вырезанны на валунах.*",34769,null],[115159,"2026-07-14T21:01:44",41,"Девушка из интереса касается рукой надписи, пытаясь понять форму данных символов, есть ли схожесть этого языка с сильван?",34769,null],[115160,"2026-07-14T21:02:24",9,"*Это друидические руны, схожесть есть, но она минимальная.*",115159,null],[115161,"2026-07-14T21:02:36",5,"Гвинди достал блокнот и перерисовал руны туда.",115158,null],[115162,"2026-07-14T21:02:44",5,"// могу потом найти друида?",34769,null],[115163,"2026-07-14T21:02:57",41,"( есть ли возможность провести ассоциации?",115160,null],[115164,"2026-07-14T21:03:13",17,"Фауст тоже достал блокнот и повторил зарисовку за драконорожденным",34769,null],[115166,"2026-07-14T21:03:25",41,"( хотя если не дал, то вряд ли",34769,null],[115167,"2026-07-14T21:03:44",9,"Хардинт — Только не используйте магию рядом с ними. — *Вспомнил что говорил Багровый прошлый раз, предупреждал.* — Я не знаю что с ними, один мой хороший знакомый был ими сильно насторожен.",34769,null],[115168,"2026-07-14T21:05:15",9,"Хардинт — Раз никто не знает, пойдём. Если получится найти лруида и узнать что это, буду очень рад узнать, самому лчень интересно. — *Попросил тех кто записывал.*",34769,null],[115169,"2026-07-14T21:05:17",41,"— Если рядом с этими рунами странно работает магия, то это… \n\nОна не продолжила, но явно догадалась. Её глаза скользнули на Фауста.",34769,null],[115170,"2026-07-14T21:06:01",41,"Она сказала на сильван\n\n— Фейская тропа",34769,null],[115172,"2026-07-14T21:07:01",5,"— Да, найду тебя в таверне, когда узнаю сам",115168,null],[115174,"2026-07-14T21:07:12",17,"Фауст лишь дёрнул плечами\n\n\"Мол, может быть, не знаю\"",34769,null],[115175,"2026-07-14T21:08:26",11,"— Знали мы одного друида.. — Иштар молча шел за Гвинди всё это время",34769,null],[115176,"2026-07-14T21:08:30",5,"— У меня нет магии. По крайнем мере в привычном смысле",115167,null],[115177,"2026-07-14T21:09:26",41,"Она слегка испуганно и тихо сказала, почему-то полагаясь на то, что Фауст её услышит и тем более сделает\n\n— Прошу, их нужно повредить, пока их не привели в действие… пока остальные не видят. \n\n— Нам правда лучше уйти, если это место опасно.",34769,null],[115178,"2026-07-14T21:09:40",5,"Дракон вслушался в слова, но не понял.\n\n— Соль, переведи нам, пожалуйста!",115170,null],[115179,"2026-07-14T21:10:18",41,"— Я не знаю, что тут написано. Просто догадывалась. Можем идти…",115178,null],[115180,"2026-07-14T21:10:56",5,"— Но ты сказала что-то. Не хочешь поделиться догадкой?",115179,null],[115181,"2026-07-14T21:11:31",17,"Фауст написал в блокноте \n\n\"Не трогай странные символы, чтобы не было беды. Я тут чтоб никто не помер от шальной магии. Трогать их я не буду. И вам не надо.\"",115177,null],[115182,"2026-07-14T21:11:36",17,"Показал Соли",34769,null],[115184,"2026-07-14T21:12:24",5,"Гвиндшарх смотрит на Соль и Фауста, пытаясь догадаться, о чём идёт речь. И что важнее, почему они это скрывают.",34769,null],[115186,"2026-07-14T21:12:51",17,"Показал и дракониду тоже",34769,null],[115187,"2026-07-14T21:12:58",11,"Воин посмотрел на это всё скептически, а затем обратился к Харди:\n\n— Возможно поладить будет трудно — выдохнул он",34769,null],[115189,"2026-07-14T21:13:13",41,"— Магия друидов очень не предсказуемая. Мои теории лишь … запутают. \n\nУвидев записи, Соль кивнула\n\n— Прости…",115181,null],[115191,"2026-07-14T21:13:31",5,"Дракон улыбнулся и сказал громко.\n\n— Озвучу для всех! Не трогай странные символы, чтобы не было беды. Я тут чтоб никто не помер от шальной магии. Трогать их я не буду. И вам не надо.",115186,null],[115192,"2026-07-14T21:13:51",17,"Фауст показал знак \"Ок\"",34769,null],[115193,"2026-07-14T21:13:52",9,"Хардинт — Гвиди. Не всё должно быть сказанно вслух. — *А после добавил.* — Камни трогали при мне, ничего не произошло, но они реагируют на магию как я понял, лучше не рисковать. Мы идём к другому месту.",34769,null],[115194,"2026-07-14T21:13:56",11,"— Леди, если кто-то что-то скрывает то это лишь больше мотивирует выяснить что именно — теперь он подошёл к Соль и Фаусту что очевидно общались только между собой",34769,null],[115195,"2026-07-14T21:14:23",9,"//Первая сора 😂👍",34769,null],[115196,"2026-07-14T21:14:24",17,"Фауст отошёл и пошел за Харди дальше",34769,null],[115197,"2026-07-14T21:14:40",5,"— Я люблю раскрывать заговоры. Есть опыт, могу сказать. Возможно, вы даже в газетах читали...",115193,null],[115198,"2026-07-14T21:14:47",5,"// газетах элазии",34769,null],[115199,"2026-07-14T21:15:43",9,"Хардинт — Здесь где-то печатают газеты? — *Соегка удивился, он не слышал не встречал пока таких мест, в этом мире по крайней мере.*",115197,null],[115200,"2026-07-14T21:16:02",41,"—… если мои догадки меня пугают, почему я должна доверять их вам? Даже если я знаю, что это. Почему вы должны согласиться со мной ?",115194,null],[115202,"2026-07-14T21:17:05",5,"— Здесь...\n\nГвиндшарх огляделся и махнул рукой на пустошь.\n\n— Здесь нет. На юге земли цивилизованнеее будут. Там большие города и целые государства. И много новостей. А где новости — там газеты.",115199,null],[115203,"2026-07-14T21:18:31",17,"Эладрин пока осматривается на предмет следов или выделений различных монстров, чтобы в случае чего приготовиться",34769,null],[115204,"2026-07-14T21:18:40",17,"/r +4 Выживание",34769,null],[115207,"2026-07-14T21:19:34",17,"/ У всех прошу прощения, знаю что с немым персом скучно. Но это важно для персонажа и предыстории. На 4 будет телепат черта. Поговорим",34769,null],[115208,"2026-07-14T21:19:37",9,"Хардинт — А ещё отточеная налоговая и судебная система, стража и бумажная волокита? — *Явно забавлялся.*",115202,null],[115210,"2026-07-14T21:19:40",11,"— Как мы можем согласиться с вами если мы не знакомы с вашими догадками? — Он старается держаться на расстоянии что бы не пугать ее. В его словах нет агрессии, просто попытка объединить цели группы. И надежда что девушка помнит слова кентавра сказанные в таверне",115200,null],[115213,"2026-07-14T21:20:10",11,"// все норм",115207,null],[115214,"2026-07-14T21:20:34",41,"( всё в порядке. Мне интересно пробовать коммуницировать с помощью обобщения или других способов.",115207,null],[115215,"2026-07-14T21:20:43",5,"— Верно. Особенно близко мы с Иштаром познакомились с судебной системой. И стражей.",115208,null],[115216,"2026-07-14T21:20:50",9,"//Если мне поможет маг то могусделать серьгу сообщения",115207,null],[115217,"2026-07-14T21:20:58",9,"//А хотя...",34769,null],[115221,"2026-07-14T21:21:25",5,"— Но я вижу, тебя это только забавляет, Хардинт. И я не могу поспорить, у вольной жизни много преимуществ",34769,null],[115222,"2026-07-14T21:21:43",9,"Хардинт — Хах, угадал. Ну, одно без другого не бывает, правда.",115215,null],[115224,"2026-07-14T21:22:13",41,"Она сдается, ожидая что раскрытие предположения позволит положить конец её опасениям. \n\n— Это фейские тропы, скорее всего фейские тропы. Портал обходящий реальность через мир за пределами материального… Вошедший в портал может не выйти собой… а может вообще не выйти. \n\nОна обняла себя за плечи",115210,null],[115225,"2026-07-14T21:22:14",11,"Воин кивает на слова драконорожденного \n\n— Я действую так как кажется правильным. Я бы с уважением отнёсся к вашим догадкам, но мне тяжело уважать желание скрыть что-то от группы. Впрочем решать вам.",115215,null],[115226,"2026-07-14T21:22:20",9,"*Под редкими кустами можно было заметить человеческий скелет, кости под скалами, но лишь изредка, тихо.*",115205,null],[115227,"2026-07-14T21:23:32",5,"Дракон зорко смотрит вдаль. Есть ли живность в горах?  Кто летает в небе?",34769,null],[115228,"2026-07-14T21:23:34",11,"— Фейские тропы? — Он задумался вспоминая слова их проводника — я мало что знаю о культуре фей, но учитывая ваши слова и слова господина Хардинита все складывается. Возможно вы и правы",115224,null],[115230,"2026-07-14T21:24:28",9,"Хардинт — Я изучал этот вопрос, некоторые путешественники путешествуют по континенту фейскими тропами. Но согласен, опасное дело это. — *Вспомнил ещё кое что.* — А ещё есть фейский карнавал, но о нём не знаю ничего.",115224,null],[115232,"2026-07-14T21:24:45",17,"/ Фамильяр кстате ворон может озвучивать то что я ему мысленно передал вау",115216,null],[115233,"2026-07-14T21:24:58",5,"— Феи, фейские тропы... Я слышал рассказы от отца, но много не помню",34769,null],[115234,"2026-07-14T21:25:52",17,"Фауст задумался от чего погиб этот гуманоид. От падения, от монстра или от жажды и голода.",115226,null],[115235,"2026-07-14T21:25:57",5,"// кстати, а телепатический канал односторонний или двойной?",115232,null],[115236,"2026-07-14T21:26:01",41,"— Проводник Хардинт, прошу вас, если есть возможность скрыть или убрать эти письмена, можем ли мы это сделать ? Историческое открытие стоит такого риска ?",115230,null],[115237,"2026-07-14T21:26:11",11,"Иштар почесал затылок \n\n— Я там бывал, славное место",115230,null],[115238,"2026-07-14T21:26:40",17,"/ Односторонний, но я слышу что говорят. Так же есть вариант чтения мыслей в той же черте. Если существо позволяет можно общаться как телепатия - мысль как ответ",115235,null],[115239,"2026-07-14T21:27:14",9,"Хардинт — Нууу, мне всё равно. — *Смущённо потер щатылок, на него оставили столь важное решение.* — Можем скинуть их вниз, они всё равно на краю обрывов все.",115236,null],[115240,"2026-07-14T21:27:28",5,"// можно инфу?",115227,null],[115241,"2026-07-14T21:27:50",41,"( я думала они на скале вырезаны",115239,null],[115242,"2026-07-14T21:27:56",11,"— Кстати, господин Фауст, я ведь ещё не представился вам. Кентавр опустил на лапки Цереру и наконец-то поклонился как полагает — Иштар",34769,null],[115244,"2026-07-14T21:28:33",17,"Фауст приложил кулак к груди и поклонился",115242,null],[115245,"2026-07-14T21:28:35",9,"//Явно притащенные, лишь едва поросли мзом, на краю обрывов",115241,null],[115246,"2026-07-14T21:28:57",5,"— Разрушить камни? Боюсь, на неприятности нарвёмся",115239,null],[115247,"2026-07-14T21:29:01",9,"*Их съели и обглодали.*",115234,null],[115248,"2026-07-14T21:29:25",17,"/ Есть зазубрины от зубов на костях?",115247,null],[115250,"2026-07-14T21:29:55",41,"( тогда точно тропы",115245,null],[115251,"2026-07-14T21:30:17",41,"— Я не думаю, что мне хватит сил их скинуть, но если мы попробуем вместе ?",34769,null],[115252,"2026-07-14T21:30:19",9,"Хардинт — Мне самому не хочется их трогать. Люди здесь ходят и ничего не происходит,будто. Только пропадают иногда бесследно пл слухам.",115246,null],[115253,"2026-07-14T21:30:28",17,"Быстро нацарапал в блокноте\n\n\"Тут водятся опасные звери, возможно падальщики, но может хищники. Труп обглодан\"\n\nПоднял кулак вверх и показал всем",34769,null],[115255,"2026-07-14T21:30:56",11,"Иштар улыбнулся ему \n\n— Пусть ваши особенности не помешают нам поладить — он протянул руку для рукопожатия",115244,null],[115256,"2026-07-14T21:31:32",11,"*смотрю куда указывает Фауст*",115253,null],[115257,"2026-07-14T21:31:56",5,"/r +2 история как часто разрушение фейских камней приводило к проблемам",115252,null],[115259,"2026-07-14T21:32:22",17,"Пожал крепко в ответ",115255,null],[115260,"2026-07-14T21:32:38",17,"/ Там этот облоданый скелет гуманоида",115256,null],[115261,"2026-07-14T21:32:41",9,"*Хардинт вчитался в блокнот, подумал и снял с воротника крохотную серьгу.*\n\nХардинт — Держи, если что-то важное — сможешь нас быстро предупредить.\n\n//Серьгу сообщения тебе",115253,null],[115262,"2026-07-14T21:33:49",41,"Ну издалека Соль почти не может прочитать, потому подойдет \n\n— Спасибо, что предупредил. Тогда закончим дело и не будем больше шуметь …",34769,null],[115263,"2026-07-14T21:34:22",11,"— С летунами дело уже иметь приходилось, стрелять есть чем да и мой репертуар оружия довольно длинный — кентавр демонстративно похлопал оружие на своем крупе",115260,null],[115264,"2026-07-14T21:34:25",9,"*На счёт фейского колдунства не ясно. Но очень много историй как друиды вырезали деревни или убивали причастных если их знаковые места трогали.*",115258,null],[115265,"2026-07-14T21:34:53",41,"( не ну это дополнительный квест в придачу ура",115264,null],[115266,"2026-07-14T21:35:00",5,"— Не будем трогать камни. Друиды очень мстительные, слышал не раз!",115264,null],[115269,"2026-07-14T21:35:27",11,"// Харди, а Сера ничего не видит случаем?",34769,null],[115270,"2026-07-14T21:35:49",9,"//Что? Спросите — скажу",115269,null],[115271,"2026-07-14T21:36:02",41,"— Будем надеяться, что кроме друидов его никто не будет трогать…",115266,null],[115272,"2026-07-14T21:36:05",5,"Гвинди улыбнулся.\n\n— Летуны — моя любимая цель! Собью в 400 футах, только укажите. И сети есть, кстати",115263,null],[115273,"2026-07-14T21:36:07",11,"// ну ты сам дал мне диника с слепым зрением вот и уточняю",115266,null],[115274,"2026-07-14T21:36:12",11,"//",115270,null],[115275,"2026-07-14T21:36:41",17,"/такс ну я чекнул. Чтобы пользоваться серьгой нужно шептать сообщение и слышать будет владелец второй серьги только. Думаю это невозможно",115261,null],[115276,"2026-07-14T21:37:07",9,"//Пу пу пу, но ладно",115275,null],[115277,"2026-07-14T21:37:36",9,"//Сорян, думал хоть немного поможет",34769,null],[115279,"2026-07-14T21:38:02",9,"//Наложить заговор сообщение 5 раз, но ладно",115275,null],[115281,"2026-07-14T21:38:18",17,"Фауст покрутил серьгу в руке и вернул Хардингу он приступстил маску и показал ему лицо\n\nОтрицательно поматал головой",115261,null],[115282,"2026-07-14T21:38:24",5,"// этот заговор шёпотом накладывается",115279,null],[115286,"2026-07-14T21:39:20",5,"Троглодит Гниляк:\n— Хребты, а драконов нет! Надо идти дальше",34769,null],[115287,"2026-07-14T21:39:28",9,"Хардинт — Прости, думал сработает. Попытка не пытка. — *Извинился, он хотел помочь, но вышло как всегда, вернул серьгу себе где была.*",115281,null],[115288,"2026-07-14T21:39:31",41,"( его лицо только проводник видит ?",115281,null],[115289,"2026-07-14T21:39:47",41,"( хотя мне ли спрашивать ? Для меня он просто пятно голубое",34769,null],[115291,"2026-07-14T21:40:04",11,"*хлопаю по плечу*",115287,null],[115292,"2026-07-14T21:40:18",11,"// а как меня видишь? Хд",115289,null],[115293,"2026-07-14T21:40:31",41,"Коричневая куча",115292,null],[115294,"2026-07-14T21:40:39",11,"// жестоко",34769,null],[115296,"2026-07-14T21:40:51",9,"//Чекните когда идём, камни от части местная достопримечательность судя по всему",34769,null],[115297,"2026-07-14T21:41:03",17,"Эладрин моргунл знак \"Спасибо. Все понимаю\"",115287,null],[115299,"2026-07-14T21:42:51",41,"Соль долго смотрела на Фауста, лишь чуть чуть заметила швы на нижней части его лица. Но не была уверена. \n\n( это че у тебя, брекеты ?",34769,null],[115301,"2026-07-14T21:43:13",5,"— Фауст, у меня с собой кусочки мела. Возьмёшь себе? Чтобы мог написать нам, когда нет бумаги рядом. Мелом удобнее будет",115297,null],[115302,"2026-07-14T21:43:31",11,"// у него есть дневник ведь",34769,null],[115303,"2026-07-14T21:43:40",17,"Фауст сунул руку в сумку и между пальцев достал мел три куска\n\nКивнул в знак того, что все есть",34769,null],[115304,"2026-07-14T21:43:55",17,"Махнул рукой всем",34769,null],[115305,"2026-07-14T21:44:09",5,"— Хорошо. Если понадобятся ещё, я поделюсь",115303,null],[115307,"2026-07-14T21:44:56",17,"/ Жесты на сообщениях от Фауста чтоб не отписывать по 100 раз кивки и знаки \"Ок\")",34769,null],[115309,"2026-07-14T21:45:19",11,"// Всем очень нравится Фауст🫶",34769,null],[115313,"2026-07-14T21:46:03",41,"( ну он же лапочка",115309,null],[115314,"2026-07-14T21:46:30",41,"( его только я буллю",34769,null],[115315,"2026-07-14T21:47:19",5,"Гвиндшарх идёт по тропе, в основном смотря вдаль, а не под ноги. Смотрит не мелькнёт ли силуэт какой хищной птицы в небе.",34769,null],[115318,"2026-07-14T21:48:06",11,"// и меня тоже теперь?)",115314,null],[115320,"2026-07-14T21:48:27",41,"( ты могучая кучка )0",34769,null],[115322,"2026-07-14T21:49:28",5,"Дракон взял в руки блестящий дротик и прицелился\n\n— Смотрите, как я могу! Никто не посмеет подлететь\n\nДротик полетел по высокой траектории куда-то вниз со скал.",34769,null],[115323,"2026-07-14T21:49:39",11,"— Феи.. — тихо произнес Иштар вслух касаясь рукой своего амулета в форме морского конька. Ему вспомнилась прелестная Йинь что подарила его",34769,null],[115325,"2026-07-14T21:50:30",11,"— Ты хочешь что бы он вновь попал в кого-то? С нами сейчас придут друиды разбираться за то что ты бросаешь дротики куда непопадя..",115322,null],[115327,"2026-07-14T21:51:23",9,"//Дп",115309,null],[115329,"2026-07-14T21:52:14",9,"Хардинт — А зачем?",115322,null],[115330,"2026-07-14T21:53:47",9,"//Я вернулся, высвобождал перса игрока из плена и ирл сделал кое что. Скажите когда идём дальше? Я прост думал что вы посмотрите на камни и не будете устраивать детектив, но в целом круто вышло очень",34769,null],[115331,"2026-07-14T21:54:29",5,"— Мы в пустошах, тут никого нет. Кроме того...\n\nДракон раскрыл ладонь и там лежал тот же самый дротик.\n\n— Я контролирую его полёт. Возвращаю когда захочу",115325,null],[115332,"2026-07-14T21:54:39",11,"// он хвастается",34769,null],[115333,"2026-07-14T21:54:46",5,"// идём)",115330,null],[115335,"2026-07-14T21:54:56",11,"— Раньше у тебя таких штук не было, откуда взял?",34769,null],[115336,"2026-07-14T21:55:02",11,"// да, давай дальше",34769,null],[115337,"2026-07-14T21:55:04",5,"// пока ничего не происходило",115332,null],[115338,"2026-07-14T21:56:07",5,"— Помнишь утро, когда у меня было сильное похмелье. Вот в прошлый день пил с одной компанией. Мы удачно одно поручение выполнили, а дротик в награду получил за это",115335,null],[115339,"2026-07-14T21:56:12",9,"Хардинт — Оу. Я могу зачаровывать оружие, но чтобы само возвращалось? Нет. — *Смотрит на вещь с неподлельным интересом, явно магия.*",115331,null],[115342,"2026-07-14T21:57:59",11,"Иштар потянулся к дротику в руках друга и с его позволения взял оружие в руки, а затем что-то прошептал на древнем не переводимом наречии\n\n— Пускай духи направят твои броски, друг",115338,null],[115344,"2026-07-14T21:58:39",11,"— Фыр — издала звук малютка",34769,null],[115345,"2026-07-14T21:58:41",5,"Гвинди отдал дротик другу и понаблюдал за... ритуалом?",34769,null],[115346,"2026-07-14T21:59:15",5,"— Умеешь зачаровывать? А ты можешь зачаровать уже магическое? Ещё сильнее сделать?",115339,null],[115355,"2026-07-14T22:01:36",9,"Хардинт — Вряд-ли, чтобы наложить новые чары надо разрушить старые. — *Качает головой, улыбнулся чутка грустно.* — У меня не так много рецептов, и все от друга. А так, могу сделать оружие магическим, сделать сумку хранения или расчертить медали силы. Только начал собирать рецепты, магия здесь работает не так как привык, иначе смог бы намного больше.",115346,null],[115357,"2026-07-14T22:02:36",11,"— Если получится добыть что-то я обязательно покажу тебе, Хардинит",34769,null],[115362,"2026-07-14T22:03:44",9,"//Думаб надо дальше уде скакатт 100%, это место себя исчерпало",34769,null],[115364,"2026-07-14T22:04:28",9,"*Вы прошли мимо небольших руин какого-то селения от которого ничего не осталось кроме стен. Все что можно здесь было раскопанно до героев, а за ним тропа вела уже вниз, на другую сторону гор, в долину.*",34769,null],[115365,"2026-07-14T22:04:40",5,"— Интересные варианты. Я обращусь к тебе, когда будет нужда в этом",115355,null],[115370,"2026-07-14T22:05:16",5,"Гвинди смотрит в долину. Отсюда должен быть хороший обзор",115364,null],[115373,"2026-07-14T22:06:47",9,"*На следующий день, под горами, героев встретили цветочные поля. Далёкие словно сказка, под ногами расли всевозможные цветы, редкие, лечебные и просто красивые, горы укрывал рассвет. Розовые, фиолетовые облака.*",34769,null],[115375,"2026-07-14T22:07:04",5,"// на следующий день? тогда я съедаю рацион",115373,null],[115380,"2026-07-14T22:08:01",9,"//Я напишу сколько списать сегодня, ощущение что пол пати пропало, так что наверное это растянется дня на два.",115375,null],[115381,"2026-07-14T22:09:31",5,"Гвинди идёт по полю и завороженно смотрит.\n\n— Красота какая! И от Гниляка не так воняет...\n\nЗапах цветов и правда перебивает вонь троглодита.",115373,null],[115382,"2026-07-14T22:10:08",5,"Дракон наклонился и сорвал большой розовый цветок. Закрепил его на голове",34769,null],[115383,"2026-07-14T22:10:20",11,"Иштар чувствует себя здесь намного уютнее чем в городе. Открытая местность, запах знакомых и незнакомых цветов, звуки природы - все это навевало чувство ностальгии по дому и так любимую кентаврами свободу",115373,null],[115384,"2026-07-14T22:10:53",11,"Кентавр засмеялся\n\n— Тебе идёт! Не хочешь и мне такой же предложить?",115382,null],[115385,"2026-07-14T22:11:30",5,"Дракон улыбнулся.\n\n— Хочу и предлагаю. Какой цвет твой любимый?",115384,null],[115386,"2026-07-14T22:12:06",9,"Хардинт — Кажется, один мой знакомый использовал такие когда варил зелья. — *Держит в руках неприметное растение, цветок который мягко цветёт жёлтым с толстым стеблем и мясистый.*",34769,null],[115387,"2026-07-14T22:12:54",11,"— Выбери сам какой мне подойдёт — ответил воин и начал осматриваться вокруг в поисках чего-то полезного. \n\nИштар и сам неплохо разбирался в свойствах некоторых растений. Наследственные знания от всё той же бабули.",34769,null],[115388,"2026-07-14T22:13:07",5,"— Не только красивые, но и полезные? Удивительное место",115386,null],[115389,"2026-07-14T22:13:27",11,"— Хм? Впервые вижу такой цветок, но могу помочь найти таких ещё.",115386,null],[115390,"2026-07-14T22:13:39",11,"— У всех растений есть какие-то свойства, Гвинди",115388,null],[115391,"2026-07-14T22:14:09",5,"Дракон походил по полю и сорвал огненно-красный цветок.\n\n— Вот, тебе подойдёт!",115387,null],[115392,"2026-07-14T22:14:29",5,"— Свойства есть, польза редка. — возразил дракон",115390,null],[115393,"2026-07-14T22:15:17",9,"// Я так понял сегодня игра не пойдет дальше и вы заняты @sweetkittywitch и @dunchev ? Я могу завтра продолжить, разделим на две части если времени нет.",34769,null],[115394,"2026-07-14T22:15:35",41,"( сори, я только убрала… кухню",34769,null],[115395,"2026-07-14T22:16:08",9,"// Ничё, я просто спрашиваюч вы будто пропали, вот и беспокоюсь.",115394,null],[115396,"2026-07-14T22:16:31",9,"//А так перс рил знает рецепты и может скрафтить указанные предметы кому надо. Не для красного словца сказал 👍",34769,null],[115397,"2026-07-14T22:17:13",5,"// ещё и дешевле",34769,null],[115399,"2026-07-14T22:17:49",11,"— Многие растения имеют полезные в разных сферах свойства, дружище, не недооценивай даже маленькие вещи, все бывает полезным — Иштар взял цветок из рук друга и заплел себе в хвост, а затем обратился к остальным — Как вам?",34769,null],[115400,"2026-07-14T22:21:48",17,"/ Домой ехал. Все я тут",34769,null],[115401,"2026-07-14T22:21:52",9,"Хардинт — Ты большой. На тебя надо много венков. — *Хардинт прикинул и немного расмеялся.* — Даже веников. Можем сплести тебе плащ из цветов, правда не хотел бы сильно прорежать их.",34769,null],[115402,"2026-07-14T22:22:15",41,"Смеясь и восхищаясь красотой этого мыла, покружилась на поляне и упала в цветы",115373,null],[115404,"2026-07-14T22:23:08",17,"На лугу Фауст не испытывал благоговения, радости, все это великолепие он даже не оценивал с такой стороны.\n\nПотому что ему плевать на красоту, важна только эффективность, полезность и холодный расчет.\n\nПоэтому он целенаправленно искал тут ядовитые цветы вроде паслёна чтобы изготовить яд.",34769,null],[115405,"2026-07-14T22:23:10",41,"— Как пахнет! Ха-а-а-ах! Ребята , хотите тоже лечь ?",34769,null],[115406,"2026-07-14T22:23:12",9,"*Запах такой что голова кружится, но не на самом деле, просто приятно.*",115402,null],[115407,"2026-07-14T22:23:33",41,"( :0 капец",115404,null],[115408,"2026-07-14T22:23:56",9,"//Кинь природу/внимательность или выживание на выбор",115404,null],[115409,"2026-07-14T22:24:11",17,"/r +4 Выживание",115408,null],[115411,"2026-07-14T22:24:18",11,"— Тогда соглашусь на венок, от него большого вреда не будет? — Воин говорил весёлым голосом, но не врал\n\n// Я же не зря добавила в анкету что он любит такое:D",115401,null],[115412,"2026-07-14T22:24:50",41,"( Фауст, смотри какой классный синий цветок растет. Наверняка пригодится !",115410,null],[115413,"2026-07-14T22:24:58",41,"( меня разрывает",34769,null],[115414,"2026-07-14T22:24:58",11,"Поддавшись импульсу Соль кентавр так же валится на траву и дрыгает копытами как молодой жеребец",115402,null],[115415,"2026-07-14T22:25:07",9,"*Среди кучи цветов и красок, ядовитых было не так уж и много.*\n\n//Нашёл на 7 золотых ядовитых трав, это для крафта пригодиться, или просто в магаз продай и получи 7 щм потом",115410,null],[115416,"2026-07-14T22:25:47",41,"( капец если б вы знали аааааа",115412,null],[115417,"2026-07-14T22:25:51",5,"— А мне идея... Нравится",115405,null],[115418,"2026-07-14T22:26:13",41,"( Повалите Фауста в цветы пж",34769,null],[115419,"2026-07-14T22:26:30",41,"( пока он афк",34769,null],[115420,"2026-07-14T22:26:42",11,"— Присоединяйся, Гвинди!\n\nЦерера бодает Фауста с разгона что бы он присоединился к остальным",115418,null],[115422,"2026-07-14T22:27:01",41,"( МУХАХАХАХА >:D",34769,null],[115423,"2026-07-14T22:27:19",9,"*Хардинт хотел тоже собирать травки, но общее веселье его заразило и он лёг в цветы.*",34769,null],[115427,"2026-07-14T22:27:39",9,"*Мимо вас летит стая разноветных бабочек.*",34769,null],[115431,"2026-07-14T22:27:55",11,"— Ещё успеем, но момент упускать не стоит! — произнес Иштар любуясь бабочками и запахом цветов — как дома!",115423,null],[115435,"2026-07-14T22:28:17",9,"Хардинт — Синий, Зелёный, Красный. Покружите в небе, поищите что-то полезное.",34769,null],[115439,"2026-07-14T22:28:57",41,"( это Фауст, огурец и Иштар ?",115435,null],[115441,"2026-07-14T22:29:19",11,"— Твои подручные? — продолжая следить взглядом за бабочками кентавр почувствовал родные рожки у себя под бочком и прижал трайчонка в обнимашки",34769,null],[115442,"2026-07-14T22:29:38",9,"*Три механических слуги, размером чуть больше чем яйцо вылетили с портфеля и разлетелись в разные стороны.*\n\nХардинт — Теперь можно и отдохнуть.",34769,null],[115443,"2026-07-14T22:29:43",5,"Троглодит стоит среди цветов и жалуется:\n— Воняет!",34769,null],[115444,"2026-07-14T22:29:49",41,"Соль поднялась и попробовала приманить к себе бабочек благородным танцем",34769,null],[115446,"2026-07-14T22:29:54",5,"А Гвинди разлёгся и смотрит на небо",34769,null],[115447,"2026-07-14T22:29:59",41,"( кинуть выступление или уход за животными ?",34769,null],[115448,"2026-07-14T22:31:43",9,"*Бабочки совсем не боялись людей, одна села на палец, пару заинтересовало платье. А одна совсем прямо влетела в лицо и после небольшой \"аварии\" осталась на носу.*",115444,null],[115449,"2026-07-14T22:32:04",17,"/ Давай состязание",115420,null],[115450,"2026-07-14T22:32:18",17,"/r +6 Акробатически уклоняюсь",34769,null],[115451,"2026-07-14T22:32:18",11,"// сдавайся это сила милоты",115449,null],[115453,"2026-07-14T22:32:29",9,"//Еси шо, умением слуги брал, они ещё безобидные. У нас гоблин паладин так 3 гоблинов брал.",115442,null],[115454,"2026-07-14T22:33:10",11,"/r d20+4",34769,null],[115456,"2026-07-14T22:33:17",17,"Фауст делает сальто назад и трицепатопс проносится мимо",34769,null],[115457,"2026-07-14T22:33:20",41,"( я могу как монах дать какое-то преимущество Иштару ?",34769,null],[115458,"2026-07-14T22:33:26",17,"Он наклоняет голову на бок смотря на него",34769,null],[115459,"2026-07-14T22:33:31",17,"Знак не понимания",34769,null],[115460,"2026-07-14T22:33:38",11,"Трайчонок пыхтел, старался, но Фауст был шустрее малышки и уклонился от бодания",34769,null],[115461,"2026-07-14T22:34:04",11,"// тебя не кентавр бодал",115456,null],[115462,"2026-07-14T22:34:15",17,"/ Когда бабочки полетели я хотел бы высмотреть ядовитую особь и поймать",34769,null],[115463,"2026-07-14T22:34:20",5,"// ага, я видел. Даёшь преимущество трем союзникам на каждый бросок атаки в бою. Очень безобидные имба",115453,null],[115464,"2026-07-14T22:34:23",17,"/ а кто?))",115461,null],[115465,"2026-07-14T22:34:46",17,"/r +4 Выживание на поиск ядовитой бабочки",34769,null],[115467,"2026-07-14T22:34:53",11,"Деревянный трицератопс [ Церера ] \n\nРазмер: маленький \nХиты: 11\nКД: 10\nСкорость 20 футов.\nПассивное восприятие: 10\nИммунитеты: испуг/окаменение/ослепление/Яд/очарование/паралич\nУязвимость: огонь\nЧувства: слепое зрение 30 футов (слеп за пределами)\n\n🏋🏻Сила — 14 (+2)\n🤸🏻Ловкость — 10 (+0)\n🧍🏻Телосложение — 13 (+1)\n🙇🏻Интелект — 5 (-3)\n🦉Мудрость — 11 (+0)\n🕺🏻Харизма — 13 (+1)\n      БМ +2\n\nОсобенности:\n\nСильный. Динозаврик считается на размер больше при определении его грузоподъемности.\nУстойчивый. Динозаврик совершает с преимуществом спасброски Силы и Ловкости против эффектов, сбивающих его с ног.\nДеревянный. Не тонет.",34769,null],[115468,"2026-07-14T22:34:56",41,"Вдоволь наигравшись с бабочками, Соль увидит попытку Иштара уложить Фауста в траву. Вместо этого она подойдет к эладрину и посадит бабочку со своего носа на его нос\n\nСо своей руки ему на нос",34769,null],[115469,"2026-07-14T22:35:28",41,"( И ТУТ СОЛЬ ПОСАДИЛА НА НОС ФАУСТУ ЖУКА ТРУПОЕДА",115466,null],[115472,"2026-07-14T22:35:56",11,"— Ладно, валяться весело, но пора бы и делом заняться — сказал Иштар и поднялся беря в охапку малютку",34769,null],[115473,"2026-07-14T22:36:05",11,"— Харди, скажи какие цветы нужно собрать, я поищу",34769,null],[115476,"2026-07-14T22:37:27",5,"— Но здесь так хорошо... Не нужна мне слава, дайте жить здесь!",115472,null],[115478,"2026-07-14T22:37:58",11,"— Добейся славы и сможешь вернуться со мной в мое племя и жить так всегда, будешь моим названным братом",115476,null],[115479,"2026-07-14T22:38:23",9,"//Это не делает навык, я на своих квестах где Хардинт, чтобы вы не скопытились",115463,null],[115482,"2026-07-14T22:40:41",9,"Хардинт — Ну, тут легче начеркать. — *Берёт несколько листов и рисует на них заметки, как выглядят цветы.* — Вот, эти точно подойдут, а так я не травник, не успел обучится.",115473,null],[115483,"2026-07-14T22:41:01",9,"*Ни одна не ядовита.*",115466,null],[115484,"2026-07-14T22:41:16",11,"— Тогда я соберу ещё кое-что что знакомо и мне.. если повезёт найти, Гвинди, поможешь?",34769,null],[115485,"2026-07-14T22:41:34",9,"//Не надо, котюроче",115484,null],[115486,"2026-07-14T22:42:14",9,"//Вот, для каждого персонажа те же условия, без преимуществ",115408,null],[115487,"2026-07-14T22:42:34",5,"— Ого, это звучит... Невероятно! Спасибо, Иштар! Обещаю, я приду в твое племя однажды. Но сначала я должен добиться чего-то",115478,null],[115491,"2026-07-14T22:45:40",9,"/roll 1d20+3 хардинт ищет полезные растения",34769,null],[115493,"2026-07-14T22:45:48",9,"//Пу пу пу",34769,null],[115495,"2026-07-14T22:46:08",9,"//Нашёл на 23 золотых 😂👍",34769,null],[115496,"2026-07-14T22:46:21",17,"Пока группа дурачится или собирает травы эладрин поднялся на камень и как суррикат высматривает опасность",34769,null],[115497,"2026-07-14T22:46:30",9,"*Хардинт явно знает что ищет и сколько.*",34769,null],[115498,"2026-07-14T22:46:30",17,"/r +4 Высматривает",34769,null],[115503,"2026-07-14T22:47:28",11,"/r d20+2",34769,null],[115505,"2026-07-14T22:47:31",9,"*Ничего. Ничего. Ничего. Змея мимо ползёт. Ничего. Просто поля цветов, дикое место, нелюдное.*",115499,null],[115506,"2026-07-14T22:47:37",11,"// ничего не нахожу судя по всему:(",34769,null],[115507,"2026-07-14T22:47:54",9,"//На 4 золотых находишь травок лечебных",115504,null],[115511,"2026-07-14T22:48:41",11,"Понимая что здесь мало знакомого Иштар продолжил собирать просто красивые цветы. Отдав лечебные Харди он начал делать венки",34769,null],[115512,"2026-07-14T22:49:35",5,"/r +4 Гвинди повалялся по лугу, вдруг что-то под лапу попало",34769,null],[115516,"2026-07-14T22:50:50",9,"*Нашёл в яме под камнем кучу цветком каких показывал Хардинт.*\n\n//На 21 золотой трав лечебных",115513,null],[115517,"2026-07-14T22:51:54",9,"Хардинт — Думаю, я не хочу больше собирать. — *Просто сел отдыхать, достал пожевать что-то.*",34769,null],[115521,"2026-07-14T22:54:00",5,"— Что это такое? Похоже на те полезные цветочки.\n\nДракон поднялся и вручил их кентавру.\n\n— Возьми, Иштар! Ты прав, я не умею извлекать пользу из растений",115516,null],[115526,"2026-07-14T22:57:37",11,"— Лучше отдай Харди, у меня нет с собой инструментов алхимика — Ответил кентавр сплетая цветы между собой\n\nЗакончив с работой он отдал один Гвинди — лиловые цветы под цвет его чешуек сплетённые с зелёными травами, белыми и местами розовыми цветами, теми самыми что понравились Гвинди",34769,null],[115533,"2026-07-14T22:59:17",5,"— Так и сделаю.\n\nГвинди передал цветы ремесленнику, а потом увидел венок.\n\n— Какая красота! У тебя такие ловкие руки, Иштар. Спасибо за венок!\n\nДракон надел венок на голову и покрасовался",115526,null],[115535,"2026-07-14T22:59:46",11,"Он подошёл к обедающему Хардиниту сзади и надел ему на голову венок. В этом было больше зелени и белых цветов, местами мелькали редкие цветные. Такой же он подарил девушке. А Фаусту достался венок с темно синими цветами.",34769,null],[115539,"2026-07-14T23:00:21",11,"Не забыл кентавр и про Цереру, та сперва пыталась съесть цветы повинуясь инстинктам, но быстро успокоилась и гордо фыркнула",34769,null],[115540,"2026-07-14T23:00:43",17,"Фауст положил венок в сумку. Выкидывать сразу было бы невежливо и могло посеять зерно ненужного конфликта.\n\nТак что он подумав сделал тактично",34769,null],[115541,"2026-07-14T23:01:27",17,"/ Тут кроме поля ничего нет? Может есть дерево?",34769,null],[115548,"2026-07-14T23:03:21",17,"От скуки Фауст решил немного потренироваться он набрал таки охапку цветов подкинул их в воздух.\n\nДостал свой клинок и начал рубить бутоны пополам",34769,null],[115551,"2026-07-14T23:03:34",17,"/r +6 На вам цветы",34769,null],[115553,"2026-07-14T23:04:03",11,"Иштар заметил твою неприязнь, но пока решил оставить без внимания",115540,null],[115554,"2026-07-14T23:04:29",5,"— Сера, тебе идут! Не кушай, они красивые",115539,null],[115555,"2026-07-14T23:04:58",11,"— Не рационально так относиться к цветам — на плечо Фауста упала крепкая рука",115548,null],[115556,"2026-07-14T23:05:04",5,"— Скучаешь по битвам, Фауст?",115548,null],[115559,"2026-07-14T23:08:00",41,"( ты не ответил на бабочку на носу(((",115548,null],[115561,"2026-07-14T23:08:56",11,"// я вижу кто-то занят :3",34769,null],[115562,"2026-07-14T23:09:32",9,"*Хардинт подходит к тебе.*\n\nХардинт — Ты умеешь сражаться, вижу. Не мог бы показать пару приёмов? Хотел бы научиться нормально сражаться оружием.\n\n//Рапирой вособенности",115548,null],[115563,"2026-07-14T23:09:33",41,"( ну в магазин сходила. Про Одиссея послушала, трупы растворила",115561,null],[115564,"2026-07-14T23:10:04",17,"Киваю",115556,null],[115565,"2026-07-14T23:10:13",5,"// насчёт трупов можно детали?",115563,null],[115566,"2026-07-14T23:10:17",17,"Пожимаю плечами",115555,null],[115567,"2026-07-14T23:10:29",41,"Их больше нет",115565,null],[115569,"2026-07-14T23:11:51",41,"Соль захотела побежать немного дальше остальных, дабы поискать интересных живых существ",34769,null],[115570,"2026-07-14T23:11:59",17,"Фауст кивает.\n\nДостает свой клинок длинный кинжал. Показывает его Хардингу\n\nПосле показывает свою боевую стойку и пару выпадов в связке. Сначало медленно. Потом быстрее. Потом кивает и даёт своё оружее Хардингу",115562,null],[115572,"2026-07-14T23:12:37",41,"( могу кинуть внимание (слух) ?",34769,null],[115573,"2026-07-14T23:13:14",17,"/ В трусы сунуть же договаривались",115469,null],[115574,"2026-07-14T23:13:29",9,"*Пытается повторить, ещё раз и ещё раз, и ещё. Потихоньку у него начинает получаться почти полностью копировать стойку и выпады что он видел.*\n\n//Быстрый студент",115570,null],[115575,"2026-07-14T23:13:39",41,"( это было в прошлой жизни",115573,null],[115576,"2026-07-14T23:14:10",17,"/ Ну ты сам знаешь как засчитать тренировку. Я не шарю за обывателей",115574,null],[115579,"2026-07-14T23:15:01",41,"/r d20+4 слушаю",34769,null],[115581,"2026-07-14T23:15:08",9,"//Да, спс. На это и расчёт, правда, кажется мне надо другое орудие, ноэт отыгрыш всё равно и я не выбрал ещё",115576,null],[115582,"2026-07-14T23:15:17",41,"( ООООО ЖУК ТРУПОЕД, ПРИВЕТ",34769,null],[115583,"2026-07-14T23:15:56",9,"//Ты мож выбрать даже и описать сама что то размера маленького и меньше 😏👌",115582,null],[115584,"2026-07-14T23:16:28",41,"( ого, прямо питомца найти могу ? :000",34769,null],[115585,"2026-07-14T23:16:32",41,"( ой всё",34769,null],[115586,"2026-07-14T23:16:47",41,"( с нами щас будет ходить жук трупоед на поводке",34769,null],[115587,"2026-07-14T23:17:22",9,"Хардинт — Спасибо за пример, я постараюсь запомнить эти удары. — *Возвращает клинок как устал немного.*",115570,null],[115588,"2026-07-14T23:18:06",17,"Показывает парню большой палец вверх",115587,null],[115589,"2026-07-14T23:18:08",9,"//Не питомца, а выбрать кого нашла и описатькак. На счёт питомца это уже дело техники что дальше",115584,null],[115590,"2026-07-14T23:18:49",41,"( оооох я знаю что я найду",34769,null],[115591,"2026-07-14T23:19:00",41,"( у Коли щас ТАКИЕ флешбеки пойдут",34769,null],[115592,"2026-07-14T23:19:13",41,"( и идеи интересные",34769,null],[115593,"2026-07-14T23:20:09",41,"— Ребята, ребята, я нашла кусочек солнца! Смотрите! \n\nДействительно, что-то в цветах очень ярко блестело золотом",34769,null],[115595,"2026-07-14T23:21:20",9,"*Парень как раз вернул клинок и идёт посмотреть что нашла леди Соль.*",34769,null],[115596,"2026-07-14T23:22:37",41,"@dunchev  у тебя там билд Шана, говоришь)))))",34769,null],[115597,"2026-07-14T23:23:22",17,"/ И чё это я не понял лол",34769,null],[115598,"2026-07-14T23:23:30",41,"( щас нагенерю",34769,null],[115599,"2026-07-14T23:23:49",17,"Фауст тоже пошел смотреть, что шебутная нашла",34769,null],[115603,"2026-07-14T23:28:35",41,"Sheep, here we go again",34769,null],[115604,"2026-07-14T23:30:16",17,"/ Я клянусь не помню золотую овцу",34769,null],[115605,"2026-07-14T23:30:28",41,"( Кошмар",34769,null],[115606,"2026-07-14T23:30:31",17,"/ Ну может я так называл файну по приколу",34769,null],[115607,"2026-07-14T23:30:38",17,"/ я не помню",34769,null],[115608,"2026-07-14T23:30:43",41,"( золотого овна не помнишь ???",34769,null],[115609,"2026-07-14T23:30:55",41,"( которого Шан побил и съел ???",34769,null],[115610,"2026-07-14T23:30:57",17,"/ Бля это про это ладно понял",34769,null],[115611,"2026-07-14T23:31:05",9,"//Если это ягнёнок, они безобидны мож оставить персу. Потом обсудим в лс его.",115605,null],[115612,"2026-07-14T23:31:07",17,"/ Такс ну чего мграем",34769,null],[115613,"2026-07-14T23:31:30",41,"( я думала ты за Фауста предложишь его приготовить хд",115612,null],[115614,"2026-07-14T23:32:04",41,"( у вас 4 голодных мужчины на сухпайках",34769,null],[115615,"2026-07-14T23:32:08",9,"Хардинт — Никогда такого не видел. Чей он, может потерялся. — *Смотрит вокруг, не видит ни одной золотой овцы.*",115603,null],[115616,"2026-07-14T23:33:00",41,"— Он такой маленький и кудрявый. Можно он пойдет с нами ? По пути может и мать найдем. \n\nЗадумалась Соль",34769,null],[115620,"2026-07-14T23:35:27",9,"// @Ashenchampion гвиди спит уже? Если так можем завтра уже продолжить",34769,null],[115621,"2026-07-14T23:35:31",17,"Фауст пишет в блокноте\n\n\"Давайте его пустим на вяленое мясо. Запасы кончаются.\"",34769,null],[115622,"2026-07-14T23:36:00",11,"// нет, мы просто не мешаем им",115620,null],[115623,"2026-07-14T23:36:03",17,"Показывает Соли и остальным отличное на его взгляд предложение",34769,null],[115624,"2026-07-14T23:36:12",11,"// ибо тут отсылки нас не касающиеся",34769,null],[115625,"2026-07-14T23:36:15",17,"/ Давай играть я просто ищу момента",115622,null],[115626,"2026-07-14T23:36:35",17,"/ Да Эль, заканчивай отсылки, пишем новую историю",115624,null],[115627,"2026-07-14T23:36:40",9,"//Мы пишем новые истории, вы не мешаете",115624,null],[115628,"2026-07-14T23:36:47",17,"/ Надо съесть барашка",34769,null],[115629,"2026-07-14T23:37:21",11,"// ну я попыталась порпшить, не очень получилось, так что жду дальше движений сюжета",34769,null],[115630,"2026-07-14T23:37:40",11,"// и дракон Гвинди если что^^",34769,null],[115631,"2026-07-14T23:37:58",5,"// да, уже ухожу",115620,null],[115632,"2026-07-14T23:38:11",11,"// ну тогда звиняйте",34769,null],[115633,"2026-07-14T23:38:51",9,"Хардинт — Нууууу... — *Ягнёнок слишком маленький, а учитывая радость Соль... ну нет желания её расстраивать.* — Неверное не нужно, да и сколько его.",115623,null],[115635,"2026-07-14T23:39:42",11,"Иштар смотря на эту картину испытывал чувство дежавю\n\n— Я бы не советовал его есть. Порой ягнята оказываются друидами",34769,null],[115636,"2026-07-14T23:40:12",41,"— Вы что, хотите зарезать совсем маленького ягненка ? А если он нам поможет ?",34769,null],[115637,"2026-07-14T23:41:19",9,"Хардинт — Вот и не хочу. — *Тут одного взгляда на Соль хватило, аргументы даже были излишни.*",34769,null],[115638,"2026-07-14T23:42:58",11,"— У меня достаточно еды, не беспокойтесь.. нужно будет подсоблю если у меня брать не откажетесь",34769,null],[115639,"2026-07-14T23:44:07",41,"— У меня тоже есть, я могу поделиться",34769,null],[115643,"2026-07-14T23:47:03",17,"Фауст видя что все единогласно против пожал плечами. Достал венок который ему подарили и надел на голову ягненка",34769,null],[115644,"2026-07-14T23:47:09",9,"Хардинт — Ладно, большинство за то чтобы оставить. — *Посмотрел на Фауста и едва заметно улыбнулся его решениям.* — План Б — оставим на крайний случай.",34769,null],[115645,"2026-07-14T23:47:24",17,"А потом отвернулся и пошел высматривать следы",34769,null],[115647,"2026-07-14T23:48:29",11,"— Что-ж, вижу мои венки почти никому не пришлись по душе — слегка погрустнело сказал кентавр — продолжим путь?",34769,null],[115648,"2026-07-14T23:49:32",41,"— Спасибо, Фауст…\n\n\nТихо сказала эльфийка и с малышом пошла в след за остальными. Заодно, нарвав ему травинки на ужин",115643,null],[115649,"2026-07-14T23:50:01",9,"Хардинт — Хорошие венки, просто, о другом думаю. Разум всё время в мастерской. — *Поправил свой венок на голове.* — Спасибо Иштар.",115647,null],[115650,"2026-07-14T23:51:14",9,"Хардинт — Кстати, я не знаю как народ кентавров относиться к такому. У меня есть мысль, только боюст ты сочтёшь её слишком наглой, не знаю стот ли спрашивать.",115647,null],[115651,"2026-07-14T23:53:14",11,"— Спрашивай, я уже привык к отношению людей — он поднял на руки Серу — вряд ли ты меня удивишь",34769,null],[115652,"2026-07-14T23:56:44",9,"— Хотел попросить повезти леди Соль на себе. — *Хардинт не назвал причину, и лишь показал на свои глаза потом на неё, чтобы она не заметила этого. Намекнул о её зрении и что ей модет быть тяжеловато.* — Если жто слишком — забудь. Считай не спрашивал.",34769,null],[115653,"2026-07-14T23:57:31",41,"( Соль этого не слышала ?",34769,null],[115654,"2026-07-14T23:59:52",41,"Эладринка покраснела и начала разводить руками перед кентравром и сопровождающим\n\n— Что вы, я совсем не устала! Я очень благодарна за вашу заботу, но господин Иштар не обязан меня везти.",34769,null],[115655,"2026-07-15T00:00:13",9,"//Все что вслух — слышала)",34769,null],[115656,"2026-07-15T00:00:28",41,"( ок",34769,null],[115657,"2026-07-15T00:03:09",11,"— Если придётся я не откажу в помощи, но пока не думаю что это необходимо — Иштар наклоняется над Харди что бы прошептать ему на ухо — люди с особенностями учатся жить заново и обычно справляются с этим сами. Мы можем помогать им, но не стоит испытывать жалость только из-за этого, они тоже хотят быть равными нам",34769,null],[115658,"2026-07-15T00:04:53",9,"*Просто кивнул.*\n\nХардинт — Ладно, ладно, всё, виноват. — *Начал собирать рюкщак где его оставил и вещи.* — Тогда пошли потихоньку.",115657,null],[115659,"2026-07-15T00:05:44",11,"— Все в порядке, ты заботливый парень, нужно будет и тебя повезу — он одарил тебя улыбкой",34769,null],[115660,"2026-07-15T00:06:59",41,"— Я не могу придумать…\n\nЗадумчиво произнесла Соль",34769,null],[115661,"2026-07-15T00:07:22",9,"Хардинт — Я понял что это лишнее, не напоминай. — *Сам от точно слишком смущен ситуацией чтобы сейчас даже думать об этом.*",115659,null],[115662,"2026-07-15T00:09:03",11,"*Гладит Харди по голове*\n\n// Ну вы правда милые что я могу сделать с этим:D",34769,null],[115663,"2026-07-15T00:09:23",11,"— М? Ты что-то сказала?",115660,null],[115664,"2026-07-15T00:13:48",41,"— Я не могу придумать имя ягненку… Я думала назвать его «Хэ» - значит Солнце, или «Бом» - значит Весна, или «Хару» - День",115663,null],[115665,"2026-07-15T00:14:56",11,"— А что на счёт цветка? Ты ведь нашла его в цветочном поле — Смотря на ягненка и девушка произнес кентавр",34769,null],[115666,"2026-07-15T00:19:07",41,"— А какое название цветка могло бы подойти ?",115665,null],[115667,"2026-07-15T00:20:11",11,"// ну может на азиатскую манеру просто слово цветок или хм дай посмотрю",34769,null],[115668,"2026-07-15T00:20:39",9,"Хардинт — Простите, не знаю, с названиями плохо. Даже цветы которые мы искали подсмотрел у знакомого что делает зелья. — *Лишь развёл руками, что правда то правда.*",34769,null],[115669,"2026-07-15T00:20:58",41,"( Османтус очень популярный азиатский цветок, но это смешное имя",34769,null],[115670,"2026-07-15T00:21:40",41,"( цветок на корейском звучит не очень звучно",115667,null],[115671,"2026-07-15T00:21:51",11,"— Может хлопок? Он такой же пушистый — кентавр гладит ягненка в руках девушки",34769,null],[115672,"2026-07-15T00:22:01",11,"// на корейском хлопок мокхва вроде",34769,null],[115673,"2026-07-15T00:23:01",9,"//Я бы назвал его по упоротому, зверобой (тож жёлтый цветок), или Ванилином там Сахарком. Тоже мне все на японских зациклены, сами думайте)",115669,null],[115674,"2026-07-15T00:23:40",41,"— … а если назвать его Мокси? Это созвучно с названием маленького золотого цветка. Я видела тут похожие, и такие росли на моей родине",34769,null],[115675,"2026-07-15T00:24:14",41,"( Османтус оказывается переводится как Моксо",34769,null],[115676,"2026-07-15T00:26:01",17,"Подходит Фауст с блокнотом где написано\n\n\"Назови его Жаркое\"",115664,null],[115677,"2026-07-15T00:26:15",41,"( НУ ТЕБЯ",115676,null],[115678,"2026-07-15T00:26:40",41,"Соль не жалея сил сваливает Фауста в цветы",115676,null],[115679,"2026-07-15T00:26:46",11,"— Звучит очень мило, Мокси — он обратился к ягненку — а тебе нравится?",115674,null],[115680,"2026-07-15T00:27:25",17,"/r +6 Нет не сваливает",115678,null],[115682,"2026-07-15T00:27:36",41,"/r d20+2 Я не кентавр, я женщина с ребёнком!",34769,null],[115684,"2026-07-15T00:27:41",9,"Хардинт — Жаркое тоже неплохо звучит. — *Слегка толкнул кентавра в бок, скорее подшучивая. Вариант Фауста его позабавил.*",115679,null],[115685,"2026-07-15T00:28:10",17,"/ Чё оба упали в цветы?",34769,null],[115686,"2026-07-15T00:28:18",17,"/ Это просто шутка юмора",34769,null],[115687,"2026-07-15T00:28:22",17,"/ Сразу тумаки",34769,null],[115688,"2026-07-15T00:28:28",41,"( ну она бы и так его вместе с собой уронила",115685,null],[115689,"2026-07-15T00:28:51",41,"( ок лежим",34769,null],[115690,"2026-07-15T00:29:23",11,"— Ну решать все равно не нам",115684,null],[115691,"2026-07-15T00:29:46",41,"— Да ты! Да ты вредина! \n\nСказала Соль лежа поперек Фауста",34769,null],[115692,"2026-07-15T00:29:52",9,"Хардинт — Тоже верно. — *Согласился.*",115690,null],[115693,"2026-07-15T00:30:03",41,"( а кто барашка играет ?",34769,null],[115694,"2026-07-15T00:30:20",9,"//Твой барашек ты и играешь ^^",115693,null],[115695,"2026-07-15T00:31:08",11,"// как я трайчонка",34769,null],[115696,"2026-07-15T00:31:09",41,"Барашек смотря на то , что его новая мама уронила себя и какого-то хищника, просто тоненько бееекал и щипал травку",34769,null],[115699,"2026-07-15T00:41:13",17,"В этот момент под маской эладрин искренне улыбнулся и даже хрипло хихикнул\n\nНити тут же натянулись разрывая кожу\n\nВеселье сменилось болью. Как всегда. Одно и тоже. Кровоподтёки чуть запачкали маску изнутри.\n\nИ Фауст снова стал собой.\n\nОн строго встал. Отрехнулся и отвернулся от эладринки пошел в другую сторону.",115691,null],[115700,"2026-07-15T00:43:15",41,"Не мешая ему подниматься, Соль хотела извиниться, так как заметив напряжение эльфа первой её мыслью было, что она ему куда-то надавила. Но не успела и подумала, что принесет извинения в другой раз",34769,null],[115701,"2026-07-15T00:44:19",11,"— Ты в порядке? — Иштар обратился к Фаусту подавая девушке руку",34769,null],[115702,"2026-07-15T00:45:48",17,"Не оборачиваясь Фауст показывает большой палец и продолжает отходить",115701,null],[115703,"2026-07-15T00:48:03",11,"*вздох*",34769,null],[115704,"2026-07-15T00:48:18",11,"// чувствую себя третьим колесом х)",34769,null],[115705,"2026-07-15T00:48:57",9,"Хардинт — Кажется не время и не место. — *Он поправил рюкзак и собрался продолжить путь.* — Пошли, всё наладиться, нам лишь нужно время.",34769,null],[115706,"2026-07-15T00:49:57",9,"//Это должен был быть ваншот, но го продолдим завтра (тоесть уже сегодня). Чисто вторая часть. Я щас подщитаю вам награды за этот день, оке?",34769,null],[115707,"2026-07-15T00:53:29",9,"//Награды:\n\nВсем по 200 опыта за оттыгрыш и хардинту 20 как персу ведущего. Это фулл для этого места, завтра будет другое.\n\nСоль: Золотой ягнёнок если не пропадёт к конце квеста.\nИштар: травы на 4 золотых.\nГвиди: травы на 21 золотой.\nФауст: травы на 7 золотых.\nХардинт: травы на 23 золотых.\n\nМожете записать золото вместо трав чтобы не париться, сами смотрите.",34769,null],[115709,"2026-07-15T00:55:17",41,"— Спасибо…\n\nОна вздохнула, вновь прикрывая глаза и поманив малыша за собой пошла вперед.\n\nБарашек Мокси побежал за ней, блистая маленькой золотой жопкой",115701,null],[115710,"2026-07-15T00:59:15",17,"/ Нет, я со всеми хочу Рп просто перс такой. Сэд бой. Форевер элоне. Грустная предыстория. Много боли внутри и жажда мести. У вас чертверых более цветочный вайб вы мэтчитесь. Мне нужно больше времени в группе.",115704,null],[115711,"2026-07-15T01:00:22",11,"// да у вас все отлично с Элей, просто не понимаю как к вам вписаться",34769,null],[115712,"2026-07-15T01:01:04",17,"/ Ну можно толкнуть меня в цветы например ))",115711,null],[115713,"2026-07-15T01:01:16",17,"/ Нужен бой",34769,null],[115714,"2026-07-15T01:01:25",17,"/ В бою я раскроюсь",34769,null],[115715,"2026-07-15T01:01:57",17,"/ Не как дамагер, а как чел который пытается всех спасать",34769,null],[115716,"2026-07-15T01:03:18",11,"// ты это говоришь воину у которого атака с маневром :D",34769,null],[115737,"2026-07-15T08:12:02",9,"*За цветочными полями шли леса, густые непроглядные, цспокатвающий ритм природы, щебет птиц, всё кишало жизнью. Путь занял ещё пол дня по едва угадывающейся свежей тропе, натоптали её люди. Пара диких собак или волков прошмыгнула мимо, на толпу людей они не позарились, похоже был плохой опыт или испугались потому что не видели таких до этого, точно не скажешь.*\n\n*Была пора обедать, заморосил мелкий дождь, найдя место где тот не достанет Хардинт решил что пора разбить лагерь. Он готовил еду, не то чтобы слишком умело, но да.*\n\n*Золотой ягнёнок чувствует себя неуютно в этом месте, затих.*",34769,null],[115738,"2026-07-15T08:12:17",9,"Хардинт — По идее мы уже близко. Немного отдохнём и пойдём дальше. — *Он помешивал поварёшкой и пробовал пока готовил, привычка добавлять всё по вкусу, в этом случае хотя бы соль.*",34769,null],[115739,"2026-07-15T08:12:36",9,"//А дальше пойдём когда будут все",34769,null],[115745,"2026-07-15T08:36:53",9,"// музычка кстати",48827,null],[115785,"2026-07-15T13:19:19",17,"Фауст обосновался недалеко от Хардинга но ужин у него был другой. Он достал нож и куски вяленного мяса, на небольшой дощечке мелко мелко начал шинковать эти кусочки в мелкую стружку\n\nПотом вытер лезвие тканью, взял доску с мелко рубленым мясом и отойдя к дереву в сторону сел там в сухом месте.\n\n/Внимание СЛ14 Кто хочет подсмотреть\n\nФауст приспустил платок с лица, полоснул ножом по серебряным нитям плотно сшивающим рот и сразу сунул туда стружку мяса. Проклятые нити очень быстро восстановились, он делал так несколько раз, каждый раз мешая удовлетворение потребности в еде с болью.\n\n/ 1 урона запишу. -1 рацион",34769,null],[115786,"2026-07-15T13:21:35",5,"Гвиндшарх сел около костра и достал из рюкзака паёк. От него запахло грибами.\n\nТроглодит презрительно осмотрел место стоянки и отправился куда-то во тьму",34769,null],[115787,"2026-07-15T13:21:38",5,"/r +4",34769,null],[115789,"2026-07-15T13:22:09",5,"Дракон смотрел в сторону немого товарища, но не обнаружил ничего странного",34769,null],[115790,"2026-07-15T13:22:23",11,"// попытка не пытка:D",34769,null],[115792,"2026-07-15T13:23:48",41,"/r d20+4 она бы слышала очень странные звуки",34769,null],[115794,"2026-07-15T13:24:01",9,"*Хардинт был занят чтобы смотреть.*",34769,null],[115795,"2026-07-15T13:24:37",9,"//Вы слепы? Точно? Откуда криты на восприятие постоянные?)",115793,null],[115796,"2026-07-15T13:25:12",41,"( у меня обострились остальные чувства",115795,null],[115797,"2026-07-15T13:25:52",11,"— Харди, нужна помощь? — Иштар подошёл к парню смотря за тем чем он занят",34769,null],[115804,"2026-07-15T13:29:56",5,"Гвинди подошёл к котлу.\n\n— Можно я добавлю грибы в котёл? Обожаю еду с шампиньонами!",115738,null],[115809,"2026-07-15T13:35:03",9,"— Не против помощи, в целом моя готовка не лучшая. — *Готов уступить место повара без вопросов.*",115797,null],[115811,"2026-07-15T13:36:29",11,"// ну у нас тут каждый сам себя кормит я смотрю, но если ты не против нас покормить:3",34769,null],[115812,"2026-07-15T13:36:48",5,"// нарративно добавили пайку в один котёл",34769,null],[115813,"2026-07-15T13:36:54",9,"//Я обыгрываю просто, мезанически пох",115811,null],[115814,"2026-07-15T13:37:09",41,"Уходом Фауста первым поинтересовался золотой ягненок Мокси, по пути его маленькое тельце поймала Соль и собиралась уйти, однако её прервал звук скрежета кинжала по серебряным нитям. \n\nБыстрое поедание и проглатывание соленого мяса\n\nПосле загический треск того как эти нити снова сращиваются. Теперь стало понятно то, что она не видит. \n\nОна была далеко не глупой, и сразу провела цепочку действий того, как Фауст прорывает собственный рот просто чтоб поесть. Это было первым за долгое время, что действительно кольнуло её в сердце.\n\nОна хотела извиниться перед ним за ту небольшую оплошность с её стороны, но теперь любая компенсация казалась ей мелочью. Однако одна идея всё же пришла ей в голову: взяв из сумки свою флягу с водой, эльфийка открыла её и сунула в горлышко трубочку из тонкой ветви бамбука. \n\nПодождав немного времени перед тем, как эладрин вернется, она подойдет к нему и протянет свою флягу. \n\n— П-прости, что навязываюсь. Кажется вяленое мясо очень соленое, вот вода чтоб запить.",115785,null],[115815,"2026-07-15T13:38:29",5,"// напоминает мне [ВЫРЕЗАНО], там такие же персонажи, например [ВЫРЕЗАНО]",34769,null],[115816,"2026-07-15T13:39:00",41,"@dunchev ответ Фаусту",115814,null],[115817,"2026-07-15T13:39:11",11,"— Не стоит принижать свои способности, но помощь никогда не помешает — Иштар взял у Гвинди сушеные шампиньоны останавливая того от вреда их общей еде* методом забрасывания всего пайка в котел — Да.. мне стоило взять специй \n\nПроизнеся это Иштар вспомнил про цветы что вы собирали днём и добавил один знакомый в котелок с умным видом, а затем проверил на соль и показал довольно палец вверх",34769,null],[115818,"2026-07-15T13:39:55",41,"( аааа кушац",34769,null],[115819,"2026-07-15T13:40:17",5,"— Уже готово? У меня слюнки текут",115817,null],[115820,"2026-07-15T13:41:39",11,"— Ещё пару минут.. твоим грибам и цветам нужно время — он посматривал в котёл ещё пару минут прежде чем дать попросить у вас ваши тарелки",34769,null],[115823,"2026-07-15T13:43:25",41,"( я аж сама проголодалась",34769,null],[115824,"2026-07-15T13:43:41",9,"Хардинт — Как вы стали приключенцами. —*Спросил парень Иштарана и Гриди что были рядом пока они готовили.* — Я помню чинил вещи и разные приспособления для наёмников, а потом коснулся кристалла который перенёс меня в леса, первый раз видел леса, то был какой-то артефакт или устройство что принесли моему учителя. Я в пустыне видел лишь редкие финиковые пальмы.\n\n*Поднимает взгляд на кроны деревьев и смотрит на них, протягивает руку и сжимает в пустоте.*\n\nХардинт — Словно сказка, я был ошеломлён когда увидел столько зелени. Когда солнце не жжёт так сильно что прячешься в подвалах мастерской чтобы оно не достало. Так легко дышать без раскаленной пыли.",34769,null],[115825,"2026-07-15T13:43:45",11,"// я ирл омлет с сыром на завтрак делаю:D",34769,null],[115826,"2026-07-15T13:44:04",41,"( Приятного аппетита!!!",115825,null],[115827,"2026-07-15T13:44:04",9,"*Кажется парень словил нотку меланхолии.*",115824,null],[115828,"2026-07-15T13:44:36",17,"Фауст поворачивается на голос девушки. Особо не пряча свои шрамы и нити и ожоги.\n\nВ глазах холодное спокойствие.\n\nОн берёт воду с трубочкой и приложив руку к груди делает ей поклон сидя.",115814,null],[115831,"2026-07-15T13:46:21",11,"— О, ты тоже был в пустынях? — кентавр протянул первую тарелку Гвиндшарху, а затем подошёл к Харди с его порцией — Путешествовать - судьба каждого кентавра. Ещё с моим племенем я обошёл все степи и пустыни, а затем наконец двинулся в личное путешествие.. такова традиция моего народа. Мы путешествуем по разным странам, знакомимся с культурами других и в итоге приносим это домой\n\nИштар оглянулся на эльфов \n\n— Присоединяйтесь к ужину",115824,null],[115832,"2026-07-15T13:46:29",5,"— Значит, некий артефакт выбросил тебя из дома, а ты теперь не хочешь возвращаться?",115824,null],[115834,"2026-07-15T13:48:23",41,"В вечерней темноте её глаза уже не были постоянно закрыты, как при дневном свете. Теперь Фауст тоже мог увидеть как белые ресницы, похожие на иней переливаются с глубоким ледником темно-голубых глаз, в центре которых были маленькие звезды. \n\nВ знак уважения, Соль поклонилась в ответ\n\nУслышав оклик Иштара она вновь прищурилась, смотря на костер. \n\n— О, конечно! Пахнет очень вкусно! \n\nДевушка побежала к ним",115828,null],[115835,"2026-07-15T13:49:23",11,"— Рагу с грибами и \"специями\", леди Соль — он протянул ей тарелку — а что на счёт вас, господин Фауст?",34769,null],[115837,"2026-07-15T13:50:30",5,"Дракон взял тарелку и поблагодарил.\n\n— Мой отец брал меня в приключения ещё когда я был подростком. Много лет я сопровождал отца и его друзей в странствиях. Но несколько месяцев назад я решил пойти своей дорогой. Научиться самостоятельно выживать и совершать славные дела.",115831,null],[115838,"2026-07-15T13:51:04",9,"Хардинт — Зачем? Я остался жив до сих пор потому что работал на артефактора. — *Усмехнулся.* — никогда не вернусь в (имя не указано), даже если предоставится такой шанс. Там любого \"слабого\" или \"бесполезного\" ждёт смерть, не важно сколько тебе лет, юноша, старик или совсем ребёнок.",115832,null],[115839,"2026-07-15T13:52:03",41,"Слегка подпрыгивая с ноги на ногу, эладринка восхищалась тем как поблескивает вкусное варево с грибами. \n\n— Какая вкуснятина! Оно уже совсем готово???",115835,null],[115840,"2026-07-15T13:53:19",5,"— Суровое место. Никогда не было мыслей вернуться и изменить его? У тебя не осталось близких там?",115838,null],[115841,"2026-07-15T13:53:47",17,"Ну, а мрачный свидетель судеб резанул пару нитей и сунул трубочку в рот чтоб попить. \n\nУ него в рюкзаке было еще двенадцать таких бамбуковых трубочек. \n\nЗадумавшись о заботе, которую безвозмездно к нему проявляют. И соль, И остальные. Венок, серьга. Он погрузился в мысли. Но воспоминание выбило его на поверхность вновь.\n\n\"Приятно иметь поддержку, но полагаться на других нельзя. Ради исполнения своей заветной мести.\"",34769,null],[115846,"2026-07-15T13:55:25",11,"— Пустыни суровые места, но в них есть и своя прелесть, Господин Хардинит. Для меня пустыня - дом. Если мне представиться возможность показать вам ее с другой стороны я бы ею воспользовался \n\nИштар с грустью взглянул на Харди, а затем на Фауста. \"У каждого свои причины полагаю\" — подумал он и принялся за трапезу",115838,null],[115848,"2026-07-15T13:55:48",41,"Я искала нужную гифку с Маомао, нашла только эту",34769,null],[115849,"2026-07-15T13:56:05",11,"// я хотела взять преду бедуин даже, но у нас ее вроде нет\n\nКстати, Эля, у Гвинди недавно совсем глаз выкололи и лечили если он в курсе твоих проблем может будет темой для разговора, чисто предлагаю",34769,null],[115851,"2026-07-15T13:57:43",41,"( может быть, но Соль не страдает",115849,null],[115852,"2026-07-15T13:57:53",17,"Видя как остальные радуются грибному рагу Фауст решил попробовать как то отплатить группе. Он пошел искать грибы, чтобы Хардинг порадовал остальных снова на следующем привале",34769,null],[115853,"2026-07-15T13:58:00",9,"Хардинт — Из тех пустынь в которые вы никогда не попадёте скорей всего. Мне доводилось видеть карты, пока не видел ни одного знакомого континента или названия. Поэтому буду рад посмотреть ваш дом.",115846,null],[115854,"2026-07-15T13:58:01",17,"/r +4 Выживание ищем грибы",34769,null],[115857,"2026-07-15T13:58:54",9,"*Пень с вешанками обнаружен, пол ведра самых мясистых грибов на нём.*",115855,null],[115858,"2026-07-15T13:59:18",41,"Соль с интересом слушала рассказы проводника о далёких пустынях, уплетая мясное рагу, пока Мокси травку щипал.",34769,null],[115859,"2026-07-15T13:59:40",11,"— Мое предложение все ещё в силе, но теперь мне интересно о каких местах вы говорите..",115853,null],[115860,"2026-07-15T13:59:47",17,"Набрав грибов вешенок в сумку Фауст вернулся назад к костру и высыпал их рядом с пеньком где сидел Хардинг\n\nКоротко кивнул ему",34769,null],[115861,"2026-07-15T14:00:13",41,"( блииин кушац хочу. Всё , буду отходить немного. Не теряйте",34769,null],[115862,"2026-07-15T14:00:26",41,"( тут у них рагу, грибы мясистые ааааа",34769,null],[115863,"2026-07-15T14:01:20",11,"// могла бы предложила со мной позавтракать, приятного тебе заранее",34769,null],[115865,"2026-07-15T14:02:51",41,"( Спасибо, очень уютно звучит :3 Я бы тебя чаями своими вкусными угостила. Или кофе карамельным",115863,null],[115866,"2026-07-15T14:03:30",9,"*Хреначим значит жареных в масле грибов.*",34769,null],[115868,"2026-07-15T14:05:13",11,"// ооо оба варианта имба",115865,null],[115869,"2026-07-15T14:05:30",11,"// рагу вообще-то! С цветочками в качестве специй",115866,null],[115870,"2026-07-15T14:06:16",41,"( у меня есть смешной чай, называется срібний равлик - серебряная улитка. Это белый чай в форме маленьких панцирей улиток",115868,null],[115871,"2026-07-15T14:06:55",9,"//Ну, сами)",115869,null],[115872,"2026-07-15T14:08:07",9,"Хардинт — Кажется обедать мы будем грибами.",115860,null],[115873,"2026-07-15T14:08:50",11,"— Можно добавить ещё мяса и овощей с пайков! — Иштар осмотрел добычу Фауста — Отличный улов, приятель!",34769,null],[115874,"2026-07-15T14:11:38",41,"Достав немного овощей из своих пайков, Соль начала нанизывать их на шашлычки\n\n— это хватит и на завтра точно! Спасибо за грибы, Фауст!",34769,null],[115879,"2026-07-15T14:16:26",9,"//Что за подземелье вкусностей началось 😂👌(мне нарится)",34769,null],[115880,"2026-07-15T14:16:28",11,"Иштар поставил на котел казанок с чистой водой, дожидаясь пока та закипит ощипал некоторые цветы со своего венка и кинул их в воду\n\n— Вы же не думали что у них нету практического применения? Горные цветы отлично подходят для чая, будете?",34769,null],[115884,"2026-07-15T14:20:49",17,"Фауст тоже взял прутик и решил со всеми пожарить грибочки, есть он их не хотел. Но сам процесс поддержать захотелось.",115874,null],[115889,"2026-07-15T14:24:22",11,"// очень сытный ужин 😁",34769,null],[115895,"2026-07-15T14:27:10",5,"Гвинди понюхал котелок чая.\n\n— Ты уверен, что положил те травы?",115880,null],[115896,"2026-07-15T14:28:02",41,"— Чай??? Ох, точно. Мой давно кончился, а я так хочу показать фокусы.",115880,null],[115898,"2026-07-15T14:28:34",11,"Наевшись досыта кентавра потянуло в сон. Он расстелил покрывало с подушками для своего конского крупа и укрылся одеялом посматривая в небо. Звёзды на природе всегда были завораживающими, он повторил жест Харди протягивая к ним руку, но слова драконорожденного вернули его в реальность \n\n— Не хочешь не пей — обиженно ответил кентавр и повернулся к нему спиной — да, ваши венки - это цветы для чая",34769,null],[115903,"2026-07-15T14:33:21",5,"— Всё же попробую\n\nДракон осторожно отпил чая из кружки.\n\n— Неплохо!",34769,null],[115911,"2026-07-15T14:34:42",9,"Хардинт — Синий, Красный, Зеленый — патрулируйте. Если обнаружите угрозу — разбудите. — *Отдав указания, крошечные консрукты разлетелись и заняли место на указанных точках. Налил себе травяного чая перед сном.* — Скорей всего завтра мы будем на месте, надеюсь ещё до обеда.",34769,null],[115914,"2026-07-15T14:37:05",17,"Дожарив шашлычок из вешенок Фауст протянул шпажку Иштару\n\nСам он есть уже не хотел. \n\nСкоро его ждала очередная медитация и образы прошлого, что не дадут забыть ту боль.",34769,null],[115916,"2026-07-15T14:38:40",11,"— Благодарю, но тебе тоже стоит попробовать",34769,null],[115918,"2026-07-15T14:38:43",41,"— Фауст…\n\nПрервала его размышления эладринка\n\n— А ты когда-нибудь пробовал делать так ? \n\nПоказывая на кружке чая, она начала морозно рисовать маленькую бабочку, после выловила её из воды и показала",34769,null],[115923,"2026-07-15T14:40:59",17,"Он в ответ создал в ладони тонкую острую сосульку \n\nВзял ее и приставил к горлу Соли делая вид что бьёт, но медленно как бы объясняя зачем он использовал фейский дар ледяных эладринов раньше",115918,null],[115926,"2026-07-15T14:42:15",41,"/r d20+2 А она поймёт ?",34769,null],[115928,"2026-07-15T14:43:02",17,"/r -1 Убеждение что это не атака",34769,null],[115930,"2026-07-15T14:44:18",9,"Хардинт — Воу, воу. Опасные сосульки. — *На мгновение испугался, но понял что ничего плозого не происходит, подумал немного.* — Думаю такой дар везде может пригодится, охлаждать напитки, хранить пищу.",34769,null],[115931,"2026-07-15T14:44:56",11,"* Иштар съел предложенные Фаустом грибочки и уснул в обнимку с трайчонком *",34769,null],[115932,"2026-07-15T14:44:59",41,"— Оу… вижу ты много тренировался. \n\nСлегка наклонив голову ответила она\n\n— В детстве мы с братом часто дрались с помощью снега, нам не было равных в этой игре. Хехех… Но так же мы были самыми младшими, может взрослые просто поддавались",34769,null],[115934,"2026-07-15T14:46:13",41,"— Но в создании красивых снежинок нам никто не мог поддаваться. Хотите ещё сделаю ? \n\nОна вновь закрутила тонкими пальчиками над поверхностью воды",34769,null],[115944,"2026-07-15T14:48:47",17,"Фауст тоже сделал снежинку, но получился острый сюрикен",34769,null],[115949,"2026-07-15T14:50:05",9,"//Это типа как увеличенноя большая снежинка?",115934,null],[115950,"2026-07-15T14:50:35",41,"( да",34769,null],[115951,"2026-07-15T14:51:36",5,"Гвинди заснул в спальнике около костра.\n\nЕго лупоглазого друга нигде не видно.",34769,null],[115952,"2026-07-15T14:51:51",41,"Сейчас она сделала стандартную снежинку",34769,null],[115953,"2026-07-15T14:52:18",9,"Хардинт — Красиво. У меня есть идея, поможешь? — *Он достал чернила и листок бумаги и мыла.* — Заморозь чернила в форме небольшой снежинки, остальное я сделаю сам.",34769,null],[115959,"2026-07-15T14:57:26",41,"Увидев снежинку Фауста, она улыбнулась, но решила дать подсказку. Тут как раз Хардинт предложил свой вариант. \n\n— это будет сложнее, но я попробую. Смотри, Фауст: У снежинок всегда шесть симметричных сторон. Они могут быть мягкими, а могут быть изящными. Мне всегда говорили, что снежинки похожи на звезды, наверное это правда… попробуй сделать звездочку…\n\n\nОна начала проводить пальцами аккуратные линии со своей половины, остальную предоставила эладрину",34769,null],[115961,"2026-07-15T14:58:31",17,"Фауст метнул свою снежинку в ствол дерева и она вонзилась в него до половины\n\nМахнув рукой он полез на дерево, чтобы там помедитировать",115959,null],[115972,"2026-07-15T15:02:31",41,"В итоге Соль сама закончила снежинку, тихо и без явного недовольства.",34769,null],[115973,"2026-07-15T15:02:43",9,"//Из чернил?",34769,null],[115980,"2026-07-15T15:05:33",41,"( да",34769,null],[115983,"2026-07-15T15:08:46",9,"*Хардинт достает лист бумаги и из мыла как из пластелина вылепил печать на которую поместил снежинку и в итоге успел поставить несколько чернильныз снежинок прежде чем та растеклась.*\n\nХардинт — Ох. Успел. Теперь снежинка запечатлина на листе. — *Он обратился к Соль.* — Так можно делать печати или уникальные узоры на тексте, может пригодится.\n\n*Протянул листок ей.*",34769,null],[115984,"2026-07-15T15:10:05",9,"//Мыло имба предмет, отвечаю. Я ещё наварю как руки к набору алхимика дойдут. Всего то 2 медяка за имбовую штуку. Копировать ключи, да что угодно!)))",34769,null],[115985,"2026-07-15T15:14:45",41,"— Какая прелесть! \n\nНом ном ном\n\nДевушка присела ставить печати, другой рукой поедая шашлычок",34769,null],[115987,"2026-07-15T15:19:36",9,"*Просто улыбается наблюдая как приглянулась его идея.*",34769,null],[115988,"2026-07-15T15:20:07",9,"//Если все заявки, перейдем к основному действу?",34769,null],[115989,"2026-07-15T15:20:51",41,"( я пока уборкой занята . По сути мои заявки всё",34769,null],[116000,"2026-07-15T15:44:46",9,"*Леса, окончились небольшой долиной. Руины какого-то города чьё название кануло в лету. Мхи, деревья и природа словно хотели скрыть что здесь была цивилизация. Ваш проводник потрогал ногой кладку края стены, убежившись что та не обвалится просто сел там.*\n\nХардинт — Кажется это наше место. Вот, вот, вот тут, если не путаю и мне дали достоверное описание. — *Указал он на обвалившейся здание среди других.* — Та самая стена должна быть там.",34769,null],[116002,"2026-07-15T15:52:01",9,"//Сорян, я не мастер генеров. Одного персонажа на картинку вместить уже проблемой бывает)",34769,null],[116005,"2026-07-15T16:02:21",11,"Иштар старается держаться подальше от края понимая что там где руины выдерживают вес человека его вес может стать фатальным \n\n— И какая же цель у нашей экспедиции, господин Хардинит?",34769,null],[116006,"2026-07-15T16:02:34",5,"// описания важнее",116002,null],[116007,"2026-07-15T16:04:06",9,"Хардинт — А, простите. Мы же шли смотреть нерушимую стену, и возможно то что за ней.",116005,null],[116008,"2026-07-15T16:05:23",9,"*Думает что вы забыли. Встаёт и отряхивается. Кое что замечает.*\n\nХардинт — Там уже кто-то есть. — *Укзывает почти на то же место где примерно стена.* — Огонь.",34769,null],[116010,"2026-07-15T16:06:00",9,"*Похоже посреди руин кто-то разбил лагерь, видна струйка дыма из-за здания.*",34769,null],[116012,"2026-07-15T16:06:39",11,"Кентавр посмотрел куда указывает проводник\n\n— Кто-то добрался суда раньше нас, хм? Какой план?",34769,null],[116014,"2026-07-15T16:07:38",9,"Хардинт — Конечно добрались. Я сам услышал о стене от приключенцев в таверне. А что делать? Не знаю, это зависит от того кто там.",34769,null],[116016,"2026-07-15T16:08:51",5,"Гвинди поглядел на указанное здание.\n\n— Ты имеешь в виду, что нерушимая стена — это стена одного дома!? Я ожидал большего!",116000,null],[116018,"2026-07-15T16:10:08",11,"— Тогда спустимся вниз и осмотримся?",116014,null],[116020,"2026-07-15T16:10:58",9,"*Покачал головой.*\n\nХардинт — Не не не, она преграждает путь в проход под землю. — *Немного смутился.* — Так слышал, и вам говорил.\n\n*Думает что вы пьяные тогда всё забыли.*",116016,null],[116022,"2026-07-15T16:12:08",9,"Хардинт — Хотя слухам верить себе дороже. О ней упоминали несколько ращ и совсем разные люди. Говорили об одном и том же месте.",34769,null],[116023,"2026-07-15T16:12:27",5,"— Да. Сначала узнаем кто это. Но не доставайте оружия слишком рано, попробуем договориться",116018,null],[116024,"2026-07-15T16:12:56",5,"// надеюсь там не гоблины, бестиарий большой всё-таки",34769,null],[116025,"2026-07-15T16:14:02",17,"Фауст на блокноте начиркал\n\n\"Я сзади постою, чтоб не напрягать тех ребят\"",34769,null],[116026,"2026-07-15T16:16:09",41,"— Я тоже постою сзади … я слишком слабая чтоб они не захотели попытаться взять меня в качестве заложника",34769,null],[116027,"2026-07-15T16:16:31",11,"*кентавр пожимает плечами* \n\n— Я пойду вперёд",34769,null],[116030,"2026-07-15T16:17:23",41,"Тем временем , слегка приоткрыв глаза, Соль будет искать любые намеки на сокровищницу. Может стена имеется ввиду у храма или дворца?",34769,null],[116031,"2026-07-15T16:17:33",41,"( могу кинуть внимательность ?",34769,null],[116032,"2026-07-15T16:17:47",41,"/r d20+4",34769,null],[116035,"2026-07-15T16:17:58",41,"( нииичо не вижу",34769,null],[116040,"2026-07-15T16:18:48",9,"*Герои решили посмотреть кто разводит костёр. Руины выглядели давно разграбленными, где-то копались, где-то рылись.*",34769,null],[116041,"2026-07-15T16:20:15",9,"*Ты находишь каменную фигурку грифона с обломанными крыльями на обочине, похоже кто-то из искстелей сокровищ не счел её ценной и выбросил.*",116033,null],[116043,"2026-07-15T16:21:27",5,"Гвинди прячется среди руин и незаметно подбирается ближе к костру",34769,null],[116047,"2026-07-15T16:23:00",17,"Фауст Решил скрыться из виду в руинах и наблюдать из теней со стороны, он знал, что в случае нужны быстро придёт на помощь фейским шагом",34769,null],[116048,"2026-07-15T16:23:06",17,"/r +6 Скрытность",34769,null],[116050,"2026-07-15T16:23:11",17,"/Ого",34769,null],[116053,"2026-07-15T16:24:22",11,"*Иштар все ещё спокойно идёт вперёд держа щит в руке и готовый выхватить оружие в любой момент*",34769,null],[116063,"2026-07-15T16:30:20",9,"*Вас встречал лагерь приклбченцев, дюжина человек, слегка бандитской наружности. Они перебирали находки, лопаты в свежей земле, уставшие и... вооружённые.*\n\nЧасовой — Жанна, к нам гости! — *Кое кто заметил процессию и люди тут же повставали готовые реагироыать на угрозу.*",34769,null],[116065,"2026-07-15T16:33:31",11,"— Здравствуйте! — Иштар поднял руку в приветствии все ещё не доставая оружия пока его спутники ныкались по углам успешно или не очень",34769,null],[116070,"2026-07-15T16:36:33",9,"*Перед вами выходит женщина с повязкой на глазу, поднакаченная фигура.*\n\nЖанка — Чегойсь забыли тут? Если копаться — копайтесь, только в другом месте, город большой.",34769,null],[116071,"2026-07-15T16:37:22",11,"// а они прямо перед стеной?",34769,null],[116072,"2026-07-15T16:37:30",5,"— А, это люди! — сказал Гвинди и покинул укрытие.\n\nОн подошёл к кентавру и представился.\n\n— Нориксиус Гвиндшарх! Что тут поделываете?",34769,null],[116074,"2026-07-15T16:39:40",17,"Пока Фауст искал место чтоб скрыться с глаз угодил в выкопанную яму, глубокая, самому не выбраться, а силы тратить глупо\n\nСделал пару снежинок и кидает их воздух, авось кто заметит из своих",34769,null],[116075,"2026-07-15T16:39:49",9,"Жанка — Ищем сокровища, кому просто богатства, кто-то археолог.",34769,null],[116081,"2026-07-15T16:41:10",11,"Пока Гвинди говорит Иштар решил помочь не особо скрытному Фаусту протягивая руку\n\n— Цел?",116074,null],[116084,"2026-07-15T16:42:07",5,"— Мы тоже. Услышали про какую-то стену, что никто сломать не может. Вот и собрались посмотреть. Видели такую?",116075,null],[116085,"2026-07-15T16:43:05",17,"Кивает и хватается за руку и подтягивается на ней выбирается.\n\nпоклоном благодарит за помощь и уже идёт с Иштаром открыто",116081,null],[116086,"2026-07-15T16:43:56",9,"Жанка — Ахаха. Да, вилели, половину инструментрв сломали. — *Похоже её позабавило это дело.* — Ну, если вы прямо к стене, то идите, она в той часовне.\n\n*Указывает на часовенку полуобрушенную.*",34769,null],[116087,"2026-07-15T16:44:52",5,"// проницательность?",116086,null],[116088,"2026-07-15T16:44:54",11,"— Пойдём? — воин обращается к проводнику",34769,null],[116090,"2026-07-15T16:45:16",41,"Соль слишком засмотрелась на грифона и не заметила, куда пропал Фауст",116041,null],[116095,"2026-07-15T16:45:55",9,"//Если хочешь",116087,null],[116096,"2026-07-15T16:46:22",5,"Телепатически остальным:\n\"Хардинт сказал, что стена прямо тут. Куда это они нас отправить хотят?\"",34769,null],[116097,"2026-07-15T16:46:37",5,"/r +4",116095,null],[116100,"2026-07-15T16:47:37",5,"// все же телепатия двусторонняя?",34769,null],[116101,"2026-07-15T16:48:03",9,"//Хз, Арминар пользовал как двустороннюю. Дайте описание",34769,null],[116102,"2026-07-15T16:48:45",5,"Псионический разум. Вы можете посылать телепатические сообщения любому существу, которое можете видеть в пределах 30 футов. Вам не надо знать язык существа, чтобы оно понимало ваши телепатические сообщения, но существо должно быть в состоянии понимать по крайней мере один язык.",34769,null],[116103,"2026-07-15T16:49:04",9,"//Это всё?",116102,null],[116104,"2026-07-15T16:49:31",11,"// там вроде есть двусторонняя, но явно не на первых уровнях",34769,null],[116105,"2026-07-15T16:50:43",9,"Хардинт — Я сам только по слухам знаю где стена. Спасибо за наводку. Мы проверим.\n\nЖанка — Давай, идите идите. Не мешайтесь.",34769,null],[116106,"2026-07-15T16:51:00",5,"// а проницательность?",116098,null],[116107,"2026-07-15T16:52:01",9,"*Вроде не врет, но вы ей точно не нравитесь, остальным людям тоже. Ощущение что после любого агрессивного действия начнётся сражение.*",116106,null],[116108,"2026-07-15T16:52:33",5,"Телепатически:\n\"Я ей верю. Но будьте начеку\"",34769,null],[116109,"2026-07-15T16:52:46",5,"Гвинди кивнул.\n\n— Тогда пошли",116105,null],[116110,"2026-07-15T16:54:53",9,"*Двинув почти на другую сторону, в полуазрушенную часовенку герои обнаружили в её стенах статую прекрасной женщины, ангела с обломанным крылом и руками, она была отодвинута и открыта давно, открывался за ней тайный проход вниз, в подземелье.*",34769,null],[116114,"2026-07-15T16:57:19",17,"Фауст сразу достал масленый фонарь и зажег его, чиркнув кресалом.",34769,null],[116117,"2026-07-15T16:58:08",17,"Он пошел вперёди остальных медленно ступая с носка ан пятку и на всякий случай осматривал пол и стенки на предмет старых хитрых ловушек.",34769,null],[116118,"2026-07-15T16:58:16",17,"/r +4 Внимание",34769,null],[116120,"2026-07-15T16:58:42",5,"Дракон осмотрел статую.\n\n— Хм, может, религиозный символ?\n\nГвинди вспоминает известные ему символы",116110,null],[116129,"2026-07-15T17:00:43",9,"*Несколько ловушек со стрелами и нажимными плитами, но они давно сработали. Приключенцы до героев осследовали широкий болишой копидор и он окончился стеной. Та глухая и как будто состоит из другого материала чем стены, кадется не тронутой временем.*\n\nХардинт — Кажется это она.",116117,null],[116131,"2026-07-15T17:01:45",9,"*Аасимар или небожитель, часто такие статуи ставят в храмах, просто как символ существ смотрящих сверху, совершеннеее и правильнее обычного человека.*",116120,null],[116134,"2026-07-15T17:02:51",17,"Слыша о том, что ее не удалось проломить и разрушить, Фауст решил притронуться сперва робко\n\nПальцы касаются стены\n\n/есть реакт стены?",116129,null],[116135,"2026-07-15T17:02:55",5,"Гвинди последовал за остальным к стене",34769,null],[116146,"2026-07-15T17:10:49",9,"*Прохладная, слегка влажная, слегка шершавая текстура на кончиках пальцев. Приятная, хочется придаться к ней и просто отдохнуть после пути, под прохладный напиток. Идеальная кладка без зазоров, словно положенна вчера, оставляет лучшее впечатление, её ложил мастер своего дела ровные линии. Очень кайфовая и ровная стена которых нет даже во дворцах, прелесть. Каждый кирпич со своей неповторяющейся но простой текстурой, по фэнцую, без единого изьяна.*",116134,null],[116150,"2026-07-15T17:15:50",17,"Для контрабандиста любая стена может быть с секретом. Часто на сопровождении груза перевозчики контрабанды или даже целые повозки исчезали с пути через стены, прямо перед шмоном стражников на заставах. Главное знать куда надавить. \n\nФауст кладет на землю фонарь и обеими руками начинает скользить по стене сверху вниз слева направо он надавливает чтобы попытаться нащупать какой нибудь механизм, нажимной кирпич или что то подобное.\n\nОн так же повернулся ко всем и кивает на стену, чтобы помогли искать.",34769,null],[116151,"2026-07-15T17:16:03",5,"Гвиндшарх потер стену рукой.\n\n— Нерушимая, да ещё и архитектурный шедевр. Такую и ломать не хочется!\n\nДракон сел на пол и прислонился спиной к стене. Оглядывается, смотрит, что ещё есть в комнате",34769,null],[116152,"2026-07-15T17:16:04",17,"/r +4 Ищем скрытый проход выживанием и знаниями контрабандиста",34769,null],[116155,"2026-07-15T17:18:08",9,"*Скрытого прохода нет кажется. Слишком всё хорошо, ещё от стены исходит лёгкое покалывающее ощущение в неготорых местах... магия.*",116153,null],[116159,"2026-07-15T17:18:53",9,"Хардинт — Да, кадется это то что мы искали. — *Достаёт инструменты и пытается что-то сделать или сбить кусочек, ничего ее выходит.*",34769,null],[116161,"2026-07-15T17:19:59",17,"Фауст достает блокнот и пишет \"Тут магия\" на листочках потом эти листочки прикладывает к стене в местах где покалывало и примораживает небольшим фокусом эладринов зимы",34769,null],[116162,"2026-07-15T17:20:05",9,"*Достаточно просторная комната, у стены напротив ловушки со стрелами куча сломанных стрел. Походе приключенцы активировали нажимную плиту пока в ловушке не кончились стрелы.*",116151,null],[116163,"2026-07-15T17:20:29",5,"Дракон повернул голову и лениво наблюдает за действиями эладрина.\n\n— Фауст, думаешь никто из авантюристов не пытался ощупать стену? Все не может быть так просто",116152,null],[116164,"2026-07-15T17:21:01",11,"— а что предлагаешь ты?",34769,null],[116165,"2026-07-15T17:21:39",9,"*Небольшой разряд электричества сверкнул обжигая руку в ответ на раздражитель.*\n\n//1 урона электричеством Фаусту",116161,null],[116166,"2026-07-15T17:22:48",17,"Он повернулся указал на листочки \"Тут магия\" и пожал плечами",116163,null],[116168,"2026-07-15T17:23:41",5,"Дракон только покачал головой. А потом прижался ухом к стене. И прислушался.",116164,null],[116169,"2026-07-15T17:24:08",9,"*Изнутри лишь какое-то едва слышное гудение.*",116168,null],[116170,"2026-07-15T17:24:48",5,"*сравниваю звук с известными механизмами*",116169,null],[116175,"2026-07-15T17:28:17",9,"*Звук трансформаторной будки.*\n\n//Сам реши знает ли перс чет подобное, но более магического происхождение конечно",116170,null],[116177,"2026-07-15T17:29:29",5,"/r +2 магия",34769,null],[116179,"2026-07-15T17:29:35",5,"// знает",34769,null],[116181,"2026-07-15T17:31:12",5,"— Слышу магическое устройство за стеной. Думаю, оно и держит постоянный барьер. Всё-таки эта стена — не творение великого архитектора, а лишь магия",34769,null],[116183,"2026-07-15T17:32:28",11,"Трайчонок из рук кентавра выскочил на землю и стал обнюхивать стену",34769,null],[116200,"2026-07-15T17:43:10",9,"*Сплошная, скорей всего и в стороны уходит.*",116183,null],[116203,"2026-07-15T17:43:52",17,"Фауст написал на листе \"Лопата есть? Подкоп?\"",34769,null],[116204,"2026-07-15T17:44:07",9,"Хардинт — А почему сверкнуло электричеством? На мои инструменты не среагировала.",34769,null],[116207,"2026-07-15T17:44:51",9,"Хардинт — Скорее кирки нужны. — *Смотрит на каменный пол и стены.*",34769,null],[116210,"2026-07-15T17:49:33",5,"— Лопаты нет, извини",116203,null],[116211,"2026-07-15T17:49:46",11,"— Таким не владеем — ответил Иштар — есть какие-то другие идеи?",34769,null],[116213,"2026-07-15T17:49:59",11,"// а за ней что? Или стена 30 ф толщиной?",116200,null],[116214,"2026-07-15T17:50:27",5,"— Действительно... Попробую повторить \n\nДракон достал бурдюк и вылил немного воды на стену",116204,null],[116216,"2026-07-15T17:52:06",9,"*Дальше проход той же ширины, толщиной кладка в 1 кирпич.*",116213,null],[116218,"2026-07-15T17:52:44",9,"*Никакой реакции на воду, похоже оно сработало на другой раздражитель.*",116214,null],[116219,"2026-07-15T17:56:47",5,"— Фауст положил листочки, а потом приморозил. Значит, стена среагировала на бумаги или... На температуру!",116161,null],[116220,"2026-07-15T17:57:07",11,"— А может на магию?",34769,null],[116221,"2026-07-15T17:57:25",11,"— Отторжение чуждой магии?",34769,null],[116223,"2026-07-15T17:59:15",5,"— Может и на магию. Надо проверить.\n\nДракон достал волшебную палочку и коснулся стены",116220,null],[116225,"2026-07-15T18:00:19",5,"Затем активировал связанное с ней заклинание против себя",34769,null],[116226,"2026-07-15T18:01:00",11,"Иштар снова взял Серу в руки опасаясь что стена может навредить малютке",34769,null],[116227,"2026-07-15T18:01:19",5,"/r +0 спас харизмы",116225,null],[116229,"2026-07-15T18:01:24",5,"// прошёл",34769,null],[116233,"2026-07-15T18:05:07",9,"*В палочку ударил небольшой разряд.*",34769,null],[116234,"2026-07-15T18:05:21",9,"//Что за палочка, ты волшебник?",34769,null],[116235,"2026-07-15T18:05:36",5,"// самая сильная вещь в днд",116234,null],[116241,"2026-07-15T18:08:28",11,"— Похоже оно и правда реагирует на магию — кентавр наблюдал за действиями драконорожденного",116233,null],[116248,"2026-07-15T18:10:28",17,"Фауст подошел вплотную и на сантиметр влево совершил фейский шаг, чтобы проверить как стена может отреагировать на фейскую магию крови",34769,null],[116250,"2026-07-15T18:10:39",17,"/Помоему там не надо видить точку телепортации",34769,null],[116253,"2026-07-15T18:11:40",5,"// хз",34769,null],[116254,"2026-07-15T18:12:01",17,"/ Это не тот",34769,null],[116255,"2026-07-15T18:12:03",17,"/ ща",34769,null],[116257,"2026-07-15T18:13:14",17,"/ Фейский шаг. Вы можете бонусным действием магическим образом телепортироваться в свободное пространство, которое можете видеть в пределах 30 футов. Вы можете использовать эту особенность количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования по окончании продолжительного отдыха.",34769,null],[116258,"2026-07-15T18:13:17",17,"/ Надо видить бля",34769,null],[116260,"2026-07-15T18:13:26",17,"/ Приколитесь а у Шадаркай нет такой приписки",34769,null],[116263,"2026-07-15T18:14:09",17,"/ Хотя хз там написано пространство вашей видимости, хуй пойми такой вординг",34769,null],[116266,"2026-07-15T18:14:38",11,"// все такие тп работают с тем что ты видел мне кажется",34769,null],[116267,"2026-07-15T18:15:15",17,"/Поменял пост",34769,null],[116269,"2026-07-15T18:16:03",5,"— Да. Значит, магический генератор держит барьер, и тот бьёт током любую магию. Что же с этим делать?",116241,null],[116270,"2026-07-15T18:16:15",9,"Хардинт — Значит стену не сломать, она реагирует на магию и как пройти дальше неизвестно. — *Подумал немного, пробормотал:* — Зона антимагии... нет...",34769,null],[116272,"2026-07-15T18:17:19",9,"*Несколько электрических разрядов ударили фауста.*\n\n//1 электричеством",116248,null],[116274,"2026-07-15T18:18:55",9,"Хардинт — Осторожнее, если это магическая ловушка или что-то подобное неизвестно как она ещё отреагирует. — *Окликнул Фауста.*",34769,null],[116280,"2026-07-15T18:20:53",17,"Фауст от досады схватил клинок и вонзил его в стену прямо в одну из своих листовочек",34769,null],[116281,"2026-07-15T18:21:13",41,"( Ого, вы далеко отписали",34769,null],[116282,"2026-07-15T18:21:18",41,"( Погодите пж",34769,null],[116283,"2026-07-15T18:21:37",9,"*Клинок сискользнул со стены даже не поцарапав.*",116280,null],[116284,"2026-07-15T18:22:20",9,"//Не заставляйте моего перса придумывать план 😏👌",34769,null],[116285,"2026-07-15T18:22:50",5,"// можно кинуть что-то?",34769,null],[116286,"2026-07-15T18:23:16",9,"//Кидай и опиши что хочешь этим получить",116285,null],[116287,"2026-07-15T18:24:06",5,"/r +2 магия\nДракон задумался, как преодолевают магические барьеры, источник которых находится внутри барьера.",34769,null],[116291,"2026-07-15T18:25:34",9,"*Если барьер контактирует с вещами снаружи, то надо как-то его заставить потратить энергию всю разом.*",116288,null],[116293,"2026-07-15T18:26:29",5,"— Мне в голову пришла идея... Надо перегрузить барьер! Чтобы он израсходовал всю магическую энергию",34769,null],[116294,"2026-07-15T18:27:40",11,"— Если реагирует он только на магию, то и перегрузить его нужно магией, есть идеи? Я ею не владею",34769,null],[116295,"2026-07-15T18:28:49",5,"— Да, магией. У меня из магического только эта палочка...",116294,null],[116296,"2026-07-15T18:28:52",9,"Хардинт — Думаю модет быть неплохой взрыв от попытки. Но у меня нет пока идей.",34769,null],[116297,"2026-07-15T18:29:54",5,"— Нужен постоянный источник магии. Хардинт, а зачарованное оружие хранит магию в себе. Или её можно высвободить?",34769,null],[116298,"2026-07-15T18:30:48",11,"— Магическое оружие? — кентавр взял в руки пику осматривая её — можно попробовать, кто знает?",34769,null],[116299,"2026-07-15T18:32:03",9,"Хардинт — Зачарованное оружие? Магии в нём немного, она постоянно течёт через контур теряя силу, но постоянно пополняет силу из окружения. — *Подумал как обьяснить попроще.* — Это как кровь по венам, только магия, её на деле немного.",34769,null],[116300,"2026-07-15T18:33:54",5,"— Как кровь по венам, уходя через контур... Барьер должен почувствовать её!",116299,null],[116301,"2026-07-15T18:35:05",9,"*Смотрит непонимающе.*\n\n//Я тоже не понял ничё ^^",116300,null],[116302,"2026-07-15T18:35:52",5,"// хм изменил",34769,null],[116423,"2026-07-15T19:20:08",9,"//Придумывайте планы, взаемодействуйте, я бы хотел закончить сегодня.",34769,null],[116427,"2026-07-15T19:21:55",5,"/ игроки потерялись",116423,null],[116429,"2026-07-15T19:23:11",9,"//Похоже",116427,null],[116436,"2026-07-15T19:24:08",17,"/ мне сложно что то выдумать тут. У меня нет ни магии ни взрывчатки. Физическое воздействие не сработало. У меня нет идей.",34769,null],[116441,"2026-07-15T19:25:44",5,"Гвиндшарх достал свой магический дротик и коснулся стены им",34769,null],[116442,"2026-07-15T19:25:50",5,"// дротик+1",34769,null],[116444,"2026-07-15T19:26:53",5,"— Фауст, можешь подпитать магию дротика своими заговорами?",34769,null],[116446,"2026-07-15T19:27:47",17,"/У меня и заговоров нет, это чисто для отыгрыша всякие снежинки и лёд, типо по механике нету такого но чтоб разнообразить отыгрываю",116444,null],[116448,"2026-07-15T19:28:29",17,"Немой подошел и взяв дротик за древко как смог напрягся чтобы покрыть его льдом",116444,null],[116450,"2026-07-15T19:28:40",17,"/r -1 магия",34769,null],[116452,"2026-07-15T19:28:45",17,"/ Ну да",34769,null],[116453,"2026-07-15T19:29:10",5,"// окак понял",116446,null],[116463,"2026-07-15T19:32:52",9,"*Разряд был сильнее ранних, металл поглотил часть, жадно.",34769,null],[116466,"2026-07-15T19:33:20",9,"/roll 1d4 часов дротик перестал быть магическим",34769,null],[116474,"2026-07-15T19:34:24",5,"— Работает! Надо больше магических вещей. У кого что есть?\n\nДракон взял дротик повертел в руках и снова приложил к стене.",34769,null],[116486,"2026-07-15T19:35:48",11,"Иштар прислонил пику к стене\n\n— Все что у меня есть магического — произнес он",34769,null],[116487,"2026-07-15T19:35:58",9,"Хардинт — Я не дам свои вещи. — *Покачал головой.* — Они могут испортится, вдруг мы потеряем всё и нового не достанем?",34769,null],[116492,"2026-07-15T19:36:45",5,"— Где твой дух исследователя? Вещи — дело наживное, ещё найдешь. Неужели ты не хочешь пробраться за стену?",116487,null],[116501,"2026-07-15T19:38:48",11,"//предлагаем все что есть",116486,null],[116503,"2026-07-15T19:38:58",9,"Хардинт — Умер в кошельке, я на мели. Простите. Сейчас едва свожу концы с концами, а если с сумкой чтослучится вы точно не будете нести кучу моих вещей. Слугами рисковать тоже не буду, таких не достать.",34769,null],[116509,"2026-07-15T19:40:03",5,"— Я компенсирую тебе потери в случае чего. Золото есть, после удачного дела! — Гвинди подмигнул\n\n— Давай же, помоги нам!",116503,null],[116510,"2026-07-15T19:40:13",9,"*На пику оно отвечат корокими ударами, периодически. Ничего не происходит ни с предметом ни с барьером, лишь раздражение на касание.*",116486,null],[116511,"2026-07-15T19:40:22",5,"Гвинди достал волшебную палочку и тоже прислонил к стене",34769,null],[116515,"2026-07-15T19:41:02",9,"Хардинт — Да зватит мучать волшебные предметы! Модет просто заземлить барьер.",34769,null],[116518,"2026-07-15T19:41:32",5,"— Заземлить? Объясни",116515,null],[116520,"2026-07-15T19:41:39",9,"*Ремесленник негодует как вы портите то что он куёт неделями без продыху.*",34769,null],[116535,"2026-07-15T19:43:13",9,"Хардинт — Магия или нет, молния тёчет по металу. А когда уходит в землю — теряет силу",34769,null],[116540,"2026-07-15T19:43:54",5,"— Но ведь барьер уже контактирует с землёй",34769,null],[116579,"2026-07-15T19:49:02",11,"Иштар убрал пику, достал металлическое длинное копьё и сделал как говорит Хардинит: поставил один край оружия на землю, а второй прислонил к стене в место где шли искры",34769,null],[116585,"2026-07-15T19:49:58",9,"Хардинт — Да не к камню. А к земле. Эх, прийдётся ковырять до земли.",34769,null],[116594,"2026-07-15T19:50:49",11,"// да представь что сделала как ты говоришь, я просто хочу уже продвинуться",34769,null],[116598,"2026-07-15T19:51:02",9,"*Подошёл к стене, немагической, и пытается кинджалом выковырять несколько кирпичей, пол то каменный, ток кирками рубить.*",34769,null],[116604,"2026-07-15T19:51:32",11,"*Иштар ударил копытом по земле так что камень треснул* \n\n— Пойдет?",116598,null],[116605,"2026-07-15T19:51:34",9,"//Ну, а я хотел чтобы вы сами решили физическую загадку, не судьба",116594,null],[116608,"2026-07-15T19:51:36",5,"*достал лёгкий молот, а ремесленнику дал молоток*\n\n— Так быстрее будет",34769,null],[116615,"2026-07-15T19:52:27",11,"// мне тяжело следить за всем учитывая наш темп",116605,null],[116617,"2026-07-15T19:52:54",17,"/ Я сдался. не понимаю.",34769,null],[116621,"2026-07-15T19:53:12",41,"( ребят, что я пропустила?",34769,null],[116622,"2026-07-15T19:53:20",17,"/ Давайте натрем стену как шарик о волосы",34769,null],[116623,"2026-07-15T19:53:34",17,"/ У кого есть колючий свитер?",34769,null],[116624,"2026-07-15T19:53:49",9,"*Короче, из мягкого серебра Хардинт потратил несколько часов обкатывая проволку. После зафиксировал часть на кинждале в земле и вторую намотал на копьё кентавра.*\n\nХардинт — Преподнеси к тому месту, только осторожно. — *Отходит.*",34769,null],[116631,"2026-07-15T19:55:11",11,"*Иштар обмотал руку хлопковым плащом и взял ею копьё, а затем отнёс в указанное место*",34769,null],[116658,"2026-07-15T20:00:06",9,"/roll 2d4 и тебе",116631,null],[116661,"2026-07-15T20:00:10",41,"( ай",34769,null],[116670,"2026-07-15T20:01:26",11,"// хлопковая ткань не проводит электричество",116658,null],[116677,"2026-07-15T20:02:16",41,"( бля",34769,null],[116678,"2026-07-15T20:02:25",41,"( я думала тереть надо (",34769,null],[116689,"2026-07-15T20:03:55",41,"--- Я.... Я....я не.... ((( \n\nСлегка расстроено, она отошла назад",34769,null],[116692,"2026-07-15T20:04:04",41,"( бля, нахуя я это ролила?",34769,null],[116693,"2026-07-15T20:04:29",41,"( не, я серьезно",34769,null],[116694,"2026-07-15T20:04:34",41,"( я б удалила",34769,null],[116699,"2026-07-15T20:05:07",41,"( я попросила подождать",34769,null],[116702,"2026-07-15T20:05:14",41,"( вы рванули дальше",34769,null],[116703,"2026-07-15T20:05:27",41,"( естественно когда я вернулась, Мне пришлось спешить",34769,null],[116706,"2026-07-15T20:06:02",41,"( просто у вас так принято? Я не понимаю",34769,null],[116707,"2026-07-15T20:06:24",41,"( меня явно нет через 100 сообщений",34769,null],[116709,"2026-07-15T20:06:29",11,"— Полагаю это сработало? — Иштар смотрит за тем как электричество идёт по копью — Вот бы всегда так было",34769,null],[116716,"2026-07-15T20:07:18",41,"( я удалила",34769,null],[116720,"2026-07-15T20:07:36",9,"*Как шибануло током, заискрилось что аж цурки летели. Пространство немного наэлектризовалось. И после вспышки и звука электрической дуги всё затихло.*",116631,null],[116721,"2026-07-15T20:07:44",41,"( этого не должно было быть, я не так поняла",34769,null],[116722,"2026-07-15T20:07:54",9,"//Никакого урона, просто вспышка",116720,null],[116724,"2026-07-15T20:08:09",41,"( я просто хочу отменить действие",34769,null],[116725,"2026-07-15T20:08:10",9,"//Даже наш кентавр обмотал руки тряпкой.",34769,null],[116727,"2026-07-15T20:08:18",9,"Да уже",116724,null],[116728,"2026-07-15T20:08:29",41,"( в с е действие",34769,null],[116729,"2026-07-15T20:08:36",9,"//И наши?",34769,null],[116732,"2026-07-15T20:08:41",41,"( да",34769,null],[116735,"2026-07-15T20:09:00",11,"// я удалила свое сообщение с комментарием твоих действий (?)",34769,null],[116736,"2026-07-15T20:09:09",41,"( да, спасибо",34769,null],[116737,"2026-07-15T20:09:17",41,"( Если Ты про трение",34769,null],[116738,"2026-07-15T20:09:25",11,"// давайте просто двигаться дальше раз все здесь",34769,null],[116741,"2026-07-15T20:09:44",41,"( Мне надо всё прочитать теперь",34769,null],[116742,"2026-07-15T20:10:00",9,"//Мы не коментировали, но фокус с проволкой ьещ тебя придумали тип, его точно не откачу, типа это как найти решение и го отеатим назад",34769,null],[116744,"2026-07-15T20:10:30",9,"//Я могу использовать совсем другую загадку для стены, у меня было ещё 2 варианта, если хотите ^^",34769,null],[116745,"2026-07-15T20:10:30",41,"( я не поняла ничего из сказанного",116742,null],[116746,"2026-07-15T20:10:49",41,"( я злюсь не на то что это не сработало",34769,null],[116747,"2026-07-15T20:11:04",41,"( а на то что вы ушли без меня на 100 сообщений",34769,null],[116748,"2026-07-15T20:11:27",41,"( и мне эту загадку в стоге сена искать",34769,null],[116749,"2026-07-15T20:11:29",9,"//Напиши что ждите в след раз.",116747,null],[116750,"2026-07-15T20:11:34",41,"Оооо",34769,null],[116751,"2026-07-15T20:11:41",41,".",116282,null],[116754,"2026-07-15T20:12:35",11,"// справедливости ради ты не уточнила сколько ждать. Но мы и в целом время для игры не обговаривали, я тут весь день сижу просто нормально отойти не могу ибо не понятно играем ли мы или нет, тоже такое себе..",34769,null],[116755,"2026-07-15T20:12:38",9,"//Сколько, я пишу что пропаду на 1 -2 часа. Для меня это как \"я думаю или на 5 мин отойду\". Сорян",116751,null],[116763,"2026-07-15T20:14:53",9,"//Ладно, я буду теперь спрашивать каждые 10 минут все ли тут? Поставьте реакции 😈",34769,null],[116767,"2026-07-15T20:15:41",9,"//Простите, я не думал что эля отойдёт надолго просто.",34769,null],[116769,"2026-07-15T20:15:55",41,"( я всегда жду игроков, когда их долго нет. Мне так привычнее",116754,null],[116770,"2026-07-15T20:16:08",41,"( Если у вас нет, то буду знать",34769,null],[116771,"2026-07-15T20:16:10",11,"// ладно, не буду выказывать недовольства, всякое бывает. В следующий раз просто заранее время для игры уточняем что бы всем удобно было и активно играли",34769,null],[116772,"2026-07-15T20:16:23",41,"За этим достаточно просто следить",116763,null],[116775,"2026-07-15T20:16:27",9,"//Обычно никто на такое не злится, все играют когда есть время. Если надо прдождать то указывают сколько именно или \"я отпишусь как буду\"",34769,null],[116776,"2026-07-15T20:16:53",41,"( Мне просто не всё равно на отыгрыш",116775,null],[116777,"2026-07-15T20:17:01",41,"( я не люблю пропускать",34769,null],[116778,"2026-07-15T20:17:18",9,"//Я тож в отыгрыш стараюсь, просто не всегда игроки на месте 🫠",34769,null],[116779,"2026-07-15T20:17:26",11,"// тут проблема в том что нормально не договорились, никто не виноват и все виноваты по немного, мир?",116776,null],[116780,"2026-07-15T20:17:48",9,"//Я виноват, мне так легче",116779,null],[116782,"2026-07-15T20:17:55",11,"// не начинай",116780,null],[116784,"2026-07-15T20:18:03",9,"//Лан, чекните когда продолжим",34769,null],[116785,"2026-07-15T20:18:04",41,"( Никто никогда не договаривался для того чтоб не спешить",116779,null],[116786,"2026-07-15T20:18:34",41,"( видите что кого-то нет, понимаете что он явно не просто игнорит вас",34769,null],[116939,"2026-07-15T20:53:29",41,"Надеюсь Иштар не уйдет",34769,null],[116953,"2026-07-15T20:56:05",41,"— Простите… \n\nСоль резко задумалась, затем приоткрыла глаза\n\n— Никто из нас ведь не может чувствовать этот барьер, верно ? \n\nПрижав к нему ладони, её глаза вновь закрылись и она обратилась к команде\n\n— Нас всех вместе пятеро. Примените магию с разных сторон стены, а я попробую почувствовать её центр. Возможно так мы поймем, в каком месте стена уязвимей всего ? Как кристалл",34769,null],[116957,"2026-07-15T20:58:18",9,"//Все тут?",34769,null],[116966,"2026-07-15T21:02:14",17,"Фауст плюнул бы да не может\n\nЭта стена его порядком выбесила он пошел с фонарем разглядывать другие стены",34769,null],[116976,"2026-07-15T21:05:36",17,"/ Магии нет. Второй шаг тратить не хочу. Я сдался давно на тему этой загадки физической с молниями или током. Охраняю группу от пещерных червей",116953,null],[116977,"2026-07-15T21:05:38",41,"( окэй, забиваем хуй",34769,null],[116978,"2026-07-15T21:06:04",41,"( хз там подморозить нарративно просто",116976,null],[116979,"2026-07-15T21:06:07",17,"/ Ну вы колдуйте я хуй знает. Предлагаю ждать пока Хардинг разгадает ее сам",34769,null],[117243,"2026-07-15T22:15:30",9,"//Лан, на сёдня все или вы тут? Скипаем стену раз так, не знаю. Решайте.",34769,null],[117244,"2026-07-15T22:15:53",41,"( Иштар уже афк",34769,null],[117245,"2026-07-15T22:15:59",17,"/ Я бы плюнул на стену вышел и пошел искать то то другое. Я проиграл этой задаче",34769,null],[117246,"2026-07-15T22:16:01",41,"( че нам скипать ? Я хз",34769,null],[117248,"2026-07-15T22:16:18",41,"( а разве мы не эту стену искали ?",117245,null],[117249,"2026-07-15T22:16:31",17,"/ Ну нашли и чего. Меня она бесит",34769,null],[117251,"2026-07-15T22:16:55",9,"//Я не знаю чего вы решили вот и спрашиваю.",34769,null],[117252,"2026-07-15T22:17:09",41,"( типа пришли и забили хуй ?",117249,null],[117253,"2026-07-15T22:17:20",9,"//Можем прийти и забить ху",34769,null],[117255,"2026-07-15T22:17:43",17,"/ я, да. У меня нет идей. Я попробовал что придумал. Щас идей ваще нет.",117252,null],[117256,"2026-07-15T22:17:45",9,"//В след раз кто-то другой разберет её. Мне же не писать ещё места",34769,null],[117257,"2026-07-15T22:18:10",41,"( у меня есть идея, но мне нужно минимум 2 около мага",34769,null],[117258,"2026-07-15T22:18:19",17,"/ Хардинг какие то там спирали блять часы придумал я ваще в ахуе",34769,null],[117259,"2026-07-15T22:18:26",41,"( А Фауст пожадничал шаги",34769,null],[117260,"2026-07-15T22:18:33",17,"Фауст подходит и делает что соль сказала",34769,null],[117261,"2026-07-15T22:18:43",41,"( мог хоть написать, что за ги ги",117259,null],[117262,"2026-07-15T22:18:46",17,"Делает фейский шаг как она сказала",34769,null],[117263,"2026-07-15T22:18:55",17,"/ Чего?",117261,null],[117264,"2026-07-15T22:19:03",9,"//Сейчас тут ток половина игроков, я жду их выходит",34769,null],[117265,"2026-07-15T22:19:04",41,"( ги ги за шаги",117263,null],[117269,"2026-07-15T22:19:24",17,"/ Ну для меня твой план абстрактный типа хуй пойми что",34769,null],[117270,"2026-07-15T22:19:34",17,"/ Будто бы тут хард придумал задачку по физике за 8 класс",34769,null],[117271,"2026-07-15T22:19:37",17,"/ На электричество",34769,null],[117272,"2026-07-15T22:19:45",41,"( для меня он не менее абстрактный",117269,null],[117273,"2026-07-15T22:19:52",17,"/ И я чувствую себя тупым",34769,null],[117274,"2026-07-15T22:19:53",17,"/ потому что прогуливал физику",34769,null],[117275,"2026-07-15T22:20:05",41,"( я ебу интуитивно её",34769,null],[117276,"2026-07-15T22:20:10",41,"( не выйдет и не выйдет",34769,null],[117277,"2026-07-15T22:20:11",17,"/ Давай давай",34769,null],[117278,"2026-07-15T22:20:28",17,"/ я тоже пернул в стену чуть выше и шаг юзал и трогал ее все это нихуя не дало",34769,null],[117283,"2026-07-15T22:21:37",9,"//Пу пу пу. Похоже я один о заземлении знаю. 😂👍",34769,null],[117284,"2026-07-15T22:21:41",41,"( у меня план чуть глубже, кинуть бросок ака магии какой-то своей ци хуйци понять, че это за хуйня",117278,null],[117286,"2026-07-15T22:22:04",5,"// вы можете стену открыть как хотите. У меня магии нет энивей. А завтра что-то решим уже",34769,null],[117292,"2026-07-15T22:22:34",9,"//Да, самый простой способ зона антимагии, но эт над сильный волшеьник",34769,null],[117294,"2026-07-15T22:22:39",17,"/ Ну вон хард раскрыл задачку",34769,null],[117295,"2026-07-15T22:22:40",41,"/r d20-1 ну я прокину магию по приколу",34769,null],[117299,"2026-07-15T22:23:02",9,"//Я раскрыл потому что вы её не хотите решать.",34769,null],[117303,"2026-07-15T22:23:17",9,"//Забейте. Просто награду уменьшу.",34769,null],[117307,"2026-07-15T22:23:55",9,"//Короче, как всегда все запорол. Простите)",34769,null],[117309,"2026-07-15T22:24:03",17,"Фауст берет ломик приставляет его снизу к стене а второй конец вонзает в землю",34769,null],[117310,"2026-07-15T22:24:39",41,"( я чет ваще не поняла про заземление",34769,null],[117311,"2026-07-15T22:24:43",17,"Так он хочет отвести часть электричества со стены в землю \n\nЗаземлить эту поеботину",34769,null],[117313,"2026-07-15T22:24:53",41,"( а, это",34769,null],[117317,"2026-07-15T22:25:12",41,"( но ведь это будто бы не совсем про реакции",34769,null],[117320,"2026-07-15T22:25:26",41,"( но это моё мнение",34769,null],[117324,"2026-07-15T22:25:59",17,"/ Я хз про что это у меня есть лом вот пробую заземлить",34769,null],[117326,"2026-07-15T22:26:01",9,"//Пу пу пу, сами же никого не ждёте)",34769,null],[117329,"2026-07-15T22:26:40",17,"/ я пишу заявку, как придут люди,  результат напиши",34769,null],[117330,"2026-07-15T22:26:43",9,"//Просто говорю что жду игроков",116957,null],[117331,"2026-07-15T22:26:43",17,"/ Пусть будет",34769,null],[117944,"2026-07-16T12:39:30",11,"// если хотите продолжить вместе тегните во флуде когда соберётесь",34769,null],[117945,"2026-07-16T12:42:09",17,"/ Так а что. Давайте продолжать. По постику с каждого",34769,null],[117946,"2026-07-16T12:42:54",5,"// может подождать всех, чтобы активно сыграть?",34769,null],[117947,"2026-07-16T12:46:17",17,"/ Ну мне норм если вы посты напишете я через пару часов приду почитаю и дам реакт",34769,null],[117948,"2026-07-16T12:46:36",17,"/ Работы много сегодня, прям сесть и сидеть не получается",34769,null],[117949,"2026-07-16T12:47:33",5,"// будет как вчера",34769,null],[117950,"2026-07-16T12:47:52",5,"// ну и вообще учитывая откат времени, жду от вас инициативу",34769,null],[117951,"2026-07-16T12:48:00",5,"// мы стену ломали, теперь ваша очередь",34769,null],[117952,"2026-07-16T12:48:59",17,"/ Последнее делал такое заземление, чтобы одолеть стену и дальше пойти кайфовать",117309,null],[117953,"2026-07-16T12:49:04",11,"// попробуйте идею Эли, у нас персы совсем без магии не поможем увы",34769,null],[117954,"2026-07-16T12:49:24",17,"// Ну и идею Эли тоже я поддержал Шаги фей 0/2",34769,null],[117961,"2026-07-16T13:09:29",41,"( мой перс кинул магию - 15",34769,null],[118076,"2026-07-16T18:25:33",17,"/ Вы как там ребята?\n\n@Ashenchampion @elsio28 Hard @sweetkittywitch",34769,null],[118084,"2026-07-16T18:28:17",41,"( живаааа",34769,null],[118097,"2026-07-16T18:31:14",17,"/ Что сыграем?",34769,null],[118098,"2026-07-16T18:31:18",17,"/ мастер переверни доску плиз",34769,null],[118100,"2026-07-16T18:31:26",17,"/ Чтобы забыть об этой проклятой стене как то",34769,null],[118106,"2026-07-16T18:31:43",41,"( внезапное нападение дрейка",34769,null],[118110,"2026-07-16T18:32:51",9,"//Ха ха. Ну, я без остальных не начну.",34769,null],[118111,"2026-07-16T18:32:58",11,"// мы тут",34769,null],[118112,"2026-07-16T18:33:01",5,"// тут",34769,null],[118120,"2026-07-16T18:34:01",9,"//О, новая таверна подождет тогда. Емли начну в ближайшее время все тут?",34769,null],[118132,"2026-07-16T18:36:29",41,"( я сама таверну сделаю дааааай",118120,null],[118136,"2026-07-16T18:37:34",9,"//Бл, но эт отвлекаться",118132,null],[118138,"2026-07-16T18:37:47",9,"//Тогда ждите, чё",34769,null],[118139,"2026-07-16T18:37:49",41,"( просто темка",118136,null],[118142,"2026-07-16T18:38:06",9,"//Не просто, ответвление и тд, ща",34769,null],[118145,"2026-07-16T18:39:37",41,"( пока пойду писать чтоб не тратить время зря",34769,null],[118146,"2026-07-16T18:39:42",41,"( всем сори",34769,null],[118212,"2026-07-16T18:48:34",9,"*Герои общими усилиями смогли разрядить барьер, гудение как и электричество ушло и стена больше не реагировала на магию, даже казалось потускнела.*",34769,null],[118219,"2026-07-16T18:51:08",5,"Гвиндшарх оглянулся на остальных.\n\n— Пойдём, посмотрим, что внутри!\n\nДракон зажёг факел и вошёл внутрь, ища взглядом магическое устройство, создавшее барьер",34769,null],[118226,"2026-07-16T18:52:09",9,"*Стена все ещё стоит.*",34769,null],[118232,"2026-07-16T18:53:07",11,"— Ну магия угасла, но что дальше? — Иштар вновь коснулся стены",34769,null],[118235,"2026-07-16T18:53:50",9,"Хардинт — Может попробовать выбить, если её удерживала только магия должно сработать.",34769,null],[118237,"2026-07-16T18:54:11",9,"//А ещё игроки бы все на месте были",34769,null],[118248,"2026-07-16T18:55:48",17,"Фауст ищет кирку неподалёку",34769,null],[118250,"2026-07-16T18:55:56",17,"/r +4 Вдруг шахтеры оставили",34769,null],[118252,"2026-07-16T18:56:32",11,"— Хм.. стоило купить таран, но мне и так грубой силы должно не занимать что бы с этим справиться — кентавр осматривает стену в надежде найти более уязвимое место, где например кирпич потрескался..",118235,null],[118254,"2026-07-16T18:56:39",9,"*Сломанный инструмент есть, да, щас им не помашешь.*",118251,null],[118256,"2026-07-16T18:57:22",9,"*Нигде нет, просто стена как и ранее, выглядит идеальной. Самое слабое место? Конечно же посередине.*",118252,null],[118258,"2026-07-16T18:57:59",11,"// может трайчонок чувствует где более тонкое место?",34769,null],[118264,"2026-07-16T18:58:53",9,"*Кирпичи идеальной формы и сложенны без зазоров, правда тонко, всего в 1 кирпич толщиной.*",118258,null],[118266,"2026-07-16T18:59:14",17,"На бумаге появляется надпись рукой зимнего\n\n\"Хардинг, есть идеи? Я готов помахать киркой, только скажи что делать?\"",34769,null],[118270,"2026-07-16T19:00:15",9,"*Просто дастает молоток, и бьёт по стене, один кирпич немного смещается внутрь.*\n\nХардинт — Теперь она не такая неразрушимая.",34769,null],[118271,"2026-07-16T19:00:17",5,"— Грубая сила — не про меня — дракон развёл лапами",34769,null],[118273,"2026-07-16T19:00:34",11,"Трайчонок берет разгон и бодает стену в месте где Хардинит выбил кирпич",118270,null],[118276,"2026-07-16T19:00:53",5,"— Сера, давай!",118273,null],[118277,"2026-07-16T19:01:02",5,"// моральная помощь",34769,null],[118281,"2026-07-16T19:01:28",11,"// можно так?)",34769,null],[118285,"2026-07-16T19:01:34",9,"Хардинт — Думаю сейчас не так важно.\n\n//Ждём Элю, хоия у меня на телефоне 11% а она на таверну заагрилась",118266,null],[118286,"2026-07-16T19:01:53",5,"// не думаю, чисто нарратив)",118281,null],[118289,"2026-07-16T19:02:23",5,"// очень вовремя @sweetkittywitch",118285,null],[118292,"2026-07-16T19:03:02",17,"Фауст ломик, как гвоздодёр просовывает в отверстие которое хардинг пробил. И зовёт на помощь Иштара, махая тому рукой.",34769,null],[118294,"2026-07-16T19:03:13",17,"Получился рычаг",34769,null],[118298,"2026-07-16T19:03:52",11,"// ну я свою заявку предложила и заявку Коли поддержать могу, жду Элю и одобрение мастера",34769,null],[118301,"2026-07-16T19:04:19",17,"/пупупупупупуппупупу",34769,null],[118302,"2026-07-16T19:04:34",41,"( я писать отходила бляяч",34769,null],[118308,"2026-07-16T19:05:35",41,"Соль растопыривает ногу чтоб пробить стену как кунг фу эльф",34769,null],[118317,"2026-07-16T19:06:42",11,"// Hard",34769,null],[118319,"2026-07-16T19:06:55",41,"( но спасибо, что подождали",34769,null],[118323,"2026-07-16T19:07:14",9,"*Деревянный динощаврик даже с разгоном не такой тяжёлый чтобы повлиять на стену, он просто глухо ударился о все ещё прочную стену.*",118273,null],[118331,"2026-07-16T19:07:47",9,"*Когда первый кирпич выпал, соседние легче пошли.*",118292,null],[118332,"2026-07-16T19:07:48",11,"Трайчонок недовольно фыркнул упав крупом на землю от столкновения.",118323,null],[118335,"2026-07-16T19:08:02",5,"Дракон подошёл погладить его, чтобы утешить",118332,null],[118336,"2026-07-16T19:08:06",41,"/r d20+5 ногой по стене ХУЯК",34769,null],[118341,"2026-07-16T19:08:26",11,"Кентавр подошёл помогать Фаусту, как в стену внезапно влетела Соль",118331,null],[118345,"2026-07-16T19:09:17",9,"//Опиши как Соль разьебала стену)",118337,null],[118347,"2026-07-16T19:10:05",5,"Гвиндшарх тем временем наблюдал за разлетом кирпичей, а позже подошёл и засунул 5 штук себе в рюкзак",34769,null],[118354,"2026-07-16T19:11:40",11,"Трайчонок следует за драконорожденным и бодает самые целые на вид помогая ему",118347,null],[118357,"2026-07-16T19:12:04",11,"// он сумкой биться будет короче\n\nПрикиньте урон от сумки с кирпичами",34769,null],[118358,"2026-07-16T19:12:04",5,"— Спасибо, Сера!\n\nДракон взял кирпич, на который указал динозаврик",118354,null],[118359,"2026-07-16T19:12:23",9,"//Стена все еще стоит, пока нет описания, не спешите!",118347,null],[118361,"2026-07-16T19:12:33",5,"// 😡",34769,null],[118375,"2026-07-16T19:14:08",17,"Не жалея сил эладрин колотит по кирпичикам которые уже не окружены соседними расширяя дыру",34769,null],[118377,"2026-07-16T19:14:14",17,"/r -1 СИЛА ПОООШЛА",34769,null],[118379,"2026-07-16T19:14:22",41,"--- Бегите...\n\nЭлегантные движение Соль были подобны плавному танцу, однако стоило её ступне коснуться торчащего кирпича, как ударная волна в одно мгновение вызвала трещины в стене \n\nВ следующее стена под влиянием высводившейся энергии барьера отлетела назад и по бокам, еле улерживая остальную конструкцию дома",118345,null],[118380,"2026-07-16T19:14:35",9,"*Медленно выпадают по одному, тяжко.*",118378,null],[118381,"2026-07-16T19:15:07",9,"*Проход свободен.*",118379,null],[118383,"2026-07-16T19:15:28",41,"Полагаю, поднялось облако пыли",34769,null],[118385,"2026-07-16T19:15:36",11,"— Полагаю теперь можно идти — откашливаясь от пыли произнес воин",34769,null],[118388,"2026-07-16T19:15:41",5,"// собрал кирпичи",118381,null],[118389,"2026-07-16T19:15:46",9,"Хардинт — Не хотел бы быть вашим врагом леди Соль. — *Вытирает лоб и прячет молот.*",34769,null],[118395,"2026-07-16T19:17:03",5,"— Да, пойдём!\n\nГвинди закрыл рюкзак и зажёг факел",118385,null],[118399,"2026-07-16T19:17:17",5,"Затем вступил в проход, настороженно смотря внутрь",34769,null],[118400,"2026-07-16T19:17:31",41,"--- Все в порядке? Я ничего не вижу...",34769,null],[118404,"2026-07-16T19:17:58",17,"И Фауст замыкает со своим фонарём",34769,null],[118407,"2026-07-16T19:18:14",41,"( Фауст, белый от пыли:🤌",118400,null],[118410,"2026-07-16T19:18:44",5,"— Немного пыли, ничего смертельного",118400,null],[118414,"2026-07-16T19:19:13",9,"*Внутри были металические стержни, они торчали с другой стороны стены и от них шла проволка дальше где стояли стержни уже вертикально обрамлённые колтцами из меди. Возле странного устройства было много мусора? Похоже здесь была чья то лаборатория, но все записи истлели. На самом металлическом устройстве есть несколько округлых камней ращмером с яйцо, гладких, они будто прилипли к конструкции.*",34769,null],[118421,"2026-07-16T19:19:37",17,"/ Я думал уже эту стену побеждать страдательным постом\n\nФауст вонзает лом в землю недалеко от стены, рвет часть серебрряных нитей с болью кровью, рваные раны остаются, проклятье снова зашивает рот почти сразу. Но нити в руке и он связывает их чтобы сделать проволоку и соеденить стену с ломом\n\nзаземление\n\nЗанавес",34769,null],[118427,"2026-07-16T19:20:20",41,"( не пропадет хитрец",118421,null],[118430,"2026-07-16T19:20:31",5,"Гвинди с интересом разглядывает устройство.\n\n// Анализ?",118414,null],[118431,"2026-07-16T19:20:43",5,"— Что за камни такие?",34769,null],[118435,"2026-07-16T19:21:16",9,"*Репонятно что это вообще, но всё металлическое на тебе слегка притягивается к нему и прилипает.*",118430,null],[118437,"2026-07-16T19:21:33",41,"Соль сейчас выглядела потерянной, будто никогда и не была зрячей. \n\nРукой она коснулась лошадиного туловища Иштара\n\n--- Помогите, пожалуйста...",118385,null],[118439,"2026-07-16T19:21:48",5,"— Магнит! — заключил дракон",118435,null],[118456,"2026-07-16T19:22:55",11,"— Чем я могу помочь? — он пытался разглядеть девушку сквозь пыль",118437,null],[118466,"2026-07-16T19:24:06",5,"— Значит, и эти камни магнитные. Впрочем, разница небольшая. Меня больше интересует как хозяин этого места входил внутрь",118414,null],[118467,"2026-07-16T19:24:09",9,"Хардинт — Я бы сказал даже большой магнит. — *Проверяет его, вроде бы просто прилипают к нему металлические вещи, оторвать их легко.* — Кажется эта штука держала заряд или что-то такое.",118439,null],[118472,"2026-07-16T19:24:46",9,"*Проводник пожимает плечами, он сам впервые подобное видит.*",118466,null],[118473,"2026-07-16T19:25:09",5,"— Как думаешь, устройство можно включить опять?",118467,null],[118474,"2026-07-16T19:25:24",11,"// поищи другой выход)",118466,null],[118477,"2026-07-16T19:25:53",5,"// кстати я с самого начала забыл отыграть, что дракон уже знаком с хардинтом, точнее с версией до перерождения. А ведь Гвиндшарх считал его другом",34769,null],[118483,"2026-07-16T19:27:20",9,"Хардинт — Что точно так этой штуке нужна энергия. — *Постучал по ней, гудит как камертон слегка, показывает на стержни уходящие в потолок.* — Может оно ловило молнии, не знаю, сейчас не уверен что получится её зарядить.",118473,null],[118485,"2026-07-16T19:27:48",41,"--- Мне нужен проводник",118456,null],[118487,"2026-07-16T19:28:25",9,"//Кентавр одолжил медный кабель)\n(шучу)",118485,null],[118493,"2026-07-16T19:29:20",5,"Гвиндшарх оценил ведущие вверх стержни. \n\n— Молния? Идея отличная. Барьер, который заряжается сам. И значит, если начнется гроза, он снова включится. Если твоя теория верна, конечно",118483,null],[118494,"2026-07-16T19:29:25",41,"( покатай меня",118487,null],[118497,"2026-07-16T19:29:39",41,"( могучая кучка",34769,null],[118503,"2026-07-16T19:30:14",11,"— Конечно — кентавр взял ее за руку и осторожными шагами последовал за остальными внутрь",118485,null],[118507,"2026-07-16T19:31:01",5,"— Надо осмотреть это место!\n\nВ первую очередь Гвиндшарх смотрит, есть ли другие выходы",34769,null],[118508,"2026-07-16T19:31:16",11,"// ты сейчас не Йинь:D а так кентавры существа гордые, на спину без дела сажать не будут",118494,null],[118513,"2026-07-16T19:32:06",41,"--- Спасибо.",34769,null],[118517,"2026-07-16T19:32:38",11,"— Твоя нога в порядке? Удар был сильным",118513,null],[118518,"2026-07-16T19:32:47",41,"( Йинь бы ему массаж спины ножками сделала",118508,null],[118519,"2026-07-16T19:32:48",9,"*Есть несколько ответвлений и комнат, похоже в это место можно было попасть по другому, но проходы вне основной комнаты обрушенны.*",118507,null],[118521,"2026-07-16T19:33:39",5,"*Смотрю, насколько велики завалы*",118519,null],[118522,"2026-07-16T19:33:42",41,"--- Да, я так иногда делаю. Но когда стена упала, мир будто стал ватным...",118517,null],[118525,"2026-07-16T19:33:55",17,"Фауст не стал связываться с этой шуткой \"магнитом\" он пошел внимательно изучать ответвления и завалы. Возможно есть вариант протиснуться где то",34769,null],[118530,"2026-07-16T19:34:36",9,"//2% я оф щас, сорян",34769,null],[118532,"2026-07-16T19:35:05",9,"//Продолжим как буду в сети/соберёмся, минимум на час пропаду",34769,null],[118536,"2026-07-16T19:35:27",11,"Кентавр вздохнул и сел на передние колени\n\n— Присаживайтесь, леди",118522,null],[118542,"2026-07-16T19:37:01",41,"--- Благодарю за ваше снизхождение \n\nОна забралась на спину. Удивительно, Но весит она не так много даже в платье",34769,null],[118549,"2026-07-16T19:38:31",11,"Иштар даже не почувствовал. Сумка с запасами казалось весила больше",34769,null],[118558,"2026-07-16T19:39:53",41,"Мокси решил не садиться к Соли, чтоб не грузить кентавра, и гордо побежал перед ним, будто ведет эту громадину",34769,null],[118565,"2026-07-16T19:40:34",5,"Гвиндшарх посмотрел на кентавра и улыбнулся.\n\n— Помнится, ты очень возмущался, когда я на твоей спине выбрался из лагеря",34769,null],[118572,"2026-07-16T19:42:02",11,"— Брат, не начинай.. — Иштар думал лишь о том что бы об этом не узнали его сородичи",118565,null],[118576,"2026-07-16T19:42:50",5,"— Как скажешь! — дракон подмигнул",118572,null],[118602,"2026-07-16T19:48:09",41,"--- Ох, правда? \n\nЕё глаза приоткрылись от удивления\n\n--- Надеюсь, я не доставляю неудобств...",34769,null],[118606,"2026-07-16T19:48:32",11,"— Всё в порядке, я всегда рад помочь",34769,null],[118619,"2026-07-16T19:52:44",41,"в таком случае, она заботливо погладит его по лошадиной спине",34769,null],[119054,"2026-07-16T21:25:25",41,"( и отдыхаем",34769,null],[119445,"2026-07-16T22:52:52",5,"// вы тут?",34769,null],[119787,"2026-07-17T07:33:32",17,"/ Я уже спал. Предлагаю перейти в режим \"пришел отписал пост по ситуации - и так двигаться\" вот эти сборы всех в одно время затея так себе имхо",34769,null],[119802,"2026-07-17T13:15:09",9,"/roll 3d20 уцелевшие приборы и прочее на столько то золотых",34769,null],[119804,"2026-07-17T13:17:05",9,"*Многое истлело, кроме разве что нескольких кристаллов, мензурок и колб. Какие-то золотые прутья и металлические инструменты.*\n\n//На 37 золотых алхимического хлама",34769,null],[119805,"2026-07-17T13:17:54",41,"Соль берет что-то из хлама и с интересом перебирает в руках. Что ей дали ?",34769,null],[119806,"2026-07-17T13:18:37",9,"*Хардинт оторвал несколько камней от устройства.*\n\nХардинт — Это кажется магниты. — *Он прошёлся ими над хламом и притянул всякую металлическую мелочь.* — Здесь их штук пять, думаю могут пригодится, один мой.",34769,null],[119807,"2026-07-17T13:19:52",9,"//Можете взять \"Магнитный камень размером с яйцо\"",34769,null],[119808,"2026-07-17T13:20:09",41,"Магнитный камень в форме яйца*",34769,null],[119809,"2026-07-17T13:20:33",41,"( прикиньте их все крутить в руках как антистресс",34769,null],[119810,"2026-07-17T13:20:54",41,"( предлагаю продать их по большей цене с этой причиной",34769,null],[119811,"2026-07-17T13:21:26",9,"*Это была длинная спиральная трубка из калёного стекла, крепкая, её не взяло время.*",119805,null],[119812,"2026-07-17T13:22:00",9,"//Всякого хлама на 37 золотых и 5 магнитных чёрных камней в форме яйца. Вот что, камни отдельно, считайте камни это обычный маг предмет каждый такие хрен найдёшь)",34769,null],[119813,"2026-07-17T13:23:39",5,"— Ничего интересного. Разве что эти магниты...",34769,null],[119814,"2026-07-17T13:23:52",5,"// напиши им описание тогда",119812,null],[119815,"2026-07-17T13:24:58",41,"Как жаль, что Соль не знает о том, как эту трубку можно использовать в качестве мини-холодильника",34769,null],[119816,"2026-07-17T13:24:58",9,"\"Чёрный магнитный камень в форме яйца\"\n\nОбычный чудесный предмет. Магнитится к металлу, гладкий.",119812,null],[119817,"2026-07-17T13:25:51",41,"( ребят, у нас в руках золото. Пж пусть кто-то окажется зубрилкой(",119815,null],[119818,"2026-07-17T13:28:02",9,"Хардинт — Здесь не оказалось ничего особо интересного. — *Пытается найти что-то среди хлама.* — Думал нас ждёт сокровище или ещё что-то. — *Взглянул на стержни и установку в целом.* — Даже это, не зная как оно устроенно не смогу повторить, здание мы не разберём.",34769,null],[119819,"2026-07-17T13:29:25",41,"— Эта стена ведь что-то оберегала… не может быть, что сокровище просто исчезло ?",34769,null],[119821,"2026-07-17T13:30:50",9,"//Персонаж не знает того чего не знаю я, прости. Хотя я вкурсе о всяких элементах пельтье, схемах кондиционара и прочее, не могу понять при чём тут спиральная алхимическая трубка из калёного стекла.",119817,null],[119822,"2026-07-17T13:31:05",5,"// у дракона инт 15, но я не понимаю твоей идеи",119817,null],[119824,"2026-07-17T13:33:27",9,"Хардинт — Может и есть что-то, но это место не похоже на сокровищницу. — *Попытался ещё поискать, может какие-то скрытые тайники, но ничего.* — Или оно просто хорошо было спрятанно.",119819,null],[119826,"2026-07-17T13:33:58",41,"( ну может я туплю. Но это типо как передатчик тепла или … ладно , наверное правда сомнительно",119821,null],[119827,"2026-07-17T13:34:19",41,"@Ashenchampion  ?",34769,null],[119830,"2026-07-17T13:35:59",41,"— А если это никогда и не было сокровищницей, а защищало совсем другую цель ? Маги способные запечатать здание оберегали себя от чего-то за его пределами, а когда опасность миновала - ушли. Вы помните следы битвы в руинах? Можно ли их сейчас различить ?",34769,null],[119831,"2026-07-17T13:37:00",5,"— Скорее чья-то тайная мастерская",119824,null],[119832,"2026-07-17T13:38:27",9,"*Кивнул в согласии, Хардинт и сам открыл тайную мастерскую и там реально ничего ценного, самое ценное он носил с собой.*",119831,null],[119833,"2026-07-17T13:39:49",5,"— Битва давно закончилась. Маги могли бы спрятаться здесь, но создавать целое устройство для защиты места? Больше похоже на работу инженера.",119830,null],[119834,"2026-07-17T13:40:22",5,"// хард, что там по состоянию завалов",34769,null],[119835,"2026-07-17T13:40:37",9,"//Я бы подождал остальных, может у них будут иди прежде чем выходить отсюда",34769,null],[119836,"2026-07-17T13:40:58",41,"— Оу, это бы объяснило наличие этих загадочных штучек)",119833,null],[119837,"2026-07-17T13:42:05",9,"*Два прохода отсюда завалены, они похожи на тот из которого мы пришли, скорей всего вели в другие здания, проволка от навершия устройства натянута как струна и уходит под завалы.*",119834,null],[119841,"2026-07-17T13:44:43",11,"// все нормально",119835,null],[119842,"2026-07-17T13:45:11",41,"Иштар чиллит ?",119841,null],[119843,"2026-07-17T13:45:24",9,"//Нам бы идей может каких если есть)",119841,null],[119844,"2026-07-17T13:45:29",11,"Кентавр с любопытством осматривает заваленные проходы оценивая можно ли разобрать их собственной физической силой и помощью лома Фауста",119837,null],[119845,"2026-07-17T13:46:12",9,"*Это займёт вечность, и как бы ещё не обвалилось.*",119844,null],[119846,"2026-07-17T13:47:31",5,"Гвиндшарх подошёл к столу, взял самый целый свиток и попытался прочитать хоть что-то.\n\n— Да, жаль толку от них нет. Срок службы давно прошёл",119836,null],[119847,"2026-07-17T13:48:06",41,"— значит никаких сокровищ и неё было ? Что ж… всё равно приятно путешествовать с вами)",34769,null],[119848,"2026-07-17T13:48:17",9,"*Чернила давно выгорели, едва различимы и размыты, свиток почти рассыпается в руках.*",119846,null],[119849,"2026-07-17T13:49:33",9,"Хардинт — Не все места ведут с сокровищам. — *Вздохнул и бросил искать что-то в хламе, просто идёт вдоль стен проводя рукой.*",34769,null],[119850,"2026-07-17T13:49:47",5,"// можно с помощью инструментов каллиграфа повторить направление письма чернил и восстановить что-то?",34769,null],[119851,"2026-07-17T13:50:29",9,"//Попробуй",119850,null],[119852,"2026-07-17T13:54:02",5,"Гвиндшарх достал чистый лист и положил на стол рядом с рассыпающимся свитком. Затем взял перо, внимательно осмотрел различимые чернила в свитке и повторил линию на новом листе. Потом ещё и ещё. Через какое-то время он смотрит на лист, ища смысл в написанном.",34769,null],[119856,"2026-07-17T13:57:02",11,"— Получается мы пришли грабить магов которые и так считаются уязвимыми в наше время? — Иштар почувствовал некий укол вины",34769,null],[119857,"2026-07-17T13:58:05",11,"— Что-то ещё ищешь? Например \"тайный проход\" или вроде того?",119849,null],[119858,"2026-07-17T13:59:53",11,"— Может у магнитов была и другая функция..?",34769,null],[119859,"2026-07-17T14:02:39",9,"*Сложно что-то вычленить, но удалось понять самое частое словосочитание \"вместилище молний\", ещё угадывалось слово \"поймать\".*",119852,null],[119860,"2026-07-17T14:03:13",9,"Хардинт — Здесь все давно истлело, хозяева этого места скорей всего давно почили.",119857,null],[119861,"2026-07-17T14:03:14",17,"Фауст всё ещё ходит в поисках места куда можно протиснуться через завал и еслоитакого нет возвращается к остальным",34769,null],[119862,"2026-07-17T14:03:47",17,"/ Понятно. Тут сделали Баса Лайтера",119859,null],[119863,"2026-07-17T14:04:08",5,"— Могу прочитать что-то про вместилище молний. И что кого-то надо поймать. Или скорее что-то... молнию. Это подтверждает работу устройства от молний. Даже не знаю, зачем нам это",34769,null],[119864,"2026-07-17T14:04:33",17,"/ Да подкласс варвара на днд Су в разделе хб)",119863,null],[119865,"2026-07-17T14:05:00",5,"// такое не знаю",34769,null],[119866,"2026-07-17T14:05:10",9,"//О котором узнал вот только что ^^",119864,null],[119867,"2026-07-17T14:05:43",17,"/ Ладно я чсвешнг думаю что все вокруг меня в мире кружится забейте",34769,null],[119868,"2026-07-17T14:06:05",5,"// я не понимаю, как мы должны догадаться до чего-то",119866,null],[119869,"2026-07-17T14:06:11",5,"// может кубик на анализ?",34769,null],[119870,"2026-07-17T14:06:59",9,"//Это место для отыгрыша а не квест, если не найдёте чего, оно останется тем кто догадается",34769,null],[119871,"2026-07-17T14:08:04",5,"Гвиндшарх потоптался в комнате, а затем пошёл к выходу.\n\n— Ничего полезного больше нет. Нет смысла задерживаться",34769,null],[119872,"2026-07-17T14:08:37",17,"Эладрин кивнул и последовал за Гвиндшахом",119871,null],[119873,"2026-07-17T14:09:03",9,"//Соль и Иштар тоже пусть чекнут и дальше двинем)",34769,null],[119874,"2026-07-17T14:13:23",11,"// мне добавить нечего",34769,null],[119875,"2026-07-17T14:23:26",17,"/ Физика лже наука. В днд надо деградировать и убивать нечисть",34769,null],[119876,"2026-07-17T14:36:13",41,"--- Не волнуйся. Уверена, если бы они были здесь, мы бы договорились.\n\nОна вновь погладила опечаленного кентавра",119856,null],[119877,"2026-07-17T14:37:06",11,"// я за то что бы закончить поиски на этом",34769,null],[119878,"2026-07-17T14:47:01",9,"*Собрав все полещное что можно герои выходят из подвала в часовню где их ждут искатели сокровищь. Сидят на растоянии и глава на камне. Окружили, держат оружие в руках хоть и не поднимают, выглядят не дрюжелюбно.*",34769,null],[119879,"2026-07-17T14:48:40",9,"Жанка — Ну что работнички, вскрыли стену? Может сокровища какие нашли. — *Женжина щурится одним глазом, смотрит не прибавилось ли веса в рюкзаках ваших.*",34769,null],[119880,"2026-07-17T14:51:53",5,"— Я разочарован этой вашей стеной. Кладка красивая, да...\n\n*достал кирпич из рюкзака и показал*\n\n— Но больше ничего ценного. А за ней не лаборатория, а помойка какая-то. Мой друг-троглодит оценил бы, жаль, он ушёл гулять.\n\n*взвесил кирпич в руке*\n\n— Я вижу, вы хотите добычи. Могу только кирпичи предложить. Там ещё остались от стены, но самые красивые я с собой взял. Хотите?",34769,null],[119881,"2026-07-17T14:53:48",9,"Жанка — Значит всё же разрушили. — *Люди начали поднимать оружие, и будто хотели уже напасть. Но жанка подняла руку и остановила их.* — Стоять, а то ещё плмрёт кто-то, у нас и так не хватает рук.",34769,null],[119882,"2026-07-17T14:54:24",11,"Кентавр с девушкой-всадницей стоит немного позади держа в руках оружие",34769,null],[119883,"2026-07-17T14:56:13",41,"--- Простите, а вы были против? Мы не можем почитить, но есть ли шанс возместить?",34769,null],[119884,"2026-07-17T14:57:01",11,"— Насколько я помню они сами указали куда нам идти и были явно не против",119883,null],[119885,"2026-07-17T14:57:44",41,"--- Оу, ну... Это место все равно пустое... Почему тогда оно было таким важным?",119884,null],[119886,"2026-07-17T14:58:01",9,"Жанка — Никаких, но сокровищами положенно делиться. Не мы так кто-то лругой вас ощипает.",34769,null],[119887,"2026-07-17T14:58:03",41,"( Моя нога настроена Их побить",34769,null],[119888,"2026-07-17T14:58:29",5,"// я не могу первый нападать",34769,null],[119889,"2026-07-17T14:58:40",11,"— Да и не похожи они на здешних хозяев — последние слова кентавр произнес так что бы услышала только девушка \n\nСлова о том что некоторые путники исчезали здесь всплыли в его голове. Теперь у него было более логичное объяснение чем Фейские тропы",34769,null],[119890,"2026-07-17T14:58:55",9,"*Похоже глава искателей надумала что-то.*\n\nЖанка — Шныга. Иди проверь что там со стеной. — *После обратилась к героям.* — Надеюсь мы не хотим конфликта и вы пропустите нашего разведчика проверить? Или вы изначально соврали.\n\n*Какой-ти низеньки мужичок полурослик вышел вперёд, шуганный внимательно на вас смотрит, пропустят ли его.*",34769,null],[119891,"2026-07-17T14:59:15",41,"Соль слезла с Иштара и подошла ближе к Жанке\n\n--- Простите, что разрушила стену, но у нас нет сокровищ и странно думать, что этот аргумент нас остановит",119886,null],[119892,"2026-07-17T15:00:18",41,"( могу кинуть запугивание на то как спокойно я говорю о том что сломала ебучую стену?",34769,null],[119893,"2026-07-17T15:00:35",17,"Фауст подходит к Жанке близко смотрит прямо в глаза и качает головой отрицательно\n\n/Запугивание?",119886,null],[119894,"2026-07-17T15:00:49",5,"— Кирпичи там одни, на что смотреть...\n\nГвиндшарх взял в руки и дротик и сравнивает размер с кирпичом",119886,null],[119895,"2026-07-17T15:00:59",41,"( ебашим её",119893,null],[119896,"2026-07-17T15:01:25",17,"/r -1 Надеюсь не запугается и начнётся пиздорез",34769,null],[119898,"2026-07-17T15:01:29",17,"/ блять",34769,null],[119899,"2026-07-17T15:01:31",41,"( ВО ВО",34769,null],[119900,"2026-07-17T15:01:52",41,"( ты так круто молчишь, что аж страшно",119897,null],[119901,"2026-07-17T15:02:18",5,"Дракон отошёл в сторону с дороги, чтобы пропустить эладрина. И ещё немного назад",119893,null],[119902,"2026-07-17T15:03:27",11,"Иштар ждёт действий команды готовый подстроиться в нужный момент.",34769,null],[119903,"2026-07-17T15:05:13",17,"Фауст не страшен внешне, он худой, обожженый доходяга, ну жилистый и чего?\n\nНо рядом можно почувствовать себя холодно. Молчание давит. Иногда даже ком может подступить к горлу. В морозно голубых глазах виднеются острые иглы льда, на ресницах всегда иней, эта маска скрывает, кто знает что она скрывает.\n\nСказать можно только одно, этот эладрин нихуя не шутит",34769,null],[119904,"2026-07-17T15:05:57",11,"// можно сказать что возле тебя всегда холодно :3",119903,null],[119905,"2026-07-17T15:06:04",17,"/ Дыа",34769,null],[119906,"2026-07-17T15:06:11",9,"*Поближе рассмотрев Фауста Жанка кажется впечатлилась, ничего не поменялось, ни змурый взгляд ни стойка, но она просто подняла руки в примирительном жесте.*\n\nЖанка — Ладно, верю. — *Она отошла, махнула своим.* — Сваливаем, здесь ловить нечего.",34769,null],[119907,"2026-07-17T15:06:28",41,"( Давайте ограбим их",34769,null],[119908,"2026-07-17T15:06:44",5,"// это персам не оправдать",34769,null],[119909,"2026-07-17T15:06:56",5,"// спровоцировать можешь",34769,null],[119910,"2026-07-17T15:06:56",41,"( не ну, а че они",34769,null],[119911,"2026-07-17T15:07:05",41,"( че они",34769,null],[119912,"2026-07-17T15:07:05",9,"//Опыта в этом месте за убийства нет, ток ща отыгрыш, но лут это да",34769,null],[119913,"2026-07-17T15:07:18",5,"// и выместить злобу",119912,null],[119914,"2026-07-17T15:07:21",41,"( я уверена, сокровища у них",34769,null],[119915,"2026-07-17T15:07:30",41,"( они просто блефуют",34769,null],[119916,"2026-07-17T15:08:00",41,"( убьем всех кроме полурослика, он нам всё покажет",34769,null],[119917,"2026-07-17T15:08:21",41,"( как жаль, что я на Соли играю",34769,null],[119918,"2026-07-17T15:08:38",5,"// о, я знаю как поиздеваться над жанкой",34769,null],[119919,"2026-07-17T15:08:46",41,"( о, давай давай",34769,null],[119920,"2026-07-17T15:08:54",41,"( буллим жеско",34769,null],[119921,"2026-07-17T15:09:42",5,"— Эй, ты чего такая хмурая? — крикнул дракон Жанке. — А ну-ка улыбнись, не люблю смотреть на угрюмые рожи.\n\nГвиндшарх достал волшебную палочку и направил на Жанку.\n\n// спас харизмы 10",119906,null],[119922,"2026-07-17T15:09:52",11,"// однажды воин с 8 инт попадет на квест где нужно драться, я в это верю",34769,null],[119923,"2026-07-17T15:10:00",41,"(>:D",34769,null],[119924,"2026-07-17T15:10:13",9,"/roll 1d20+1 харизма Жанки )))",34769,null],[119926,"2026-07-17T15:10:20",41,"( УРААААА",34769,null],[119927,"2026-07-17T15:10:35",5,"Цель должна преуспеть в спасброске Харизмы Сл 10, иначе она будет улыбаться 1 минуту.",34769,null],[119928,"2026-07-17T15:10:49",5,"Очень искренняя улыбка появилась на её лице сама собой",34769,null],[119929,"2026-07-17T15:12:30",41,"--- О, она улыбнулась! Хихи, улыбнулась! \n\nКак она это увидела",34769,null],[119930,"2026-07-17T15:12:38",9,"*Её лицо скрывилось в улыбке, она сверкнула недовольным взглядом на того кто указал на неё палочкой, сняла шляпу лучника и прикрыла ею своё лицо, не смотря на улыбку её взгляда зватило чтобы полурослик что успел увилеть улыбку замолчал.*\n\nЖанка — Мы ещё... встретимся...",34769,null],[119931,"2026-07-17T15:13:40",11,"— Боюсь спросить зачем тебе эта палочка, Гвинди..",34769,null],[119932,"2026-07-17T15:14:00",5,"— Заставляю улыбаться вечно недовольных",119931,null],[119933,"2026-07-17T15:14:02",41,"@elsio28 Гвинди респект, план в 10 раз круче моего",34769,null],[119934,"2026-07-17T15:14:11",9,"*Жанка уходит вслед за своими, и посморев последний раз на вас скрылась из часовни. Она запомнила вас.*",34769,null],[119935,"2026-07-17T15:14:26",5,"// затерпела",34769,null],[119936,"2026-07-17T15:14:49",41,"( затерпела первоуровневых",34769,null],[119937,"2026-07-17T15:15:04",11,"// ну мы с драконом 3 и 4",119936,null],[119938,"2026-07-17T15:15:13",41,"( ой",34769,null],[119939,"2026-07-17T15:15:16",41,"( ну",34769,null],[119940,"2026-07-17T15:15:25",41,"( спасибо, что мы выжили",34769,null],[119941,"2026-07-17T15:15:39",9,"Хардинт — Может не стояло их злить. — *Думает, стояло ли жто того, и о том что теперь водить в эти места других стало опаснее.*",34769,null],[119942,"2026-07-17T15:16:20",11,"— Мне кажется от этого она стала только недовольнее.. — кентавр вздохнул и спрятал копьё — Эх, а я надеялся что мои силы наконец-то пригодятся",119932,null],[119943,"2026-07-17T15:16:52",41,"Мокси довольный вышел из укрытия с такой гордостью \"бодая\" воздух, будто это он их прогнал",34769,null],[119944,"2026-07-17T15:16:53",5,"— Эти ребята грабят путников на дорогах, помяните моё слово",119941,null],[119945,"2026-07-17T15:17:03",11,"— Решить проблему бандитов легко, нужно просто устранить их — простого взгляда на проводника хватило что бы понять его мысли",119941,null],[119946,"2026-07-17T15:17:43",9,"Хардинт — Не слишком похожи они на бандитов. Но ладно. Думаю надо уходить.",34769,null],[119947,"2026-07-17T15:17:50",41,"--- Устранить? В их сердце просто нет места покою, а  чрево вечно пусто. Им нужно направление...",119945,null],[119948,"2026-07-17T15:17:53",5,"— Верно мыслишь... Возможно, нам стоит взять инициативу на себя",119945,null],[119949,"2026-07-17T15:18:06",5,"— Если это бандиты конечно",119946,null],[119950,"2026-07-17T15:18:15",11,"— Они хотели нас ограбить, как их ещё назвать? — ответил Иштар сажая Серу на круп",119946,null],[119951,"2026-07-17T15:18:37",11,"— Может и так, леди",119947,null],[119952,"2026-07-17T15:19:15",11,"— Это место для умных, а я себя таковым не считаю, так что и решения принимать не мне — кентавр звучал разочаровано",119948,null],[119953,"2026-07-17T15:19:39",9,"Хардинт — Ладно, может не прав. Там откуда я такое норма. Простите. — *Немного задумался на счет того чтобы пересмотреть своё отношение.*",119950,null],[119954,"2026-07-17T15:19:43",11,"— Впрочем, возможно нам стоит вернуться сюда позже по указке гниляка, Гвинди.. вдруг мы ещё встретим этих ребят",34769,null],[119955,"2026-07-17T15:20:03",11,"// если Юнус захочет",34769,null],[119956,"2026-07-17T15:20:21",5,"— Не говори так, Иштар. Ты не раз проявлял сообразительность!\n\nГвиндшарх хотел похлопать кентавра по плечу, но достал только до Серы и погладил её",119952,null],[119957,"2026-07-17T15:21:08",41,"( Ов",34769,null],[119958,"2026-07-17T15:21:31",5,"— Может и встретим. Гниляк куда-то ушёл, смотрит окрестности думаю. Ему тоже надо сориентироваться",119954,null],[119959,"2026-07-17T15:21:39",41,"--- Это правда. Может мы тоже на что-то способны. Я бы тоже хотела побывать здесь снова...",119956,null],[119960,"2026-07-17T15:23:18",9,"Хардинт — Тогда в путь, сейчас настроен вернуться и хорошо выспаться в таверне перед покружением в работу. А к ней ещё нужно дойти.",34769,null],[119961,"2026-07-17T15:23:30",11,"— Я уверен вы и Фауст явно умнее меня — он неловко почесал затылок — просто сегодня удача не на нашей стороне",119959,null],[119962,"2026-07-17T15:23:40",11,"*кивок*",119960,null],[119963,"2026-07-17T15:24:02",5,"— Было бы, что здесь искать... Пока я увидел лишь руины. А где же обещанные драконы?",119959,null],[119964,"2026-07-17T15:24:20",5,"— Да, пойдём",119960,null],[119965,"2026-07-17T15:24:42",11,"— Так вот же ты — Иштар улыбнулся и без палочки",119963,null],[119966,"2026-07-17T15:25:27",5,"Гвинди улыбнулся и не стал возражать",119965,null],[119967,"2026-07-17T15:26:00",9,"Хардинт — В горах, мы искали ведь не их? Не хотел бы с таким столкнутся, мы вряд-ли справимся даже с одним. — *Немного неловко сказал кое что вслух:* — Я боюсь столкнутся с драконом, признаюсь.",119963,null],[119968,"2026-07-17T15:26:14",41,"Когда речь зашла о драконах, улыбка с лица Соли пропала\n\n--- Здесь их нет...",119963,null],[119969,"2026-07-17T15:26:49",11,"— Драконы разумные создания, уверен что с ними можно договориться",119967,null],[119970,"2026-07-17T15:27:08",5,"— Да, мы пошли с другой целью. Это мой дружок Гниляк рассказывал про драконов в этих горах. Может, он и меня приведёт к ним однажды",119967,null],[119971,"2026-07-17T15:27:57",11,"— Да и здесь должен быть тот кого я ищу — тихо добавил воин",34769,null],[119972,"2026-07-17T15:28:23",11,"— Драконы ведь знают ответы на многие вопросы — громче добавил он",34769,null],[119973,"2026-07-17T15:28:52",9,"Хардинт — О драконах много слышал, но чаще только плохое. А ещё о драконоборцах, те специально охотятся на них как на добычу. Говорят охотники и сами уже не совсем люди.",34769,null],[119974,"2026-07-17T15:29:34",11,"— Я бы не хотел вредить разумным созданиям если они не заслужили того",34769,null],[119975,"2026-07-17T15:30:02",5,"— Не знаю, где его найти, но спрашивать могущественных существ будет не лишним. Если цена не слишком велика.",119972,null],[119976,"2026-07-17T15:31:15",11,"— Всё так, брат",34769,null],[119977,"2026-07-17T15:35:01",9,"*Так и не найдя стоящих сокровищ герои закончили поход. Обратный путь прошёл без приключений, через леса, цветочные поля, горный переход.*\n\n*Цветы все так же стелились полями под ногами, горы величественно взирали и молча провожали путников.*",34769,null],[119978,"2026-07-17T15:36:12",9,"//Запишите себе по 10 золотых и магнитный камень с лаборатории если не взяли:\n\n\"Чёрный магнитный камень в форме яйца\"\n\nОбычный чудесный предмет. Магнитится к металлу, гладкий.",34769,null],[119979,"2026-07-17T15:36:21",9,"//Спишите по 2 рациона",34769,null],[119980,"2026-07-17T15:37:09",41,"ничо не знаю, Соль шашлык доедает",34769,null],[119981,"2026-07-17T15:37:18",9,"//Опыт: \nВсем по 100\nГвиди 150, отлично раздраконил Жанку, та едва с улыбкой вас не решила порвать\nХардинт как перс ведущего 20 опыта",34769,null],[119982,"2026-07-17T15:37:28",17,"Фауст положил на плечо руку и покачал головой мол \"нет\" улыбнулся глазами",119961,null],[119983,"2026-07-17T15:38:06",9,"//Ягнёнка можете сьёсть или оставить, решай сама)",119980,null],[119984,"2026-07-17T15:38:54",41,"Ну он теперь мой сын, нет(",119983,null],[119985,"2026-07-17T15:39:38",9,"//Если хотите ещё повзаемодействовать, я в таверну перемещаюсь)",34769,null],[119987,"2026-07-17T15:41:15",17,"/ Работы много, сори я сегодня малоактивный",34769,null],[119988,"2026-07-17T15:42:19",41,"Спасибо за квест!",34769,null],[119989,"2026-07-17T15:43:32",11,"Спасибо за квест",34769,null],[119990,"2026-07-17T15:45:34",9,"//Хотя бы 2й лвл взяли, простите за квест! ^^",34769,null],[182482,"2026-08-31T18:10:38",9,"//Руины будут ребрендированны в связи с тем что появилась новая идея как по другому реализовать данную локацию. Ожидайте, локация изменится после ярмарки.",34769,null]]);
